<?php

$input = file_get_contents("php://stdin");
$length = strlen($input);
$position = 0;

function nextInt(): int
{
    global $input, $length, $position;

    while ($position < $length) {
        $c = ord($input[$position]);
        if ($c > 32) {
            break;
        }
        $position++;
    }

    $number = 0;
    while ($position < $length) {
        $c = ord($input[$position]);
        if ($c < 48 || $c > 57) {
            break;
        }
        $number = $number * 10 + ($c - 48);
        $position++;
    }

    return $number;
}

$t = nextInt();
$answers = [];

for ($case = 0; $case < $t; $case++) {
    $n = nextInt();
    $k = nextInt();

    $minimum = PHP_INT_MAX;
    $evenCount = 0;

    for ($i = 0; $i < $n; $i++) {
        $value = nextInt();

        $operations = ($k - ($value % $k)) % $k;
        if ($operations < $minimum) {
            $minimum = $operations;
        }

        if (($value & 1) === 0) {
            $evenCount++;
        }
    }

    if ($k === 4) {
        if ($evenCount >= 2) {
            $twoFactorCost = 0;
        } elseif ($evenCount === 1) {
            $twoFactorCost = 1;
        } else {
            $twoFactorCost = 2;
        }

        $minimum = min($minimum, $twoFactorCost);
    }

    $answers[] = (string)$minimum;
}

echo implode("\n", $answers);
?>
