function nextInt(string $data, int &$index, int $length): int
{
    while ($index < $length && ord($data[$index]) <= 32) {
        $index++;
    }

    $sign = 1;
    if ($data[$index] === '-') {
        $sign = -1;
        $index++;
    }

    $number = 0;
    while ($index < $length) {
        $code = ord($data[$index]);
        if ($code < 48 || $code > 57) {
            break;
        }
        $number = $number * 10 + ($code - 48);
        $index++;
    }

    return $number * $sign;
}

$input = file_get_contents('php://stdin');
$length = strlen($input);
$index = 0;

$t = nextInt($input, $index, $length);
$answers = [];

for ($case = 0; $case < $t; $case++) {
    $n = nextInt($input, $index, $length);

    $previous = nextInt($input, $index, $length);
    $currentSum = $previous;
    $maximumSum = $previous;

    for ($i = 1; $i < $n; $i++) {
        $value = nextInt($input, $index, $length);

        if (($value & 1) !== ($previous & 1)) {
            $currentSum = max($value, $currentSum + $value);
        } else {
            $currentSum = $value;
        }

        $maximumSum = max($maximumSum, $currentSum);
        $previous = $value;
    }

    $answers[] = (string)$maximumSum;
}

echo implode("\n", $answers);
