<?php

const MOD = 1000000007;

$tokens = preg_split('/\s+/', trim(stream_get_contents(STDIN)));

$num1 = $tokens[0];
$num2 = $tokens[1];
$minSum = (int)$tokens[2];
$maxSum = (int)$tokens[3];

function decrementString(string $number): string
{
    $digits = str_split($number);
    $i = count($digits) - 1;

    while ($i >= 0 && $digits[$i] === '0') {
        $digits[$i] = '9';
        $i--;
    }

    if ($i >= 0) {
        $digits[$i] = chr(ord($digits[$i]) - 1);
    }

    $result = ltrim(implode('', $digits), '0');
    return $result === '' ? '0' : $result;
}

function countGoodUpTo(string $bound, int $minSum, int $maxSum): int
{
    $tight = array_fill(0, $maxSum + 1, 0);
    $loose = array_fill(0, $maxSum + 1, 0);
    $tight[0] = 1;

    $length = strlen($bound);

    for ($position = 0; $position < $length; $position++) {
        $limit = ord($bound[$position]) - 48;
        $nextTight = array_fill(0, $maxSum + 1, 0);
        $nextLoose = array_fill(0, $maxSum + 1, 0);

        for ($sum = 0; $sum <= $maxSum; $sum++) {
            if ($tight[$sum] !== 0) {
                $ways = $tight[$sum];

                for ($digit = 0; $digit <= $limit && $sum + $digit <= $maxSum; $digit++) {
                    $newSum = $sum + $digit;

                    if ($digit === $limit) {
                        $nextTight[$newSum] = ($nextTight[$newSum] + $ways) % MOD;
                    } else {
                        $nextLoose[$newSum] = ($nextLoose[$newSum] + $ways) % MOD;
                    }
                }
            }

            if ($loose[$sum] !== 0) {
                $ways = $loose[$sum];
                $maxDigit = min(9, $maxSum - $sum);

                for ($digit = 0; $digit <= $maxDigit; $digit++) {
                    $newSum = $sum + $digit;
                    $nextLoose[$newSum] = ($nextLoose[$newSum] + $ways) % MOD;
                }
            }
        }

        $tight = $nextTight;
        $loose = $nextLoose;
    }

    $answer = 0;

    for ($sum = $minSum; $sum <= $maxSum; $sum++) {
        $answer = ($answer + $tight[$sum] + $loose[$sum]) % MOD;
    }

    return $answer;
}

$beforeNum1 = decrementString($num1);
$answer = (countGoodUpTo($num2, $minSum, $maxSum)
    - countGoodUpTo($beforeNum1, $minSum, $maxSum)
    + MOD) % MOD;

echo $answer, PHP_EOL;
