<?php

function canPartition(string $digits, int $target, int $position, int $sum, array &$memo): bool
{
    $length = strlen($digits);

    if ($position === $length) {
        return $sum === $target;
    }

    $key = $position . ':' . $sum;
    if (isset($memo[$key])) {
        return $memo[$key];
    }

    $value = 0;

    for ($end = $position; $end < $length; $end++) {
        $value = $value * 10 + (ord($digits[$end]) - 48);

        if ($sum + $value > $target) {
            break;
        }

        if (canPartition($digits, $target, $end + 1, $sum + $value, $memo)) {
            return $memo[$key] = true;
        }
    }

    return $memo[$key] = false;
}

$input = trim(stream_get_contents(STDIN));
preg_match('/\d+/', $input, $matches);
$n = (int)$matches[0];

$punishmentNumber = 0;

for ($i = 1; $i <= $n; $i++) {
    $square = $i * $i;
    $memo = [];

    if (canPartition((string)$square, $i, 0, 0, $memo)) {
        $punishmentNumber += $square;
    }
}

echo $punishmentNumber;
?>
