    while ($parent[$root] !== $root) {
        $root = $parent[$root];
    }

    while ($parent[$x] !== $x) {
        $next = $parent[$x];
        $parent[$x] = $root;
        $x = $next;
    }

    return $root;
}

function unionSets(array &$parent, array &$size, int $a, int $b): void
{
    $rootA = findRoot($parent, $a);
    $rootB = findRoot($parent, $b);

    if ($rootA === $rootB) {
        return;
    }

    if ($size[$rootA] < $size[$rootB]) {
        [$rootA, $rootB] = [$rootB, $rootA];
    }

    $parent[$rootB] = $rootA;
    $size[$rootA] += $size[$rootB];
}

$maxValue = max($nums);
$limit = (int)floor(sqrt($maxValue));
$isPrime = array_fill(0, $limit + 1, true);

if ($limit >= 0) {
    $isPrime[0] = false;
}
if ($limit >= 1) {
    $isPrime[1] = false;
}

$primes = [];

for ($i = 2; $i <= $limit; $i++) {
    if (!$isPrime[$i]) {
        continue;
    }

    $primes[] = $i;

    if ($i * $i <= $limit) {
        for ($multiple = $i * $i; $multiple <= $limit; $multiple += $i) {
            $isPrime[$multiple] = false;
        }
    }
}

