<?php

final class FastScanner
{
    private string $data;
    private int $length;
    private int $position = 0;

    public function __construct()
    {
        $this->data = file_get_contents('php://stdin');
        $this->length = strlen($this->data);
    }

    public function nextInt(): ?int
    {
        while ($this->position < $this->length) {
            $c = ord($this->data[$this->position]);
            if ($c > 32) {
                break;
            }
            $this->position++;
        }

        if ($this->position >= $this->length) {
            return null;
        }

        $sign = 1;
        if ($this->data[$this->position] === '-') {
            $sign = -1;
            $this->position++;
        }

        $number = 0;
        while ($this->position < $this->length) {
            $c = ord($this->data[$this->position]);
            if ($c < 48 || $c > 57) {
                break;
            }
            $number = $number * 10 + ($c - 48);
            $this->position++;
        }

        return $number * $sign;
    }
}

$scanner = new FastScanner();

$n = $scanner->nextInt();
$logCount = $scanner->nextInt();

$logFactor = $n + 1;
$logs = [];

for ($i = 0; $i < $logCount; $i++) {
    $serverId = $scanner->nextInt();
    $time = $scanner->nextInt();
    $logs[] = $time * $logFactor + $serverId;
}

$x = $scanner->nextInt();

$queryValues = [];
while (($query = $scanner->nextInt()) !== null) {
    $queryValues[] = $query;
}

sort($logs, SORT_NUMERIC);

$queryCount = count($queryValues);
$queryFactor = $queryCount + 1;
$sortedQueries = [];

for ($i = 0; $i < $queryCount; $i++) {
    $sortedQueries[] = $queryValues[$i] * $queryFactor + $i;
}

sort($sortedQueries, SORT_NUMERIC);

$frequencies = array_fill(0, $n + 1, 0);
$answers = array_fill(0, $queryCount, 0);

$left = 0;
$right = 0;
$activeServers = 0;

foreach ($sortedQueries as $encodedQuery) {
    $queryTime = intdiv($encodedQuery, $queryFactor);
    $originalIndex = $encodedQuery % $queryFactor;
    $minimumTime = $queryTime - $x;

    while ($right < $logCount) {
        $logTime = intdiv($logs[$right], $logFactor);
        if ($logTime > $queryTime) {
            break;
        }

        $serverId = $logs[$right] % $logFactor;
        if ($frequencies[$serverId] === 0) {
            $activeServers++;
        }
        $frequencies[$serverId]++;
        $right++;
    }

    while ($left < $right) {
        $logTime = intdiv($logs[$left], $logFactor);
        if ($logTime >= $minimumTime) {
            break;
        }

        $serverId = $logs[$left] % $logFactor;
        $frequencies[$serverId]--;
        if ($frequencies[$serverId] === 0) {
            $activeServers--;
        }
        $left++;
    }

    $answers[$originalIndex] = $n - $activeServers;
}

echo implode(' ', $answers), PHP_EOL;
