function readNonEmptyLine(): string
{
    while (($line = fgets(STDIN)) !== false) {
        if (trim($line) !== '') {
            return $line;
        }
    }
    return '';
}

function parseIntegers(string $line): array
{
    $numbers = [];
    $length = strlen($line);
    $i = 0;

    while ($i < $length) {
        while ($i < $length && ($line[$i] < '0' || $line[$i] > '9') && $line[$i] !== '-') {
            $i++;
        }

        if ($i >= $length) {
            break;
        }

        $sign = 1;
        if ($line[$i] === '-') {
            $sign = -1;
            $i++;
        }

        $value = 0;
        while ($i < $length && $line[$i] >= '0' && $line[$i] <= '9') {
            $value = $value * 10 + (ord($line[$i]) - 48);
            $i++;
        }

        $numbers[] = $value * $sign;
    }

    return $numbers;
}

function lowerBound(array &$values, int $target, int $size): int
{
    $left = 0;
    $right = $size;

    while ($left < $right) {
        $mid = intdiv($left + $right, 2);
        if ($values[$mid] < $target) {
            $left = $mid + 1;
        } else {
            $right = $mid;
        }
    }

    return $left;
}

$nums1 = parseIntegers(readNonEmptyLine());
$nums2 = parseIntegers(readNonEmptyLine());
$n = count($nums1);

$queryCountLine = parseIntegers(readNonEmptyLine());
$queryCount = $queryCountLine[0];

$queryX = [];
$queryY = [];
$queryIds = [];

for ($i = 0; $i < $queryCount; $i++) {
    $query = parseIntegers(readNonEmptyLine());
    $queryX[] = $query[0];
    $queryY[] = $query[1];
    $queryIds[] = $i;
}

array_multisort(
    $nums1, SORT_DESC, SORT_NUMERIC,
    $nums2, SORT_DESC, SORT_NUMERIC
);

array_multisort(
    $queryX, SORT_DESC, SORT_NUMERIC,
    $queryY, SORT_DESC, SORT_NUMERIC,
    $queryIds, SORT_ASC, SORT_NUMERIC
);

$coordinates = $nums2;
sort($coordinates, SORT_NUMERIC);

$fenwick = array_fill(0, $n + 1, -1);
$answers = array_fill(0, $queryCount, -1);
$pointIndex = 0;

for ($i = 0; $i < $queryCount; $i++) {
    $minimumX = $queryX[$i];

    while ($pointIndex < $n && $nums1[$pointIndex] >= $minimumX) {
        $position = lowerBound($coordinates, $nums2[$pointIndex], $n);
        $fenwickIndex = $n - $position;
        $sum = $nums1[$pointIndex] + $nums2[$pointIndex];

        while ($fenwickIndex <= $n) {
            if ($sum > $fenwick[$fenwickIndex]) {
                $fenwick[$fenwickIndex] = $sum;
            }
            $fenwickIndex += $fenwickIndex & (-$fenwickIndex);
        }

        $pointIndex++;
    }

    $position = lowerBound($coordinates, $queryY[$i], $n);
    $fenwickIndex = $n - $position;
    $best = -1;

    while ($fenwickIndex > 0) {
