$compatible = array_fill(0, $n, array_fill(0, $n, false));

for ($i = 0; $i < $n; $i++) {
    for ($j = 0; $j < $n; $j++) {
        if ($i !== $j && (
            $nums[$i] % $nums[$j] === 0 ||
            $nums[$j] % $nums[$i] === 0
        )) {
            $compatible[$i][$j] = true;
        }
    }
}

$totalMasks = 1 << $n;
$dp = array_fill(0, $totalMasks * $n, 0);

for ($i = 0; $i < $n; $i++) {
    $dp[((1 << $i) * $n) + $i] = 1;
}

for ($mask = 1; $mask < $totalMasks; $mask++) {
    for ($last = 0; $last < $n; $last++) {
        $lastBit = 1 << $last;
        if (($mask & $lastBit) === 0) {
            continue;
        }

        $previousMask = $mask ^ $lastBit;
        if ($previousMask === 0) {
            continue;
        }

        $ways = 0;
        $baseIndex = $previousMask * $n;

        for ($previous = 0; $previous < $n; $previous++) {
            if (
                ($previousMask & (1 << $previous)) !== 0 &&
                $compatible[$previous][$last]
            ) {
                $ways += $dp[$baseIndex + $previous];
            }
        }

        $dp[($mask * $n) + $last] = $ways % MOD;
    }
}

$fullMask = $totalMasks - 1;
$answer = 0;
$baseIndex = $fullMask * $n;

for ($last = 0; $last < $n; $last++) {
    $answer = ($answer + $dp[$baseIndex + $last]) % MOD;
}

echo $answer . PHP_EOL;
