<?php

const MOD = 1000000007;

function countSteppingAtMost(string $bound): int
{
    // Previous digit 0-9; state 10 means no non-leading-zero digit yet.
    $dp = [
        array_fill(0, 11, 0),
        array_fill(0, 11, 0)
    ];
    $dp[1][10] = 1;

    $length = strlen($bound);

    for ($position = 0; $position < $length; $position++) {
        $boundDigit = ord($bound[$position]) - 48;
        $next = [
            array_fill(0, 11, 0),
            array_fill(0, 11, 0)
        ];

        for ($tight = 0; $tight <= 1; $tight++) {
            $limit = $tight === 1 ? $boundDigit : 9;

            for ($previous = 0; $previous <= 10; $previous++) {
                $ways = $dp[$tight][$previous];
                if ($ways === 0) {
                    continue;
                }

                for ($digit = 0; $digit <= $limit; $digit++) {
                    $newTight = ($tight === 1 && $digit === $boundDigit) ? 1 : 0;

                    if ($previous === 10) {
                        $newPrevious = ($digit === 0) ? 10 : $digit;
                    } else {
                        if (abs($previous - $digit) !== 1) {
                            continue;
                        }
                        $newPrevious = $digit;
                    }

                    $next[$newTight][$newPrevious] =
                        ($next[$newTight][$newPrevious] + $ways) % MOD;
                }
            }
        }

        $dp = $next;
    }

    $count = 0;
    for ($tight = 0; $tight <= 1; $tight++) {
        for ($previous = 0; $previous <= 9; $previous++) {
            $count = ($count + $dp[$tight][$previous]) % MOD;
        }
    }

    return $count;
}

function decrementDecimalString(string $number): string
{
    $index = strlen($number) - 1;

    while ($index >= 0 && $number[$index] === '0') {
        $number[$index] = '9';
        $index--;
    }

    if ($index >= 0) {
        $number[$index] = chr(ord($number[$index]) - 1);
    }

    $number = ltrim($number, '0');
    return $number === '' ? '0' : $number;
}

$input = trim(stream_get_contents(STDIN));
$values = preg_split('/\s+/', $input);

$low = $values[0];
$high = $values[1];

$highCount = countSteppingAtMost($high);
$beforeLowCount = countSteppingAtMost(decrementDecimalString($low));

$answer = ($highCount - $beforeLowCount + MOD) % MOD;
echo $answer . PHP_EOL;
