<?php

final class FastScanner
{
    private string $data;
    private int $index = 0;
    private int $length;

    public function __construct()
    {
        $this->data = file_get_contents('php://stdin');
        $this->length = strlen($this->data);
    }

    public function nextInt(): int
    {
        while ($this->index < $this->length) {
            $c = ord($this->data[$this->index]);
            if ($c > 32) {
                break;
            }
            $this->index++;
        }

        $number = 0;
        while ($this->index < $this->length) {
            $c = ord($this->data[$this->index]);
            if ($c < 48 || $c > 57) {
                break;
            }
            $number = $number * 10 + ($c - 48);
            $this->index++;
        }

        return $number;
    }
}

$scanner = new FastScanner();

$n = $scanner->nextInt();
$offerCount = $scanner->nextInt();

$head = array_fill(0, $n, -1);
$starts = [];
$golds = [];
$next = [];

for ($i = 0; $i < $offerCount; $i++) {
    $start = $scanner->nextInt();
    $end = $scanner->nextInt();
    $gold = $scanner->nextInt();

    $starts[$i] = $start;
    $golds[$i] = $gold;
    $next[$i] = $head[$end];
    $head[$end] = $i;
}

$dp = [0];

for ($house = 0; $house < $n; $house++) {
    $best = $dp[$house];

    for ($offer = $head[$house]; $offer !== -1; $offer = $next[$offer]) {
        $candidate = $dp[$starts[$offer]] + $golds[$offer];
        if ($candidate > $best) {
            $best = $candidate;
        }
    }

    $dp[$house + 1] = $best;
}

echo $dp[$n], PHP_EOL;
