        if ($next <= $m && $bit[$next] < $k) {
            $index = $next;
            $k -= $bit[$next];
        }
    }
    return $index + 1;
};

$answer = PHP_INT_MAX;
$totalInserted = 0;

for ($i = $x; $i < $n; $i++) {
    $add($rank[$nums[$i - $x]]);
    $totalInserted++;

    $current = $nums[$i];
    $currentRank = $rank[$current];

    $countAtOrBelow = $prefixSum($currentRank);
    if ($countAtOrBelow > 0) {
        $predecessorRank = $kth($countAtOrBelow);
        $answer = min($answer, $current - $unique[$predecessorRank - 1]);
    }

    $countBelow = $prefixSum($currentRank - 1);
    if ($countBelow < $totalInserted) {
        $successorRank = $kth($countBelow + 1);
        $answer = min($answer, $unique[$successorRank - 1] - $current);
    }

    if ($answer === 0) {
        break;
    }
}

echo $answer . PHP_EOL;
