<?php

const MOD = 1000000007;

function modPow(int $base, int $exp): int
{
    $result = 1;
    $base %= MOD;

    while ($exp > 0) {
        if (($exp & 1) === 1) {
            $result = ($result * $base) % MOD;
        }
        $base = ($base * $base) % MOD;
        $exp = intdiv($exp, 2);
    }

    return $result;
}

$s = trim(fgets(STDIN));
$t = trim(fgets(STDIN));
$k = (int) trim(fgets(STDIN));

$n = strlen($s);

// Build the KMP prefix table for t.
$prefix = array_fill(0, $n, 0);
for ($i = 1, $j = 0; $i < $n; $i++) {
    while ($j > 0 && $t[$i] !== $t[$j]) {
        $j = $prefix[$j - 1];
    }

    if ($t[$i] === $t[$j]) {
        $j++;
    }

    $prefix[$i] = $j;
}

// Count cyclic rotations of s equal to t.
$text = $s . substr($s, 0, $n - 1);
$textLength = strlen($text);
$matchingRotations = 0;

for ($i = 0, $j = 0; $i < $textLength; $i++) {
    while ($j > 0 && $text[$i] !== $t[$j]) {
        $j = $prefix[$j - 1];
    }

    if ($text[$i] === $t[$j]) {
        $j++;
    }

    if ($j === $n) {
        $matchingRotations++;
        $j = $prefix[$j - 1];
    }
}

$power = modPow($n - 1, $k);
$sign = ($k % 2 === 0) ? 1 : MOD - 1;

$inverseN = modPow($n, MOD - 2);
$nonZeroRotationWays = (($power - $sign + MOD) % MOD * $inverseN) % MOD;

$answer = (($matchingRotations % MOD) * $nonZeroRotationWays) % MOD;

if ($s === $t) {
    $answer = ($answer + $sign) % MOD;
}

echo $answer . PHP_EOL;
