$position = range(0, $n - 1);
$total = range(0, $n - 1);

$remaining = $k;

while ($remaining > 0) {
    if (($remaining & 1) === 1) {
        for ($i = 0; $i < $n; $i++) {
            $current = $position[$i];
            $total[$i] += $gain[$current];
            $position[$i] = $jump[$current];
        }
    }

    $remaining >>= 1;
    if ($remaining === 0) {
        break;
    }

    $nextJump = [];
    $nextGain = [];

    for ($i = 0; $i < $n; $i++) {
        $middle = $jump[$i];
        $nextJump[] = $jump[$middle];
        $nextGain[] = $gain[$i] + $gain[$middle];
    }

    $jump = $nextJump;
    $gain = $nextGain;
}

$answer = $total[0];
