    $removedOffset = ($count + 1) * $value;

    for ($sum = 0; $sum <= $r; $sum++) {
        $ways = $dp[$sum];

        if ($sum >= $value) {
            $ways += $next[$sum - $value];
            if ($ways >= $mod) {
                $ways -= $mod;
            }
        }

        if ($sum >= $removedOffset) {
            $ways -= $dp[$sum - $removedOffset];
            if ($ways < 0) {
                $ways += $mod;
            }
        }

        $next[$sum] = $ways;
    }

    $dp = $next;
}

