function lowerBound(array &$array, int $target): int
{
    $left = 0;
    $right = count($array);

    while ($left < $right) {
        $middle = $left + intdiv($right - $left, 2);

        if ($array[$middle] < $target) {
            $left = $middle + 1;
        } else {
            $right = $middle;
        }
    }

    return $left;
}

foreach ($keys as $index => $key) {
    $position = lowerBound($sorted, $key) + 1;

    $bestPrevious = 0;
    for ($i = $position; $i > 0; $i -= $i & (-$i)) {
        if ($fenwick[$i] > $bestPrevious) {
            $bestPrevious = $fenwick[$i];
        }
    }

    $value = $key + $index;
    $currentSum = $value + $bestPrevious;

    if ($currentSum > $answer) {
        $answer = $currentSum;
    }

    for ($i = $position; $i <= $n; $i += $i & (-$i)) {
        if ($currentSum > $fenwick[$i]) {
            $fenwick[$i] = $currentSum;
