<?php

function nextInt(string $data, int &$pos, int $length): int
{
    while ($pos < $length && ord($data[$pos]) <= 32) {
        ++$pos;
    }

    $value = 0;
    while ($pos < $length) {
        $code = ord($data[$pos]);
        if ($code < 48 || $code > 57) {
            break;
        }
        $value = $value * 10 + ($code - 48);
        ++$pos;
    }

    return $value;
}

$s = trim((string)fgets(STDIN));
$n = strlen($s);
$m = intdiv($n, 2);

$left = substr($s, 0, $m);
$right = strrev(substr($s, $m));

/*
 * Each prefix entry contains:
 *   indices 1..26  : character counts in the left half
 *   indices 27..52 : character counts in the reversed right half
 *
 * Counts fit into unsigned 16-bit integers because m <= 50000.
 */
$counts = array_fill(0, 52, 0);
$prefixBlob = pack('v*', ...$counts);

$mismatchPrefix = [0];

for ($i = 0; $i < $m; ++$i) {
    $leftCode = ord($left[$i]) - 97;
    $rightCode = ord($right[$i]) - 97;

    ++$counts[$leftCode];
    ++$counts[26 + $rightCode];

    $prefixBlob .= pack('v*', ...$counts);
    $mismatchPrefix[] = $mismatchPrefix[$i] + ($left[$i] !== $right[$i] ? 1 : 0);
}

$totalMismatches = $mismatchPrefix[$m];
$entrySize = 104; // 52 unsigned 16-bit integers

$data = stream_get_contents(STDIN);
$pos = 0;
$dataLength = strlen($data);
$queryCount = nextInt($data, $pos, $dataLength);

$answers = [];

for ($queryIndex = 0; $queryIndex < $queryCount; ++$queryIndex) {
    $a = nextInt($data, $pos, $dataLength);
    $b = nextInt($data, $pos, $dataLength);
    $c = nextInt($data, $pos, $dataLength);
    $d = nextInt($data, $pos, $dataLength);

    // Map the interval in the original right half into the reversed right half.
    $l = $n - 1 - $d;
    $r = $n - 1 - $c;

    $bExclusive = $b + 1;
    $rExclusive = $r + 1;

    $overlapStart = max($a, $l);
    $overlapEnd = min($bExclusive, $rExclusive);
    $hasOverlap = $overlapStart < $overlapEnd;

    $unionMismatches =
        ($mismatchPrefix[$bExclusive] - $mismatchPrefix[$a]) +
        ($mismatchPrefix[$rExclusive] - $mismatchPrefix[$l]);

    if ($hasOverlap) {
        $unionMismatches -=
            $mismatchPrefix[$overlapEnd] - $mismatchPrefix[$overlapStart];
    }

    // Every mismatch outside both rearrangeable intervals is unchangeable.
    if ($unionMismatches !== $totalMismatches) {
        $answers[] = 'false';
        continue;
    }

    $prefixA = unpack('v52', $prefixBlob, $a * $entrySize);
    $prefixB = unpack('v52', $prefixBlob, $bExclusive * $entrySize);

    if ($l === $a) {
        $prefixL = $prefixA;
    } elseif ($l === $bExclusive) {
        $prefixL = $prefixB;
    } else {
        $prefixL = unpack('v52', $prefixBlob, $l * $entrySize);
    }

    if ($rExclusive === $a) {
        $prefixR = $prefixA;
    } elseif ($rExclusive === $bExclusive) {
        $prefixR = $prefixB;
    } elseif ($rExclusive === $l) {
        $prefixR = $prefixL;
    } else {
        $prefixR = unpack('v52', $prefixBlob, $rExclusive * $entrySize);
    }

    if ($hasOverlap) {
        $overlapPrefixStart = ($a >= $l) ? $prefixA : $prefixL;
        $overlapPrefixEnd = ($bExclusive <= $rExclusive) ? $prefixB : $prefixR;
    }

    $possible = true;

    for ($character = 1; $character <= 26; ++$character) {
        $rightCharacter = $character + 26;

        $leftPool = $prefixB[$character] - $prefixA[$character];
        $rightPool = $prefixR[$rightCharacter] - $prefixL[$rightCharacter];

        $rightNeededOutsideOverlap =
            $prefixB[$rightCharacter] - $prefixA[$rightCharacter];

        $leftNeededOutsideOverlap =
            $prefixR[$character] - $prefixL[$character];

        $leftOverlapCount = 0;
        $rightOverlapCount = 0;

        if ($hasOverlap) {
            $leftOverlapCount =
                $overlapPrefixEnd[$character] - $overlapPrefixStart[$character];
            $rightOverlapCount =
                $overlapPrefixEnd[$rightCharacter] - $overlapPrefixStart[$rightCharacter];
        }

        $leftRemaining =
            $leftPool - $rightNeededOutsideOverlap + $rightOverlapCount;

        $rightRemaining =
            $rightPool - $leftNeededOutsideOverlap + $leftOverlapCount;

        if (
            $leftRemaining < 0 ||
            $rightRemaining < 0 ||
            $leftRemaining !== $rightRemaining
        ) {
            $possible = false;
            break;
        }
    }

    $answers[] = $possible ? 'true' : 'false';
}

echo implode(' ', $answers), PHP_EOL;
