```php
<?php

$tokens = preg_split('/\s+/', trim(stream_get_contents(STDIN)));
$s = $tokens[0];
$k = (int)$tokens[1];
$n = strlen($s);

if ($k === 26) {
    echo "1\n";
    exit;
}

$chars = [];
$bits = [];
for ($c = 0; $c < 26; $c++) {
    $bits[$c] = 1 << $c;
}

$occurrences = [];
for ($c = 0; $c < 26; $c++) {
    $occurrences[$c] = [];
}

for ($i = 0; $i < $n; $i++) {
    $c = ord($s[$i]) - 97;
    $chars[$i] = $c;
    $occurrences[$c][] = $i;
}

/*
 * suffixPartitions[i] is the number of greedy partitions needed
 * for the suffix starting at i.
 */
$nextBoundary = array_fill(0, $n, $n);
$windowCounts = array_fill(0, 26, 0);
$distinct = 0;
$right = 0;

for ($left = 0; $left < $n; $left++) {
    while ($right < $n) {
        $c = $chars[$right];
        if ($windowCounts[$c] === 0 && $distinct === $k) {
            break;
        }

        if ($windowCounts[$c] === 0) {
            $distinct++;
        }
        $windowCounts[$c]++;
        $right++;
    }

    $nextBoundary[$left] = $right;

    $leftChar = $chars[$left];
    $windowCounts[$leftChar]--;
    if ($windowCounts[$leftChar] === 0) {
        $distinct--;
    }
}

$suffixPartitions = array_fill(0, $n + 1, 0);
for ($i = $n - 1; $i >= 0; $i--) {
    $suffixPartitions[$i] = 1 + $suffixPartitions[$nextBoundary[$i]];
}

/*
 * Maintain the first occurrence of each letter strictly after
 * the current position.
 */
$pointers = array_fill(0, 26, 0);
$nextPosition = array_fill(0, 26, $n);

for ($c = 0; $c < 26; $c++) {
    if (!empty($occurrences[$c])) {
        $nextPosition[$c] = $occurrences[$c][0];
    }
}

$answer = 1;
$currentMask = 0;
$currentDistinct = 0;
$completedPartitions = 0;

for ($i = 0; $i < $n; $i++) {
    $original = $chars[$i];

    // Move the current character out of the future-occurrence structure.
    $pointers[$original]++;
    if ($pointers[$original] < count($occurrences[$original])) {
        $nextPosition[$original] = $occurrences[$original][$pointers[$original]];
    } else {
        $nextPosition[$original] = $n;
    }

    // Letters ordered by their first occurrence after i.
    $orderedNext = $nextPosition;
    asort($orderedNext, SORT_NUMERIC);

    for ($replacement = 0; $replacement < 26; $replacement++) {
        $replacementBit = $bits[$replacement];
        $alreadyPresent = (($currentMask & $replacementBit) !== 0);
        $newDistinct = $currentDistinct + ($alreadyPresent ? 0 : 1);

        if ($newDistinct <= $k) {
            /*
             * The changed character remains in the current partition.
             * Find the first future character that makes its distinct
             * count exceed k.
             */
            $newMask = $currentMask | $replacementBit;
            $needed = $k - $newDistinct + 1;
            $boundary = $n;

            foreach ($orderedNext as $letter => $position) {
                if (($newMask & $bits[$letter]) !== 0) {
                    continue;
                }

                if ($position >= $n) {
                    break;
                }

                $needed--;
                if ($needed === 0) {
                    $boundary = $position;
                    break;
                }
            }

            $partitions = $completedPartitions
                        + 1
                        + $suffixPartitions[$boundary];
        } else {
            /*
             * Changing s[i] immediately closes the current partition.
             * A new partition starts at i with the replacement letter.
             */
            $needed = $k;
            $boundary = $n;

            foreach ($orderedNext as $letter => $position) {
                if ($letter === $replacement) {
                    continue;
                }

                if ($position >= $n) {
                    break;
                }

                $needed--;
                if ($needed === 0) {
                    $boundary = $position;
                    break;
                }
            }

            $partitions = $completedPartitions
                        + 2
                        + $suffixPartitions[$boundary];
        }

        if ($partitions > $answer) {
            $answer = $partitions;
        }
    }

    // Advance the unchanged string's greedy partition state.
    $originalBit = $bits[$original];

    if (($currentMask & $originalBit) === 0) {
        if ($currentDistinct === $k) {
            $completedPartitions++;
            $currentMask = $originalBit;
            $currentDistinct = 1;
        } else {
            $currentMask |= $originalBit;
            $currentDistinct++;
        }
    }
}

echo $answer . "\n";
