$x = (int)$matches[0][1];

function isAffordable(int $num, int $k, int $x): bool
{
    $totalNumbers = $num + 1; // Count numbers from 0 through $num.
    $halfCycle = 1 << ($x - 1);
    $step = 1 << $x;
    $sum = 0;

    while ($halfCycle < $totalNumbers) {
        $cycleLength = $halfCycle * 2;

        $fullCycles = intdiv($totalNumbers, $cycleLength);
        $ones = $fullCycles * $halfCycle;

        $remainder = $totalNumbers % $cycleLength;
        if ($remainder > $halfCycle) {
            $ones += $remainder - $halfCycle;
        }

        if ($ones > $k - $sum) {
            return false;
        }
        $sum += $ones;

        if ($halfCycle > intdiv($totalNumbers, $step)) {
            break;
        }
        $halfCycle *= $step;
    }

    return true;
}

$low = 0;
$high = 1;

while (isAffordable($high, $k, $x)) {
    $low = $high;
    $high *= 2;
}

while ($low + 1 < $high) {
    $mid = $low + intdiv($high - $low, 2);

    if (isAffordable($mid, $k, $x)) {
        $low = $mid;
    } else {
        $high = $mid;
    }
}

