```php
<?php

$input = trim(stream_get_contents(STDIN));
$tokens = preg_split('/\s+/', $input);

$start = (int)$tokens[0];
$finish = (int)$tokens[1];
$limit = (int)$tokens[2];
$suffix = $tokens[3];

function countPowerfulUpTo(int $bound, int $limit, string $suffix): int
{
    if ($bound <= 0) {
        return 0;
    }

    $boundString = (string)$bound;
    $boundLength = strlen($boundString);
    $suffixLength = strlen($suffix);

    if ($suffixLength > $boundLength) {
        return 0;
    }

    for ($i = 0; $i < $suffixLength; $i++) {
        if ((int)$suffix[$i] > $limit) {
            return 0;
        }
    }

    $total = 0;

    for ($length = $suffixLength; $length <= $boundLength; $length++) {
        $isBounded = ($length === $boundLength);

        // tight: generated prefix is equal to the bound's prefix.
        // loose: generated prefix is already smaller than the bound.
        $tight = $isBounded ? 1 : 0;
        $loose = $isBounded ? 0 : 1;

        for ($position = 0; $position < $length; $position++) {
            $newTight = 0;
            $newLoose = 0;

            $suffixStart = $length - $suffixLength;

            if ($position >= $suffixStart) {
                $allowedStart = (int)$suffix[$position - $suffixStart];
                $allowedEnd = $allowedStart;
            } else {
                $allowedStart = ($position === 0) ? 1 : 0;
                $allowedEnd = $limit;
            }

            if ($allowedStart > $allowedEnd) {
                $tight = 0;
                $loose = 0;
                break;
            }

            for ($digit = $allowedStart; $digit <= $allowedEnd; $digit++) {
                if ($loose > 0) {
                    $newLoose += $loose;
                }

                if ($tight > 0) {
                    $boundDigit = (int)$boundString[$position];

                    if ($digit < $boundDigit) {
                        $newLoose += $tight;
                    } elseif ($digit === $boundDigit) {
                        $newTight += $tight;
                    }
                }
            }

            $tight = $newTight;
            $loose = $newLoose;
        }

        $total += $tight + $loose;
    }

    return $total;
}

$result = countPowerfulUpTo($finish, $limit, $suffix)
        - countPowerfulUpTo($start - 1, $limit, $suffix);

echo $result . PHP_EOL;
