$lines = preg_split('/\R+/', $input);
$lines = array_values(array_filter($lines, static fn($line) => trim($line) !== ''));

$parseArray = static function (string $line): array {
    preg_match_all('/-?\d+/', $line, $matches);
    return array_map('intval', $matches[0]);
};

$nums = $parseArray($lines[0] ?? '');
$changeIndices = $parseArray($lines[1] ?? '');

$n = count($nums);
$m = count($changeIndices);

if ($n === 0 || $m < $n) {
    echo "-1\n";
    exit;
}

$isPossible = static function (int $second) use ($nums, $changeIndices, $n): bool {
    $lastOccurrence = array_fill(0, $n + 1, -1);

    for ($s = 1; $s <= $second; $s++) {
        $lastOccurrence[$changeIndices[$s - 1]] = $s;
    }

    for ($i = 1; $i <= $n; $i++) {
        if ($lastOccurrence[$i] === -1) {
            return false;
        }
    }

    $availableDecrements = 0;

    for ($s = 1; $s <= $second; $s++) {
        $index = $changeIndices[$s - 1];

        if ($lastOccurrence[$index] === $s) {
            $needed = $nums[$index - 1];

            if ($availableDecrements < $needed) {
                return false;
            }

            $availableDecrements -= $needed;
        } else {
            $availableDecrements++;
        }
    }

    return true;
};

if (!$isPossible($m)) {
    echo "-1\n";
    exit;
}

$left = 1;
$right = $m;

while ($left < $right) {
    $mid = intdiv($left + $right, 2);

    if ($isPossible($mid)) {
        $right = $mid;
    } else {
        $left = $mid + 1;
    }
}

echo $left . PHP_EOL;
