    $frequency[$num] = ($frequency[$num] ?? 0) + 1;
}

$answer = 1;

foreach ($frequency as $value => $count) {
    $value = (int)$value;

    if ($value === 1) {
        $length = ($count % 2 === 1) ? $count : $count - 1;
        $answer = max($answer, $length);
        continue;
    }

    $current = $value;
    $length = 0;

    while (isset($frequency[$current]) && $frequency[$current] >= 2) {
        $length += 2;
        $current *= $current;
    }

    if (isset($frequency[$current])) {
        $length++;
    } else {
        $length--;
    }

    $answer = max($answer, $length);
}

