<?php

function readNonEmptyLine()
{
    while (($line = fgets(STDIN)) !== false) {
        $line = trim($line);
        if ($line !== '') {
            return $line;
        }
    }
    return null;
}

$numsLine = readNonEmptyLine();
$nums = array_map('intval', preg_split('/\s+/', $numsLine));
$n = count($nums);

$mLine = readNonEmptyLine();
$m = (int)$mLine;

$sum = array_sum($nums);
$marked = array_fill(0, $n, false);

$sortedValues = $nums;
$sortedIndices = range(0, $n - 1);

array_multisort(
    $sortedValues, SORT_ASC, SORT_NUMERIC,
    $sortedIndices, SORT_ASC, SORT_NUMERIC
);

$pointer = 0;
$answers = [];

for ($q = 0; $q < $m; $q++) {
    $queryLine = readNonEmptyLine();
    [$index, $k] = array_map('intval', preg_split('/\s+/', $queryLine));

    if (!$marked[$index]) {
        $marked[$index] = true;
        $sum -= $nums[$index];
    }

    while ($k > 0 && $pointer < $n) {
        $candidate = $sortedIndices[$pointer++];

        if ($marked[$candidate]) {
            continue;
        }

        $marked[$candidate] = true;
        $sum -= $nums[$candidate];
        $k--;
    }

    $answers[] = (string)$sum;
}

echo implode(' ', $answers);
?>
