$negativeInfinity = PHP_INT_MIN;

$best = array_fill(0, $k + 1, $negativeInfinity);
$ending = array_fill(0, $k + 1, $negativeInfinity);
$best[0] = 0;

for ($i = 0; $i < $n; $i++) {
    $value = $nums[$i];
    $maxSelected = min($k, $i + 1);

