        $coefficient = $k - $j + 1;
        if (($j & 1) === 0) {
            $coefficient = -$coefficient;
        }

        $contribution = $value * $coefficient;
        $newEnding = $negativeInfinity;

        if ($ending[$j] !== $negativeInfinity) {
            $newEnding = $ending[$j] + $contribution;
        }

        if ($best[$j - 1] !== $negativeInfinity) {
            $startNew = $best[$j - 1] + $contribution;
            if ($newEnding === $negativeInfinity || $startNew > $newEnding) {
                $newEnding = $startNew;
            }
        }

        $ending[$j] = $newEnding;

        if ($best[$j] === $negativeInfinity || $newEnding > $best[$j]) {
            $best[$j] = $newEnding;
        }
    }
