<?php

const MOD = 1000000007;

$input = trim(stream_get_contents(STDIN));
if ($input === '') {
    exit;
}

$lines = preg_split('/\R+/', $input);
$lines = array_values(array_filter($lines, static fn($line) => trim($line) !== ''));

if (count($lines) >= 2) {
    preg_match_all('/-?\d+/', $lines[0], $matches);
    $nums = array_map('intval', $matches[0]);

    preg_match('/-?\d+/', $lines[1], $kMatch);
    $k = (int)$kMatch[0];
} else {
    preg_match_all('/-?\d+/', $lines[0], $matches);
    $values = array_map('intval', $matches[0]);
    $k = array_pop($values);
    $nums = $values;
}

sort($nums, SORT_NUMERIC);
$n = count($nums);

$distances = [];
for ($i = 0; $i < $n; $i++) {
    for ($j = $i + 1; $j < $n; $j++) {
        $difference = $nums[$j] - $nums[$i];
        if ($difference > 0) {
            $distances[] = $difference;
        }
    }
}

if (empty($distances)) {
    echo "0\n";
    exit;
}

sort($distances, SORT_NUMERIC);
$distances = array_values(array_unique($distances, SORT_REGULAR));

function countSubsequencesWithMinDistance(
    array $nums,
    int $k,
    int $distance
): int {
    $n = count($nums);

    // limit[i] is the largest j < i such that nums[i] - nums[j] >= distance.
    $limit = array_fill(0, $n, -1);
    $left = -1;

    for ($i = 0; $i < $n; $i++) {
        while ($left + 1 < $i &&
               $nums[$i] - $nums[$left + 1] >= $distance) {
            $left++;
        }
        $limit[$i] = $left;
    }

    // For length 1, one subsequence ends at every index.
    $previous = array_fill(0, $n, 1);

    for ($length = 2; $length <= $k; $length++) {
        $prefix = array_fill(0, $n, 0);
        $running = 0;

        for ($i = 0; $i < $n; $i++) {
            $running += $previous[$i];
            if ($running >= MOD) {
                $running -= MOD;
            }
            $prefix[$i] = $running;
        }

        $current = array_fill(0, $n, 0);
        for ($i = 0; $i < $n; $i++) {
            if ($limit[$i] >= 0) {
                $current[$i] = $prefix[$limit[$i]];
            }
        }

        $previous = $current;
    }

    $count = 0;
    foreach ($previous as $value) {
        $count += $value;
        if ($count >= MOD) {
            $count -= MOD;
        }
    }

    return $count;
}

$answer = 0;
$previousDistance = 0;

foreach ($distances as $distance) {
    $count = countSubsequencesWithMinDistance($nums, $k, $distance);
    $delta = $distance - $previousDistance;

    $contribution = (($delta % MOD) * $count) % MOD;
    $answer = ($answer + $contribution) % MOD;

    $previousDistance = $distance;
}

echo $answer . PHP_EOL;
