            $words = $decoded['words'];
        } else {
            $words = $decoded;
        }
    } elseif (preg_match('/\[[\s\S]*\]/', $input, $match)) {
        $decoded = json_decode($match[0], true);
        if (is_array($decoded)) {
            $words = $decoded;
        }
    }

    if (!$words) {
        $tokens = preg_split('/\s+/', $input, -1, PREG_SPLIT_NO_EMPTY);
        if ($tokens && ctype_digit($tokens[0]) && (int)$tokens[0] === count($tokens) - 1) {
            array_shift($tokens);
        }
        $words = $tokens;
    }
}

$frequencies = array_fill(0, 26, 0);
$lengths = [];

foreach ($words as $word) {
    $word = (string)$word;
    $length = strlen($word);
    $lengths[] = $length;

    for ($i = 0; $i < $length; $i++) {
        $frequencies[ord($word[$i]) - 97]++;
    }
}

$availablePairs = 0;
foreach ($frequencies as $frequency) {
    $availablePairs += intdiv($frequency, 2);
}

sort($lengths, SORT_NUMERIC);

$result = 0;
foreach ($lengths as $length) {
    $requiredPairs = intdiv($length, 2);

    if ($requiredPairs > $availablePairs) {
        break;
    }

    $availablePairs -= $requiredPairs;
    $result++;
}

echo $result;
?>
