```php
<?php

$input = trim(stream_get_contents(STDIN));
$lines = preg_split('/\R+/', $input);

$parsed = [];
foreach ($lines as $line) {
    if (trim($line) === '') {
        continue;
    }
    preg_match_all('/-?\d+/', $line, $matches);
    if (!empty($matches[0])) {
        $parsed[] = array_map('intval', $matches[0]);
    }
}

if (count($parsed) >= 3) {
    $nums = $parsed[0];
    $k = $parsed[1][0];
    $maxChanges = $parsed[2][0];
} else {
    preg_match_all('/-?\d+/', $input, $matches);
    $values = array_map('intval', $matches[0]);
    $maxChanges = array_pop($values);
    $k = array_pop($values);
    $nums = $values;
}

$positions = [];
$maxRun = 0;
$currentRun = 0;

foreach ($nums as $index => $value) {
    if ($value === 1) {
        $positions[] = $index;
        $currentRun++;
        if ($currentRun > $maxRun) {
            $maxRun = $currentRun;
        }
    } else {
        $currentRun = 0;
    }
}

$cheapOnes = min($k, 3, $maxRun);

if ($maxChanges >= $k - $cheapOnes) {
    $answer = max(0, $cheapOnes - 1) + 2 * ($k - $cheapOnes);
    echo $answer . PHP_EOL;
    exit;
}

$neededExisting = $k - $maxChanges;
$count = count($positions);

$prefix = array_fill(0, $count + 1, 0);
for ($i = 0; $i < $count; $i++) {
    $prefix[$i + 1] = $prefix[$i] + $positions[$i];
}

$minimumDistance = PHP_INT_MAX;

for ($left = 0; $left + $neededExisting <= $count; $left++) {
    $right = $left + $neededExisting - 1;
    $middle = intdiv($left + $right, 2);
    $median = $positions[$middle];

    $leftCost = $median * ($middle - $left)
        - ($prefix[$middle] - $prefix[$left]);

    $rightCost = ($prefix[$right + 1] - $prefix[$middle + 1])
        - $median * ($right - $middle);

    $distance = $leftCost + $rightCost;
    if ($distance < $minimumDistance) {
        $minimumDistance = $distance;
    }
}

$answer = $minimumDistance + 2 * $maxChanges;
echo $answer . PHP_EOL;
