        // Start the next subarray at the current element.
        if ($completed[$j] !== $INF && (($value & $target) === $target)) {
            $states[$value] = $completed[$j];
        }

        // Extend an already active subarray.
        foreach ($active[$j] as $currentAnd => $cost) {
            $newAnd = ((int)$currentAnd) & $value;

            if (($newAnd & $target) !== $target) {
                continue;
            }

            if (!isset($states[$newAnd]) || $cost < $states[$newAnd]) {
                $states[$newAnd] = $cost;
            }
        }

        $nextActive[$j] = $states;

        // End the current subarray here.
        if (array_key_exists($target, $states)) {
            $candidate = $states[$target] + $value;
            if ($candidate < $nextCompleted[$j + 1]) {
                $nextCompleted[$j + 1] = $candidate;
            }
        }
    }

    $active = $nextActive;
    $completed = $nextCompleted;
}

