    exit;
}

$wordsContainer = preg_split('/\s+/', $nonEmptyLines[0]);
$wordsQuery = preg_split('/\s+/', $nonEmptyLines[1]);

// Each trie node has a linked list of outgoing edges.
// An edge with index e always points to node e + 1.
$head = [-1];
$next = [];
$letter = [];
$best = [-1];
$wordLengths = [];

foreach ($wordsContainer as $index => $word) {
    $length = strlen($word);
    $wordLengths[$index] = $length;

    $rootBest = $best[0];
    if ($rootBest === -1 || $length < $wordLengths[$rootBest]) {
        $best[0] = $index;
    }

    $node = 0;

    for ($position = $length - 1; $position >= 0; --$position) {
        $character = ord($word[$position]);
        $edge = $head[$node];

        while ($edge !== -1 && $letter[$edge] !== $character) {
            $edge = $next[$edge];
        }

        if ($edge === -1) {
            $edge = count($letter);
            $letter[] = $character;
            $next[] = $head[$node];
            $head[$node] = $edge;

            $head[] = -1;
            $best[] = -1;
        }

        $node = $edge + 1;
        $nodeBest = $best[$node];

        if ($nodeBest === -1 || $length < $wordLengths[$nodeBest]) {
            $best[$node] = $index;
        }
    }
}

$answers = [];

foreach ($wordsQuery as $query) {
    $node = 0;
    $answer = $best[0];

    for ($position = strlen($query) - 1; $position >= 0; --$position) {
        $character = ord($query[$position]);
        $edge = $head[$node];

        while ($edge !== -1 && $letter[$edge] !== $character) {
            $edge = $next[$edge];
        }

        if ($edge === -1) {
            break;
        }

        $node = $edge + 1;
        $answer = $best[$node];
    }

    $answers[] = $answer;
}

echo implode(' ', $answers);
