$lines = file('php://stdin', FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES);

function extractIntegers(string $line): array
{
    preg_match_all('/-?\d+/', $line, $matches);
    return array_map('intval', $matches[0]);
}

$nums = extractIntegers($lines[0] ?? '');
$cost1Values = extractIntegers($lines[1] ?? '');
$cost2Values = extractIntegers($lines[2] ?? '');

$cost1 = $cost1Values[0] ?? 0;
$cost2 = $cost2Values[0] ?? 0;
$n = count($nums);
$mod = 1000000007;

if ($n <= 1) {
    echo "0\n";
    exit;
}

$minimum = min($nums);
$maximum = max($nums);
$sum = array_sum($nums);

if ($n === 2 || $cost2 >= 2 * $cost1) {
    $deficit = $n * $maximum - $sum;
    $answer = $deficit * $cost1;
    echo ($answer % $mod) . PHP_EOL;
    exit;
}

function costForTarget(
    int $target,
    int $n,
    int $sum,
    int $minimum,
    int $cost1,
    int $cost2
): int {
    $totalDeficit = $n * $target - $sum;
    $largestDeficit = $target - $minimum;

    $pairs = min(
        intdiv($totalDeficit, 2),
        $totalDeficit - $largestDeficit
    );

    $singles = $totalDeficit - 2 * $pairs;

    return $pairs * $cost2 + $singles * $cost1;
}

$numerator = $sum - 2 * $minimum;
$denominator = $n - 2;
$balanceTarget = intdiv($numerator + $denominator - 1, $denominator);
$base = max($maximum, $balanceTarget);

$candidates = [$maximum, $maximum + 1];

for ($offset = -2; $offset <= 2; $offset++) {
    $target = $base + $offset;
    if ($target >= $maximum) {
        $candidates[] = $target;
    }
}

$best = PHP_INT_MAX;

foreach (array_unique($candidates) as $target) {
    $current = costForTarget(
        (int)$target,
        $n,
        $sum,
        $minimum,
        $cost1,
        $cost2
    );

    if ($current < $best) {
        $best = $current;
    }
}

echo ($best % $mod) . PHP_EOL;
