<?php

function totalSetBitsUpTo(int $n): int
{
    if ($n <= 0) {
        return 0;
    }

    $length = $n + 1;
    $half = 1;
    $count = 0;

    while ($half <= $n) {
        $cycle = $half * 2;
        $count += intdiv($length, $cycle) * $half;

        $remainder = $length % $cycle;
        if ($remainder > $half) {
            $count += $remainder - $half;
        }

        $half *= 2;
    }

    return $count;
}

function exponentSumUpTo(int $n): int
{
    if ($n <= 0) {
        return 0;
    }

    $length = $n + 1;
    $half = 1;
    $position = 0;
    $sum = 0;

    while ($half <= $n) {
        $cycle = $half * 2;
        $ones = intdiv($length, $cycle) * $half;

        $remainder = $length % $cycle;
        if ($remainder > $half) {
            $ones += $remainder - $half;
        }

        $sum += $ones * $position;
        $half *= 2;
        $position++;
    }

    return $sum;
}

function prefixExponentSum(int $elementCount): int
{
    if ($elementCount <= 0) {
        return 0;
    }

    $low = 0;
    $high = $elementCount;

    while ($low < $high) {
        $mid = intdiv($low + $high + 1, 2);

        if (totalSetBitsUpTo($mid) <= $elementCount) {
            $low = $mid;
        } else {
            $high = $mid - 1;
        }
    }

    $completeNumbers = $low;
    $usedElements = totalSetBitsUpTo($completeNumbers);
    $sum = exponentSumUpTo($completeNumbers);
    $remaining = $elementCount - $usedElements;

    $value = $completeNumbers + 1;
    $position = 0;

    while ($remaining > 0 && $value > 0) {
        if (($value % 2) === 1) {
            $sum += $position;
            $remaining--;
        }

        $value = intdiv($value, 2);
        $position++;
    }

    return $sum;
}

function modularPowerOfTwo(int $exponent, int $modulus): int
{
    if ($modulus === 1) {
        return 0;
    }

    $result = 1;
    $base = 2 % $modulus;

    while ($exponent > 0) {
        if (($exponent % 2) === 1) {
            $result = ($result * $base) % $modulus;
        }

        $base = ($base * $base) % $modulus;
        $exponent = intdiv($exponent, 2);
    }

    return $result;
}

$input = trim(stream_get_contents(STDIN));
if ($input === '') {
    exit;
}

$tokens = preg_split('/\s+/', $input);
$index = 0;
$queryCount = intval($tokens[$index++]);
$answers = [];

for ($i = 0; $i < $queryCount; $i++) {
    $from = intval($tokens[$index++]);
    $to = intval($tokens[$index++]);
    $modulus = intval($tokens[$index++]);

    $rightSum = prefixExponentSum($to + 1);
    $leftSum = prefixExponentSum($from);
    $answers[] = modularPowerOfTwo($rightSum - $leftSum, $modulus);
}

echo implode(' ', $answers);
?>
