function readNonEmptyLine()
{
    while (($line = fgets(STDIN)) !== false) {
        $line = trim($line);
        if ($line !== '') {
            return $line;
        }
    }
    return null;
}

$numsLine = readNonEmptyLine();
$nums = array_map(
    'intval',
    preg_split('/\s+/', $numsLine, -1, PREG_SPLIT_NO_EMPTY)
);

$queryCount = (int) readNonEmptyLine();

$remainingInput = stream_get_contents(STDIN);
$queryTokens = preg_split(
    '/\s+/',
    trim($remainingInput),
    -1,
    PREG_SPLIT_NO_EMPTY
);

$n = count($nums);
$size = 1;
while ($size < $n) {
    $size <<= 1;
}

$totalSize = $size << 1;
$negativeInfinity = -1000000000000000;

/*
 * Each segment stores a 2x2 max-plus transition matrix:
 *
 * newNotSelected = max(oldNotSelected, oldSelected)
 * newSelected    = oldNotSelected + value
 *
 * Padding leaves are identity matrices.
 */
$m00 = array_fill(0, $totalSize, 0);
$m01 = array_fill(0, $totalSize, $negativeInfinity);
$m10 = array_fill(0, $totalSize, $negativeInfinity);
$m11 = array_fill(0, $totalSize, 0);

for ($i = 0; $i < $n; $i++) {
    $leaf = $size + $i;
    $m00[$leaf] = 0;
    $m01[$leaf] = 0;
    $m10[$leaf] = $nums[$i];
    $m11[$leaf] = $negativeInfinity;
}

unset($nums);

for ($i = $size - 1; $i >= 1; $i--) {
    $left = $i << 1;
    $right = $left + 1;

    $v1 = $m00[$right] + $m00[$left];
    $v2 = $m01[$right] + $m10[$left];
    $m00[$i] = ($v1 > $v2) ? $v1 : $v2;

    $v1 = $m00[$right] + $m01[$left];
    $v2 = $m01[$right] + $m11[$left];
    $m01[$i] = ($v1 > $v2) ? $v1 : $v2;

    $v1 = $m10[$right] + $m00[$left];
    $v2 = $m11[$right] + $m10[$left];
    $m10[$i] = ($v1 > $v2) ? $v1 : $v2;

    $v1 = $m10[$right] + $m01[$left];
    $v2 = $m11[$right] + $m11[$left];
    $m11[$i] = ($v1 > $v2) ? $v1 : $v2;
}

$mod = 1000000007;
$answer = 0;
$tokenIndex = 0;

for ($query = 0; $query < $queryCount; $query++) {
    $position = (int) $queryTokens[$tokenIndex++];
    $value = (int) $queryTokens[$tokenIndex++];

    $node = $size + $position;
    $m00[$node] = 0;
    $m01[$node] = 0;
    $m10[$node] = $value;
    $m11[$node] = $negativeInfinity;

    $node >>= 1;

    while ($node > 0) {
        $left = $node << 1;
        $right = $left + 1;

        $v1 = $m00[$right] + $m00[$left];
        $v2 = $m01[$right] + $m10[$left];
        $m00[$node] = ($v1 > $v2) ? $v1 : $v2;

        $v1 = $m00[$right] + $m01[$left];
        $v2 = $m01[$right] + $m11[$left];
        $m01[$node] = ($v1 > $v2) ? $v1 : $v2;

        $v1 = $m10[$right] + $m00[$left];
        $v2 = $m11[$right] + $m10[$left];
        $m10[$node] = ($v1 > $v2) ? $v1 : $v2;

        $v1 = $m10[$right] + $m01[$left];
        $v2 = $m11[$right] + $m11[$left];
        $m11[$node] = ($v1 > $v2) ? $v1 : $v2;

        $node >>= 1;
    }

    $best = ($m00[1] > $m10[1]) ? $m00[1] : $m10[1];
    $answer = ($answer + $best) % $mod;
}

echo $answer, PHP_EOL;
