$bit = array_fill(0, $n + 1, 0);
$isPeak = array_fill(0, $n, 0);

function addFenwick(array &$bit, int $n, int $index, int $delta): void
{
    for ($i = $index + 1; $i <= $n; $i += $i & (-$i)) {
        $bit[$i] += $delta;
    }
}

function prefixSum(array &$bit, int $index): int
{
    $sum = 0;
    for ($i = $index + 1; $i > 0; $i -= $i & (-$i)) {
        $sum += $bit[$i];
    }
    return $sum;
}

for ($i = 1; $i < $n - 1; $i++) {
    if ($nums[$i] > $nums[$i - 1] && $nums[$i] > $nums[$i + 1]) {
        $isPeak[$i] = 1;
        addFenwick($bit, $n, $i, 1);
    }
}

$answers = [];
$position = 0;

for ($q = 0; $q < $queryCount; $q++) {
    $type = $queryTokens[$position++] ?? 0;
    $a = $queryTokens[$position++] ?? 0;
    $b = $queryTokens[$position++] ?? 0;

    if ($type === 1) {
        $left = $a;
        $right = $b;

        if ($right - $left < 2) {
            $answers[] = 0;
        } else {
            $answers[] = prefixSum($bit, $right - 1) - prefixSum($bit, $left);
        }
    } else {
        $index = $a;
        $value = $b;
        $nums[$index] = $value;

        $start = max(1, $index - 1);
        $end = min($n - 2, $index + 1);

        for ($i = $start; $i <= $end; $i++) {
            $newPeak = (
                $nums[$i] > $nums[$i - 1] &&
                $nums[$i] > $nums[$i + 1]
