            if ($newPeak !== $isPeak[$i]) {
                addFenwick($bit, $n, $i, $newPeak - $isPeak[$i]);
                $isPeak[$i] = $newPeak;
            }
        }
    }
}

echo implode(' ', $answers);
echo PHP_EOL;
