    $possibleMaximum = intdiv($end * ($end + 1), 2);
    if ($count > $possibleMaximum || $count > $maxInversions) {
        echo "0\n";
        exit;
    }
}

$dp = array_fill(0, $maxInversions + 1, 0);
$dp[0] = 1;

for ($index = 0; $index < $n; $index++) {
    $next = array_fill(0, $maxInversions + 1, 0);
    $window = 0;

    for ($inversions = 0; $inversions <= $maxInversions; $inversions++) {
        $window += $dp[$inversions];
        if ($window >= MOD) {
            $window -= MOD;
        }

        $removeIndex = $inversions - $index - 1;
        if ($removeIndex >= 0) {
            $window -= $dp[$removeIndex];
            if ($window < 0) {
                $window += MOD;
            }
        }

        $next[$inversions] = $window;
    }

    if ($required[$index] !== -1) {
        $needed = $required[$index];
        $value = $next[$needed];
        $next = array_fill(0, $maxInversions + 1, 0);
        $next[$needed] = $value;
    }

