$totalWordLength = 0;
foreach ($words as $word) {
    $totalWordLength += strlen($word);
}

$maxNodes = $totalWordLength + 1;
$alphabetSize = 26;

$next = array_fill(0, $maxNodes * $alphabetSize, -1);
$fail = array_fill(0, $maxNodes, 0);
$outputLink = array_fill(0, $maxNodes, 0);
$terminalCost = array_fill(0, $maxNodes, 0);
$depth = array_fill(0, $maxNodes, 0);

$nodeCount = 1;
$wordCount = count($words);

for ($i = 0; $i < $wordCount; $i++) {
    $word = $words[$i];
    $cost = (int)$costTokens[$i];
    $state = 0;
    $length = strlen($word);

    for ($j = 0; $j < $length; $j++) {
        $letter = ord($word[$j]) - 97;
        $slot = $state * $alphabetSize + $letter;
        $child = $next[$slot];

        if ($child === -1) {
            $child = $nodeCount++;
            $next[$slot] = $child;
            $depth[$child] = $depth[$state] + 1;
        }

        $state = $child;
    }

    if ($terminalCost[$state] === 0 || $cost < $terminalCost[$state]) {
        $terminalCost[$state] = $cost;
    }
