    $child = $next[$letter];

    if ($child === -1) {
        $next[$letter] = 0;
    } else {
        $fail[$child] = 0;
        $outputLink[$child] = 0;
        $queue[$tail++] = $child;
    }
}

while ($head < $tail) {
    $state = $queue[$head++];
    $failureState = $fail[$state];
    $base = $state * $alphabetSize;
    $failureBase = $failureState * $alphabetSize;

    for ($letter = 0; $letter < $alphabetSize; $letter++) {
        $slot = $base + $letter;
        $child = $next[$slot];

        if ($child === -1) {
            $next[$slot] = $next[$failureBase + $letter];
        } else {
            $childFailure = $next[$failureBase + $letter];
            $fail[$child] = $childFailure;

            if ($terminalCost[$childFailure] > 0) {
                $outputLink[$child] = $childFailure;
            } else {
                $outputLink[$child] = $outputLink[$childFailure];
            }

            $queue[$tail++] = $child;
