<?php

$input = file_get_contents('php://stdin');
$position = 0;
$inputLength = strlen($input);

function nextInt(): int
{
    global $input, $position, $inputLength;

    while ($position < $inputLength && ord($input[$position]) <= 32) {
        $position++;
    }

    $sign = 1;
    if ($position < $inputLength && $input[$position] === '-') {
        $sign = -1;
        $position++;
    }

    $number = 0;
    while ($position < $inputLength) {
        $digit = ord($input[$position]) - 48;
        if ($digit < 0 || $digit > 9) {
            break;
        }
        $number = $number * 10 + $digit;
        $position++;
    }

    return $number * $sign;
}

$n = nextInt();
$distances = [];

for ($i = 0; $i < $n; $i++) {
    $x = nextInt();
    $y = nextInt();
    $distances[] = abs($x) + abs($y);
}

$k = nextInt();

// A max-heap containing the k smallest distances seen so far.
$heap = [0]; // One-indexed heap.
$heapSize = 0;
$results = [];

foreach ($distances as $distance) {
    if ($heapSize < $k) {
        $heapSize++;
        $index = $heapSize;

        while ($index > 1) {
            $parent = intdiv($index, 2);
            if ($heap[$parent] >= $distance) {
                break;
            }

            $heap[$index] = $heap[$parent];
            $index = $parent;
        }

        $heap[$index] = $distance;
    } elseif ($distance < $heap[1]) {
        $index = 1;

        while (true) {
            $left = $index * 2;
            if ($left > $heapSize) {
                break;
            }

            $right = $left + 1;
            $largerChild = $left;

            if ($right <= $heapSize && $heap[$right] > $heap[$left]) {
                $largerChild = $right;
            }

            if ($heap[$largerChild] <= $distance) {
                break;
            }

            $heap[$index] = $heap[$largerChild];
            $index = $largerChild;
        }

        $heap[$index] = $distance;
    }

    $results[] = ($heapSize < $k) ? -1 : $heap[1];
}

echo implode(' ', $results), PHP_EOL;
?>
