$pairs = intdiv($n, 2);

$exactDiffCount = array_fill(0, $k + 1, 0);
$thresholdCount = array_fill(0, $k + 1, 0);

for ($i = 0; $i < $pairs; $i++) {
    $a = $nums[$i];
    $b = $nums[$n - 1 - $i];

    $difference = abs($a - $b);
    $threshold = max(max($a, $b), $k - min($a, $b));

    $exactDiffCount[$difference]++;
    $thresholdCount[$threshold]++;
}

$eligibleForOneChange = $pairs;
$answer = PHP_INT_MAX;

for ($x = 0; $x <= $k; $x++) {
    if ($x > 0) {
        $eligibleForOneChange -= $thresholdCount[$x - 1];
    }

    $changes = 2 * $pairs
        - $eligibleForOneChange
        - $exactDiffCount[$x];

    if ($changes < $answer) {
        $answer = $changes;
    }
}

echo $answer . PHP_EOL;
?>
