<?php

class FenwickTree
{
    private $n;
    private $tree;
    private $maxPower;

    public function __construct($n)
    {
        $this->n = $n;
        $this->tree = array_fill(0, $n + 1, 0);

        $power = 1;
        while (($power << 1) <= $n) {
            $power <<= 1;
        }
        $this->maxPower = $power;
    }

    public function add($index, $delta)
    {
        for ($i = $index; $i <= $this->n; $i += $i & (-$i)) {
            $this->tree[$i] += $delta;
        }
    }

    public function prefixSum($index)
    {
        $sum = 0;
        for ($i = $index; $i > 0; $i -= $i & (-$i)) {
            $sum += $this->tree[$i];
        }
        return $sum;
    }

    // Returns the zero-based position of the element with the given one-based rank.
    public function kth($rank)
    {
        $index = 0;

        for ($step = $this->maxPower; $step > 0; $step >>= 1) {
            $next = $index + $step;
            if ($next <= $this->n && $this->tree[$next] < $rank) {
                $index = $next;
                $rank -= $this->tree[$next];
            }
        }

        return $index;
    }
}

class BadEdgeSet
{
    private $n;
    private $count = 0;
    private $positions;
    private $gapCount;
    private $gapSum;

    public function __construct($n)
    {
        $this->n = $n;
        $this->positions = new FenwickTree($n);
        $this->gapCount = new FenwickTree($n);
        $this->gapSum = new FenwickTree($n);
    }

    private function distance($from, $to)
    {
        $distance = $to - $from;
        return $distance > 0 ? $distance : $distance + $this->n;
    }

    private function changeGap($length, $delta)
    {
        $this->gapCount->add($length, $delta);
        $this->gapSum->add($length, $delta * $length);
    }

    public function insert($position)
    {
        if ($this->count === 0) {
            $this->positions->add($position + 1, 1);
            $this->changeGap($this->n, 1);
            $this->count = 1;
            return;
        }

        $less = $this->positions->prefixSum($position);

        $predecessorRank = $less > 0 ? $less : $this->count;
        $successorRank = $less < $this->count ? $less + 1 : 1;

        $predecessor = $this->positions->kth($predecessorRank);
        $successor = $this->positions->kth($successorRank);

        $this->changeGap($this->distance($predecessor, $successor), -1);
        $this->changeGap($this->distance($predecessor, $position), 1);
        $this->changeGap($this->distance($position, $successor), 1);

        $this->positions->add($position + 1, 1);
        $this->count++;
    }

    public function remove($position)
    {
        if ($this->count === 1) {
            $this->positions->add($position + 1, -1);
            $this->changeGap($this->n, -1);
            $this->count = 0;
            return;
        }

        $this->positions->add($position + 1, -1);
        $this->count--;

        $less = $this->positions->prefixSum($position);

        $predecessorRank = $less > 0 ? $less : $this->count;
        $successorRank = $less < $this->count ? $less + 1 : 1;

        $predecessor = $this->positions->kth($predecessorRank);
        $successor = $this->positions->kth($successorRank);

        $this->changeGap($this->distance($predecessor, $position), -1);
        $this->changeGap($this->distance($position, $successor), -1);
        $this->changeGap($this->distance($predecessor, $successor), 1);
    }

    public function countGroups($size)
    {
        if ($this->count === 0) {
            return $this->n;
        }

        $shortGapCount = $this->gapCount->prefixSum($size - 1);
        $shortGapSum = $this->gapSum->prefixSum($size - 1);

        $eligibleCount = $this->count - $shortGapCount;
        $eligibleSum = $this->n - $shortGapSum;

        return $eligibleSum - ($size - 1) * $eligibleCount;
    }
}

function readNonEmptyLine()
{
    while (($line = fgets(STDIN)) !== false) {
        $line = trim($line);
        if ($line !== '') {
            return $line;
        }
    }
    return null;
}

function parseIntegers($line)
{
    preg_match_all('/-?\d+/', $line, $matches);
    return array_map('intval', $matches[0]);
}

$colorLine = readNonEmptyLine();
$colors = parseIntegers($colorLine);
$n = count($colors);

$queryCountLine = readNonEmptyLine();
$queryCountValues = parseIntegers($queryCountLine);
$queryCount = $queryCountValues[0];

$badEdges = array_fill(0, $n, false);
$badEdgeSet = new BadEdgeSet($n);

for ($i = 0; $i < $n; $i++) {
    $next = ($i + 1) % $n;
    if ($colors[$i] === $colors[$next]) {
        $badEdges[$i] = true;
        $badEdgeSet->insert($i);
    }
}

$answers = [];

for ($q = 0; $q < $queryCount; $q++) {
    $query = parseIntegers(readNonEmptyLine());

    if ($query[0] === 1) {
        $answers[] = $badEdgeSet->countGroups($query[1]);
        continue;
    }

    $index = $query[1];
    $newColor = $query[2];

    if ($colors[$index] === $newColor) {
        continue;
    }

    $colors[$index] = $newColor;
    $affectedEdges = [
        ($index - 1 + $n) % $n,
        $index
    ];

    foreach ($affectedEdges as $edge) {
        $next = ($edge + 1) % $n;
        $isBadNow = ($colors[$edge] === $colors[$next]);

        if ($isBadNow === $badEdges[$edge]) {
            continue;
        }

        if ($isBadNow) {
            $badEdgeSet->insert($edge);
        } else {
            $badEdgeSet->remove($edge);
        }

        $badEdges[$edge] = $isBadNow;
    }
}

echo implode(' ', $answers), PHP_EOL;
