<?php

$input = file_get_contents('php://stdin');
$position = 0;
$length = strlen($input);

function nextInt(string $input, int &$position, int $length): int
{
    while ($position < $length && ord($input[$position]) <= 32) {
        ++$position;
    }

    $number = 0;
    while ($position < $length) {
        $code = ord($input[$position]);
        if ($code < 48 || $code > 57) {
            break;
        }
        $number = $number * 10 + ($code - 48);
        ++$position;
    }

    return $number;
}

$edgeCount = nextInt($input, $position, $length);
$n = $edgeCount + 1;

$adjacency = array_fill(0, $n, null);

for ($i = 0; $i < $edgeCount; ++$i) {
    $u = nextInt($input, $position, $length);
    $v = nextInt($input, $position, $length);

    $adjacency[$u][] = $v;
    $adjacency[$v][] = $u;
}

// Root the tree at node 0 and obtain a parent-before-child order.
$parent = array_fill(0, $n, -1);
$order = [0];

for ($i = 0; $i < $n; ++$i) {
    $u = $order[$i];

    foreach ($adjacency[$u] as $v) {
        if ($v === $parent[$u]) {
            continue;
        }

        $parent[$v] = $u;
        $order[] = $v;
    }
}

// down[u] is the maximum marking time from u to a node in u's subtree.
$down = array_fill(0, $n, 0);

for ($i = $n - 1; $i >= 0; --$i) {
    $u = $order[$i];
    $best = 0;

    foreach ($adjacency[$u] as $v) {
        if ($v === $parent[$u]) {
            continue;
        }

        $costToV = ($v & 1) ? 1 : 2;
        $candidate = $costToV + $down[$v];

        if ($candidate > $best) {
            $best = $candidate;
        }
    }

    $down[$u] = $best;
}

// up[u] is the maximum marking time from u to a node outside u's subtree.
$up = array_fill(0, $n, 0);
$answer = array_fill(0, $n, 0);

for ($i = 0; $i < $n; ++$i) {
    $u = $order[$i];

    $top1 = 0;
    $top2 = 0;
    $topChild = -1;

    foreach ($adjacency[$u] as $v) {
        if ($v === $parent[$u]) {
            continue;
        }

        $branch = (($v & 1) ? 1 : 2) + $down[$v];

        if ($branch > $top1) {
            $top2 = $top1;
            $top1 = $branch;
            $topChild = $v;
        } elseif ($branch > $top2) {
            $top2 = $branch;
        }
    }

    $answer[$u] = max($down[$u], $up[$u]);
    $costToU = ($u & 1) ? 1 : 2;

    foreach ($adjacency[$u] as $v) {
        if ($v === $parent[$u]) {
            continue;
        }

        $bestSiblingBranch = ($v === $topChild) ? $top2 : $top1;
        $bestFromU = max($up[$u], $bestSiblingBranch);

        $up[$v] = $costToU + $bestFromU;
    }
}

echo implode(' ', $answer);
?>
