$dp = array_fill(0, $nums[0] + 1, 1);

for ($i = 1; $i < $n; $i++) {
    $prefix = [];
    $sum = 0;

    foreach ($dp as $value) {
        $sum += $value;
        if ($sum >= MOD) {
            $sum -= MOD;
        }
        $prefix[] = $sum;
    }

    $requiredIncrease = max(0, $nums[$i] - $nums[$i - 1]);
    $current = array_fill(0, $nums[$i] + 1, 0);

    for ($value = 0; $value <= $nums[$i]; $value++) {
        $maxPrevious = $value - $requiredIncrease;
        if ($maxPrevious >= 0) {
            $maxPrevious = min($maxPrevious, count($dp) - 1);
            $current[$value] = $prefix[$maxPrevious];
        }
    }

    $dp = $current;
}

$answer = 0;
foreach ($dp as $value) {
    $answer += $value;
    if ($answer >= MOD) {
        $answer -= MOD;
    }
}

echo $answer . PHP_EOL;
