<?php

$input = stream_get_contents(STDIN);
preg_match_all('/\d+/', $input, $matches);

$n = (int)$matches[0][0];
$k = (int)$matches[0][1];

function binomial(int $n, int $r): int
{
    $r = min($r, $n - $r);
    $result = 1;

    for ($i = 1; $i <= $r; $i++) {
        $result = intdiv($result * ($n - $r + $i), $i);
    }

    return $result;
}

function multinomial(array $counts): int
{
    $ways = 1;
    $used = 0;

    foreach ($counts as $count) {
        if ($count > 0) {
            $ways *= binomial($used + $count, $count);
            $used += $count;
        }
    }

    return $ways;
}

function countValidPermutations(array $counts): int
{
    $total = multinomial($counts);

    if ($counts[0] === 0) {
        return $total;
    }

    $counts[0]--;
    $leadingZero = multinomial($counts);

    return $total - $leadingZero;
}

function stringModulo(string $number, int $modulus): int
{
    $remainder = 0;

    for ($i = 0, $length = strlen($number); $i < $length; $i++) {
        $remainder = ($remainder * 10 + (ord($number[$i]) - 48)) % $modulus;
    }

    return $remainder;
}

$halfLength = intdiv($n + 1, 2);

$start = 1;
for ($i = 1; $i < $halfLength; $i++) {
    $start *= 10;
}
$end = $start * 10;

$seen = [];
$answer = 0;

for ($prefixNumber = $start; $prefixNumber < $end; $prefixNumber++) {
    $prefix = (string)$prefixNumber;

    if (($n & 1) === 1) {
        $palindrome = $prefix . strrev(substr($prefix, 0, -1));
    } else {
        $palindrome = $prefix . strrev($prefix);
    }

    if (stringModulo($palindrome, $k) !== 0) {
        continue;
    }

    $counts = array_fill(0, 10, 0);
    for ($i = 0; $i < $n; $i++) {
        $counts[ord($palindrome[$i]) - 48]++;
    }

    $signature = implode(',', $counts);

    if (isset($seen[$signature])) {
        continue;
    }

    $seen[$signature] = true;
    $answer += countValidPermutations($counts);
}

echo $answer, PHP_EOL;
