```php
<?php

$input = file_get_contents("php://stdin");
preg_match_all('/\d+/', $input, $matches);

$n = (int)$matches[0][0];
$k = (int)$matches[0][1];

$halfLength = intdiv($n + 1, 2);

// Store 10^i mod k as bytes.
$powers = '';
$power = 1 % $k;

for ($i = 0; $i < $n; $i++) {
    $powers .= chr($power);
    $power = ($power * 10) % $k;
}

// Contribution modulo k of each digit in the left half.
$weights = '';
for ($i = 0; $i < $halfLength; $i++) {
    $mirror = $n - 1 - $i;
    $weight = ord($powers[$i]);

    if ($mirror !== $i) {
        $weight += ord($powers[$mirror]);
    }

    $weights .= chr($weight % $k);
}
unset($powers);

// dp[i] is a bitmask of remainders achievable using positions i onward.
$dp = array_fill(0, $halfLength + 1, 0);
$dp[$halfLength] = 1; // Only remainder 0 is possible with no digits.

$fullMask = (1 << $k) - 1;

for ($i = $halfLength - 1; $i >= 0; $i--) {
    $weight = ord($weights[$i]);
    $nextMask = $dp[$i + 1];
    $mask = 0;

    for ($digit = 0; $digit <= 9; $digit++) {
        $addition = ($digit * $weight) % $k;

        for ($remainder = 0; $remainder < $k; $remainder++) {
            if (($nextMask & (1 << $remainder)) !== 0) {
                $newRemainder = ($remainder + $addition) % $k;
                $mask |= 1 << $newRemainder;
            }
        }

        if ($mask === $fullMask) {
            break;
        }
    }

    $dp[$i] = $mask;
}

// Greedily construct the lexicographically largest feasible left half.
$left = '';
$currentRemainder = 0;

for ($i = 0; $i < $halfLength; $i++) {
    $weight = ord($weights[$i]);
    $minimumDigit = ($i === 0) ? 1 : 0;

    for ($digit = 9; $digit >= $minimumDigit; $digit--) {
        $newRemainder = ($currentRemainder + $digit * $weight) % $k;
        $needed = ($k - $newRemainder) % $k;

        if (($dp[$i + 1] & (1 << $needed)) !== 0) {
            $left .= chr(48 + $digit);
            $currentRemainder = $newRemainder;
            break;
        }
    }
}

$mirroredLength = intdiv($n, 2);
$result = $left . strrev(substr($left, 0, $mirroredLength));

echo $result, PHP_EOL;
?>
