while (!$deque->isEmpty()) {
    [$row, $col, $cost] = $deque->shift();

    if ($cost !== $distance[$row][$col]) {
        continue;
    }

    foreach ($directions as [$dr, $dc]) {
        $newRow = $row + $dr;
        $newCol = $col + $dc;

        if ($newRow < 0 || $newRow >= $m || $newCol < 0 || $newCol >= $n) {
            continue;
        }

        $newCost = $cost + $grid[$newRow][$newCol];

        if ($newCost < $distance[$newRow][$newCol]) {
            $distance[$newRow][$newCol] = $newCost;
            $state = [$newRow, $newCol, $newCost];

            if ($grid[$newRow][$newCol] === 0) {
                $deque->unshift($state);
            } else {
                $deque->push($state);
            }
        }
    }
