<?php

$input = trim(stream_get_contents(STDIN));

if ($input === '') {
    echo "-1\n";
    exit;
}

$lines = preg_split('/\R/', $input);
$lines = array_values(array_filter(array_map('trim', $lines), static fn($line) => $line !== ''));

$words = [];
$target = '';

if (count($lines) === 1) {
    $tokens = preg_split('/\s+/', $lines[0]);
    $target = array_pop($tokens) ?? '';
    $words = $tokens;
} elseif (ctype_digit($lines[0])) {
    $wordCount = (int)$lines[0];
    $tokens = preg_split('/\s+/', implode(' ', array_slice($lines, 1)));
    $words = array_slice($tokens, 0, $wordCount);
    $target = $tokens[$wordCount] ?? '';
} else {
    $target = array_pop($lines);
    $words = preg_split('/\s+/', implode(' ', $lines));
}

$targetLength = strlen($target);

if ($targetLength === 0 || count($words) === 0) {
    echo "-1\n";
    exit;
}

// $maxMatch[$i] is the maximum length of a valid string matching
// the target starting at position $i.
$maxMatch = array_fill(0, $targetLength, 0);

foreach ($words as $word) {
    $wordLength = strlen($word);
    if ($wordLength === 0) {
        continue;
    }

    // '{' does not occur in lowercase English strings.
    $combined = $word . '{' . $target;
    $combinedLength = strlen($combined);
    $z = array_fill(0, $combinedLength, 0);

    $left = 0;
    $right = 0;

    for ($i = 1; $i < $combinedLength; $i++) {
        if ($i <= $right) {
            $remaining = $right - $i + 1;
            $previous = $z[$i - $left];
            $z[$i] = min($remaining, $previous);
        }

        while (
            $i + $z[$i] < $combinedLength &&
            $combined[$z[$i]] === $combined[$i + $z[$i]]
        ) {
            $z[$i]++;
        }

        if ($i + $z[$i] - 1 > $right) {
            $left = $i;
            $right = $i + $z[$i] - 1;
        }
    }

    $offset = $wordLength + 1;
    for ($i = 0; $i < $targetLength; $i++) {
        $matchLength = $z[$offset + $i];
        if ($matchLength > $maxMatch[$i]) {
            $maxMatch[$i] = $matchLength;
        }
    }
}

// Minimum jumps over intervals [i + 1, i + maxMatch[i]].
$pieces = 0;
$currentEnd = 0;
$farthest = 0;

for ($i = 0; $i < $targetLength; $i++) {
    if ($i > $farthest) {
        echo "-1\n";
        exit;
    }

    $reach = $i + $maxMatch[$i];
    if ($reach > $farthest) {
        $farthest = $reach;
    }

    if ($i === $currentEnd) {
        if ($farthest <= $i) {
            echo "-1\n";
            exit;
        }

        $pieces++;
        $currentEnd = $farthest;

        if ($currentEnd >= $targetLength) {
            echo $pieces . "\n";
            exit;
        }
    }
}

echo "-1\n";
?>
