$dy = [1, -1, 1, -1, 2, -2, 2, -2];

for ($source = 0; $source < $pointCount; $source++) {
    $boardDistance = array_fill(0, 2500, -1);

    $startX = $points[$source][0];
    $startY = $points[$source][1];
    $startCell = $startX * 50 + $startY;

    $boardDistance[$startCell] = 0;
    $queue = [$startCell];
    $head = 0;

    while (isset($queue[$head])) {
        $cell = $queue[$head++];
        $x = intdiv($cell, 50);
        $y = $cell % 50;
        $nextDistance = $boardDistance[$cell] + 1;

        for ($move = 0; $move < 8; $move++) {
            $nx = $x + $dx[$move];
            $ny = $y + $dy[$move];

            if ($nx < 0 || $nx >= 50 || $ny < 0 || $ny >= 50) {
                continue;
            }

            $nextCell = $nx * 50 + $ny;
            if ($boardDistance[$nextCell] === -1) {
                $boardDistance[$nextCell] = $nextDistance;
                $queue[] = $nextCell;
            }
        }
    }

    $distances[$source] = array_fill(0, $pointCount, 0);
    for ($target = 0; $target < $pointCount; $target++) {
        $targetCell = $points[$target][0] * 50 + $points[$target][1];
        $distances[$source][$target] = $boardDistance[$targetCell];
    }
}

$fullMask = (1 << $n) - 1;
$stateWidth = $n + 1;
$memo = array_fill(0, (1 << $n) * $stateWidth, -1);

$solve = function (int $mask, int $current, bool $aliceTurn) use (
    &$solve,
    &$memo,
    &$distances,
    $n,
    $fullMask,
    $stateWidth
): int {
    if ($mask === $fullMask) {
        return 0;
    }

    $key = $mask * $stateWidth + $current;
    if ($memo[$key] !== -1) {
        return $memo[$key];
    }

    $best = $aliceTurn ? PHP_INT_MIN : PHP_INT_MAX;

    for ($pawn = 0; $pawn < $n; $pawn++) {
        $bit = 1 << $pawn;
        if (($mask & $bit) !== 0) {
            continue;
        }

        $score = $distances[$current][$pawn]
            + $solve($mask | $bit, $pawn, !$aliceTurn);

        if ($aliceTurn) {
            if ($score > $best) {
                $best = $score;
            }
        } else {
            if ($score < $best) {
                $best = $score;
            }
        }
    }

    $memo[$key] = $best;
    return $best;
};

echo $solve(0, $n, true), PHP_EOL;
