<?php

$input = file_get_contents('php://stdin');
$inputPos = 0;
$inputLength = strlen($input);

function nextIntFast(): int
{
    global $input, $inputPos, $inputLength;

    while ($inputPos < $inputLength) {
        $code = ord($input[$inputPos]);
        if ($code >= 48 && $code <= 57) {
            break;
        }
        $inputPos++;
    }

    $value = 0;
    while ($inputPos < $inputLength) {
        $code = ord($input[$inputPos]);
        if ($code < 48 || $code > 57) {
            break;
        }
        $value = $value * 10 + ($code - 48);
        $inputPos++;
    }

    return $value;
}

function insertIndexIntoKey(string $key, int $index): string
{
    $piece = pack('N', $index);
    $length = strlen($key);
    $position = 0;

    while ($position < $length) {
        if (strcmp($piece, substr($key, $position, 4)) < 0) {
            break;
        }
        $position += 4;
    }

    return substr($key, 0, $position)
        . $piece
        . substr($key, $position);
}

$n = nextIntFast();

$left = [];
$right = [];
$weights = [];
$ids = [];

for ($i = 0; $i < $n; $i++) {
    $left[] = nextIntFast();
    $right[] = nextIntFast();
    $weights[] = nextIntFast();
    $ids[] = $i;
}

unset($input);

array_multisort(
    $right, SORT_ASC, SORT_NUMERIC,
    $ids, SORT_ASC, SORT_NUMERIC,
    $left, SORT_ASC, SORT_NUMERIC,
    $weights, SORT_ASC, SORT_NUMERIC
);

// predecessor[i] is the number of intervals ending strictly before
// the left endpoint of sorted interval i - 1.
$predecessor = [0];

for ($i = 0; $i < $n; $i++) {
    $target = $left[$i];
    $low = 0;
    $high = $n;

    while ($low < $high) {
        $mid = intdiv($low + $high, 2);
        if ($right[$mid] < $target) {
            $low = $mid + 1;
        } else {
            $high = $mid;
        }
    }

    $predecessor[] = $low;
}

$negativeInfinity = -PHP_INT_MAX;

// DP base for choosing exactly zero intervals.
$previousScores = array_fill(0, $n + 1, 0);
$previousKeys = array_fill(0, $n + 1, '');

$bestScore = $negativeInfinity;
$bestKey = null;

for ($count = 1; $count <= 4 && $count <= $n; $count++) {
    $currentScores = [$negativeInfinity];
    $currentKeys = [null];

    for ($i = 1; $i <= $n; $i++) {
        $chosenScore = $currentScores[$i - 1];
        $chosenKey = $currentKeys[$i - 1];

        $previousPosition = $predecessor[$i];
        $baseScore = $previousScores[$previousPosition];

        if ($baseScore !== $negativeInfinity) {
            $takeScore = $baseScore + $weights[$i - 1];

            if ($takeScore > $chosenScore) {
                $chosenScore = $takeScore;
                $chosenKey = insertIndexIntoKey(
                    $previousKeys[$previousPosition],
                    $ids[$i - 1]
                );
            } elseif ($takeScore === $chosenScore) {
                $takeKey = insertIndexIntoKey(
                    $previousKeys[$previousPosition],
                    $ids[$i - 1]
                );

                if ($chosenKey === null || strcmp($takeKey, $chosenKey) < 0) {
                    $chosenKey = $takeKey;
                }
            }
        }

        $currentScores[] = $chosenScore;
        $currentKeys[] = $chosenKey;
    }

    $finalScore = $currentScores[$n];
    $finalKey = $currentKeys[$n];

    if (
        $finalScore !== $negativeInfinity &&
        (
            $finalScore > $bestScore ||
            ($finalScore === $bestScore &&
                ($bestKey === null || strcmp($finalKey, $bestKey) < 0))
        )
    ) {
        $bestScore = $finalScore;
        $bestKey = $finalKey;
    }

    if ($finalScore === $negativeInfinity) {
        break;
    }

    $previousScores = $currentScores;
    $previousKeys = $currentKeys;
    unset($currentScores, $currentKeys);
}

if ($bestKey === null || $bestKey === '') {
    echo PHP_EOL;
} else {
    $answer = array_values(unpack('N*', $bestKey));
    echo implode(' ', $answer), PHP_EOL;
}
