    if (!isset($lines[$row])) {
        break;
    }

    $values = preg_split('/\s+/', trim($lines[$row]));
    foreach ($values as $value) {
        if ($value === '') {
            continue;
        }

        $value = (int)$value;
        if (!isset($valueRowMasks[$value])) {
            $valueRowMasks[$value] = 0;
        }
        $valueRowMasks[$value] |= (1 << $row);
    }
}

$maskCount = 1 << $rowCount;
$negativeInfinity = PHP_INT_MIN;
$dp = array_fill(0, $maskCount, $negativeInfinity);
$dp[0] = 0;

foreach ($valueRowMasks as $value => $availableRowsMask) {
    $next = $dp;

    for ($mask = 0; $mask < $maskCount; $mask++) {
        if ($dp[$mask] === $negativeInfinity) {
            continue;
        }

        $available = $availableRowsMask & (~$mask);

        while ($available !== 0) {
            $rowBit = $available & (-$available);
            $newMask = $mask | $rowBit;
            $score = $dp[$mask] + $value;

            if ($score > $next[$newMask]) {
                $next[$newMask] = $score;
            }

            $available ^= $rowBit;
        }
    }

    $dp = $next;
}

echo max($dp), PHP_EOL;
