<?php

function zAlgorithm(string $str): array
{
    $n = strlen($str);
    $z = array_fill(0, $n, 0);
    $left = 0;
    $right = 0;

    for ($i = 1; $i < $n; $i++) {
        if ($i <= $right) {
            $z[$i] = min($right - $i + 1, $z[$i - $left]);
        }

        while ($i + $z[$i] < $n && $str[$z[$i]] === $str[$i + $z[$i]]) {
            $z[$i]++;
        }

        if ($i + $z[$i] - 1 > $right) {
            $left = $i;
            $right = $i + $z[$i] - 1;
        }
    }

    return $z;
}

$sLine = fgets(STDIN);
$patternLine = fgets(STDIN);

$s = rtrim($sLine === false ? '' : $sLine, "\r\n");
$pattern = rtrim($patternLine === false ? '' : $patternLine, "\r\n");

$n = strlen($s);
$m = strlen($pattern);

if ($m > $n) {
    echo "-1\n";
    exit;
}

$alignmentCount = $n - $m + 1;

$combined = $pattern . '#' . $s;
$zForward = zAlgorithm($combined);

$prefixMatches = array_fill(0, $alignmentCount, 0);
$offset = $m + 1;

for ($i = 0; $i < $alignmentCount; $i++) {
    $prefixMatches[$i] = min($m, $zForward[$offset + $i]);
}

unset($zForward, $combined);

$reversedPattern = strrev($pattern);
$reversedS = strrev($s);
$reversedCombined = $reversedPattern . '#' . $reversedS;
$zReverse = zAlgorithm($reversedCombined);

$answer = -1;

for ($i = 0; $i < $alignmentCount; $i++) {
    $reversedStart = $n - ($i + $m);
    $suffixMatches = min($m, $zReverse[$offset + $reversedStart]);

    if ($prefixMatches[$i] + $suffixMatches >= $m - 1) {
        $answer = $i;
        break;
    }
}

echo $answer . PHP_EOL;
?>
