$queryTokens = $queriesLine === '' ? [] : preg_split('/\s+/', $queriesLine);

$maxValue = 0;
foreach ($numsTokens as $token) {
    $value = (int)$token;
    if ($value > $maxValue) {
        $maxValue = $value;
    }
}

$frequency = array_fill(0, $maxValue + 1, 0);
foreach ($numsTokens as $token) {
    ++$frequency[(int)$token];
}

/*
 * $gcdCount[$d] will contain the number of pairs whose GCD is exactly $d.
 */
$gcdCount = array_fill(0, $maxValue + 1, 0);

for ($d = $maxValue; $d >= 1; --$d) {
    $divisible = 0;

    for ($multiple = $d; $multiple <= $maxValue; $multiple += $d) {
        $divisible += $frequency[$multiple];
    }

    $pairs = intdiv($divisible * ($divisible - 1), 2);

    for ($multiple = $d + $d; $multiple <= $maxValue; $multiple += $d) {
        $pairs -= $gcdCount[$multiple];
    }

    $gcdCount[$d] = $pairs;
}

/* Convert exact counts into cumulative counts. */
for ($d = 1; $d <= $maxValue; ++$d) {
    $gcdCount[$d] += $gcdCount[$d - 1];
}

$answers = [];

foreach ($queryTokens as $token) {
    $query = (int)$token;
    $low = 1;
    $high = $maxValue;

    while ($low < $high) {
        $mid = intdiv($low + $high, 2);

        if ($gcdCount[$mid] > $query) {
            $high = $mid;
        } else {
            $low = $mid + 1;
        }
    }

    $answers[] = (string)$low;
}

echo implode(' ', $answers);

