    for ($city = 0; $city < $n; $city++) {
        $next[$city] = $dp[$city] + $stayScore[$day][$city];
    }

    // Travel from the current city to a different destination.
    for ($curr = 0; $curr < $n; $curr++) {
        $currentPoints = $dp[$curr];

        for ($dest = 0; $dest < $n; $dest++) {
            if ($curr === $dest) {
                continue;
