$numbers = $numberMatches[0];
$offset = count($numbers) - $n;

$parent = [];
for ($i = 0; $i < $n; $i++) {
    $parent[] = (int)$numbers[$offset + $i];
}

unset($input, $stringMatches, $stringTokens, $numberMatches, $numbers);

$head = array_fill(0, $n, -1);
$tail = array_fill(0, $n, -1);
$next = array_fill(0, $n, -1);

for ($node = 1; $node < $n; $node++) {
    $p = $parent[$node];

    if ($head[$p] === -1) {
        $head[$p] = $node;
    } else {
        $next[$tail[$p]] = $node;
    }

    $tail[$p] = $node;
}

unset($tail);

/*
 * Visit each node before its children, processing children in decreasing
 * order. Reversing this order gives the required increasing-child postorder.
 */
$order = [];
$stack = [0];

while (!empty($stack)) {
    $node = array_pop($stack);
    $order[] = $node;

    for ($child = $head[$node]; $child !== -1; $child = $next[$child]) {
        $stack[] = $child;
    }
}

unset($stack, $head, $next);

$position = array_fill(0, $n, 0);
$subtreeSize = array_fill(0, $n, 1);
$postorderString = '';

for ($index = 0; $index < $n; $index++) {
    $node = $order[$n - 1 - $index];

    $position[$node] = $index;
    $postorderString .= $s[$node];

    $p = $parent[$node];
    if ($p >= 0) {
        $subtreeSize[$p] += $subtreeSize[$node];
    }
}

unset($order, $parent, $s);

$answer = array_fill(0, $n, false);

/* Manacher radii for odd-length palindromes. */
$oddRadius = array_fill(0, $n, 0);
$left = 0;
$right = -1;

for ($i = 0; $i < $n; $i++) {
    if ($i > $right) {
        $radius = 1;
    } else {
        $mirror = $left + $right - $i;
        $available = $right - $i + 1;
        $radius = $oddRadius[$mirror] < $available
            ? $oddRadius[$mirror]
            : $available;
    }

    while (
        $i - $radius >= 0 &&
        $i + $radius < $n &&
        $postorderString[$i - $radius] === $postorderString[$i + $radius]
    ) {
        $radius++;
    }

    $oddRadius[$i] = $radius;

    if ($i + $radius - 1 > $right) {
        $left = $i - $radius + 1;
        $right = $i + $radius - 1;
    }
}

for ($node = 0; $node < $n; $node++) {
    $length = $subtreeSize[$node];

    if (($length & 1) === 1) {
        $neededRadius = intdiv($length, 2) + 1;
        $center = $position[$node] - intdiv($length, 2);
        $answer[$node] = $oddRadius[$center] >= $neededRadius;
    }
}

unset($oddRadius);

/* Manacher radii for even-length palindromes. */
$evenRadius = array_fill(0, $n, 0);
$left = 0;
$right = -1;

for ($i = 0; $i < $n; $i++) {
    if ($i > $right) {
        $radius = 0;
    } else {
        $mirror = $left + $right - $i + 1;
        $available = $right - $i + 1;
        $radius = $evenRadius[$mirror] < $available
            ? $evenRadius[$mirror]
            : $available;
    }

    while (
        $i - $radius - 1 >= 0 &&
        $i + $radius < $n &&
        $postorderString[$i - $radius - 1] === $postorderString[$i + $radius]
    ) {
        $radius++;
    }

    $evenRadius[$i] = $radius;

    if ($i + $radius - 1 > $right) {
        $left = $i - $radius;
        $right = $i + $radius - 1;
    }
}

