    $length = $subtreeSize[$node];

    if (($length & 1) === 0) {
        $neededRadius = intdiv($length, 2);
        $center = $position[$node] - $neededRadius + 1;
        $answer[$node] = $evenRadius[$center] >= $neededRadius;
    }
}

$output = [];
for ($i = 0; $i < $n; $i++) {
    $output[] = $answer[$i] ? 'true' : 'false';
}

echo implode(' ', $output), PHP_EOL;
