<?php

const MOD = 1000000007;

function gcdInt(int $a, int $b): int
{
    while ($b !== 0) {
        $temp = $a % $b;
        $a = $b;
        $b = $temp;
    }
    return $a;
}

$input = stream_get_contents(STDIN);
preg_match_all('/\d+/', $input, $matches);
$nums = array_map('intval', $matches[0]);

if (count($nums) === 0) {
    echo "0\n";
    exit;
}

$maxValue = max($nums);
$size = $maxValue + 1;
$stateCount = $size * $size;

// Precompute gcd transitions for every distinct array value.
$gcdTables = [];
foreach ($nums as $value) {
    if (isset($gcdTables[$value])) {
        continue;
    }

    $table = array_fill(0, $size, 0);
    $table[0] = $value;

    for ($g = 1; $g <= $maxValue; $g++) {
        $table[$g] = gcdInt($g, $value);
    }

    $gcdTables[$value] = $table;
}

// dp[g1, g2] counts assignments whose two subsequences have these GCDs.
// GCD 0 represents an empty subsequence.
$dp = array_fill(0, $stateCount, 0);
$dp[0] = 1;

foreach ($nums as $value) {
    $transition = $gcdTables[$value];

    // Leaving the current element unused preserves every state.
    $next = $dp;

    for ($g1 = 0; $g1 <= $maxValue; $g1++) {
        $base = $g1 * $size;
        $newG1Base = $transition[$g1] * $size;

        for ($g2 = 0; $g2 <= $maxValue; $g2++) {
            $count = $dp[$base + $g2];

            if ($count === 0) {
                continue;
            }

            // Add the current element to the first subsequence.
            $target = $newG1Base + $g2;
            $sum = $next[$target] + $count;
            if ($sum >= MOD) {
                $sum -= MOD;
            }
            $next[$target] = $sum;

            // Add the current element to the second subsequence.
            $target = $base + $transition[$g2];
            $sum = $next[$target] + $count;
            if ($sum >= MOD) {
                $sum -= MOD;
            }
            $next[$target] = $sum;
        }
    }

    $dp = $next;
}

$answer = 0;

for ($g = 1; $g <= $maxValue; $g++) {
    $answer += $dp[$g * $size + $g];
    if ($answer >= MOD) {
        $answer -= MOD;
    }
}

echo $answer . PHP_EOL;
