<?php

const MOD = 1000000007;

function modPow(int $base, int $exp): int
{
    $result = 1;
    while ($exp > 0) {
        if ($exp & 1) {
            $result = (int)(($result * $base) % MOD);
        }
        $base = (int)(($base * $base) % MOD);
        $exp >>= 1;
    }
    return $result;
}

function solve(): void
{
    $raw = trim(stream_get_contents(STDIN));

    if (preg_match('/^[0-9]+$/', $raw)) {
        $num = $raw;
    } elseif (preg_match('/"([0-9]+)"/', $raw, $matches)) {
        $num = $matches[1];
    } else {
        preg_match('/[0-9]+/', $raw, $matches);
        $num = $matches[0] ?? '';
    }

    $n = strlen($num);
    $evenSlots = intdiv($n + 1, 2);
    $oddSlots = intdiv($n, 2);

    $velunexorai = $num;

    $counts = array_fill(0, 10, 0);
    $totalSum = 0;

    for ($i = 0; $i < $n; $i++) {
        $digit = ord($velunexorai[$i]) - 48;
        $counts[$digit]++;
        $totalSum += $digit;
    }

    if (($totalSum & 1) !== 0) {
        echo "0\n";
        return;
    }

    $targetSum = intdiv($totalSum, 2);

    $factorial = array_fill(0, $n + 1, 1);
    for ($i = 1; $i <= $n; $i++) {
        $factorial[$i] = (int)(($factorial[$i - 1] * $i) % MOD);
    }

    $inverseFactorial = array_fill(0, $n + 1, 1);
    $inverseFactorial[$n] = modPow($factorial[$n], MOD - 2);
    for ($i = $n; $i >= 1; $i--) {
        $inverseFactorial[$i - 1] = (int)(($inverseFactorial[$i] * $i) % MOD);
    }

    $dp = array_fill(0, $evenSlots + 1, null);
    for ($used = 0; $used <= $evenSlots; $used++) {
        $dp[$used] = array_fill(0, $targetSum + 1, 0);
    }
    $dp[0][0] = 1;

    $processed = 0;

    for ($digit = 0; $digit <= 9; $digit++) {
        $count = $counts[$digit];

        $next = array_fill(0, $evenSlots + 1, null);
        for ($used = 0; $used <= $evenSlots; $used++) {
            $next[$used] = array_fill(0, $targetSum + 1, 0);
        }

        $weights = [];
        for ($take = 0; $take <= $count; $take++) {
            $weights[$take] = (int)(
                ($inverseFactorial[$take] * $inverseFactorial[$count - $take]) % MOD
            );
        }

        $maxUsed = min($evenSlots, $processed);

        for ($used = 0; $used <= $maxUsed; $used++) {
            for ($sum = 0; $sum <= $targetSum; $sum++) {
                $current = $dp[$used][$sum];
                if ($current === 0) {
                    continue;
                }

                $maxTake = min($count, $evenSlots - $used);
                for ($take = 0; $take <= $maxTake; $take++) {
                    $newSum = $sum + $digit * $take;
                    if ($newSum > $targetSum) {
                        break;
                    }

                    $newUsed = $used + $take;
                    $addition = (int)(($current * $weights[$take]) % MOD);
                    $value = $next[$newUsed][$newSum] + $addition;

                    if ($value >= MOD) {
                        $value -= MOD;
                    }

                    $next[$newUsed][$newSum] = $value;
                }
            }
        }

        $dp = $next;
        $processed += $count;
    }

    $answer = $dp[$evenSlots][$targetSum];
    $answer = (int)(($answer * $factorial[$evenSlots]) % MOD);
    $answer = (int)(($answer * $factorial[$oddSlots]) % MOD);

    echo $answer . PHP_EOL;
}

solve();
