$INF = PHP_INT_MAX >> 4;

for ($frequency = 1; $frequency <= $maxFrequency; $frequency++) {
    // State 0: this character's target count is 0.
    // State 1: this character's target count is $frequency.
    $dp = [
        $counts[0],
        abs($counts[0] - $frequency)
    ];

    for ($i = 1; $i < 26; $i++) {
        $next = [$INF, $INF];

        for ($currentState = 0; $currentState <= 1; $currentState++) {
            $currentTarget = $currentState === 1 ? $frequency : 0;
            $baseCost = abs($counts[$i] - $currentTarget);

            for ($previousState = 0; $previousState <= 1; $previousState++) {
                $previousTarget = $previousState === 1 ? $frequency : 0;

                $excess = max(0, $counts[$i - 1] - $previousTarget);
                $deficit = max(0, $currentTarget - $counts[$i]);

                // Changing an excess previous character into the current
                // character saves one operation versus delete + insert.
                $saving = min($excess, $deficit);

                $cost = $dp[$previousState] + $baseCost - $saving;
                if ($cost < $next[$currentState]) {
                    $next[$currentState] = $cost;
                }
            }
        }

        $dp = $next;
    }

    $answer = min($answer, $dp[0], $dp[1]);
}

echo $answer . PHP_EOL;
