function nextInt(string &$data, int &$index, int $length): int
{
    while ($index < $length) {
        $c = ord($data[$index]);
        if ($c >= 48 && $c <= 57) {
            break;
        }
        $index++;
    }

    $number = 0;
    while ($index < $length) {
        $c = ord($data[$index]);
        if ($c < 48 || $c > 57) {
            break;
        }
        $number = $number * 10 + ($c - 48);
        $index++;
    }

    return $number;
}

