        if ($i === 0 && $j === $n - 1) {
            $topRight = $value;
        } elseif ($i >= 1 && $i <= $n - 2 && $j > $i) {
            $best = $upperPrev[$j];

            if ($j > 0 && $upperPrev[$j - 1] > $best) {
                $best = $upperPrev[$j - 1];
            }
            if ($j + 1 < $n && $upperPrev[$j + 1] > $best) {
                $best = $upperPrev[$j + 1];
            }

            $upperCurrent[$j] = $best + $value;
        }
    }

    $lowerRows[] = $lowerRow;

    if ($i === 0) {
        $upperPrev = array_fill(0, $n, $negativeInfinity);
        $upperPrev[$n - 1] = $topRight;
    } elseif ($i <= $n - 2) {
        $upperPrev = $upperCurrent;
    }
}

