            $best = $lowerPrev[$row - 1];
        }
        if ($row + 1 < $n && $lowerPrev[$row + 1] > $best) {
            $best = $lowerPrev[$row + 1];
        }

        $lowerCurrent[$row] = $best + $lowerRows[$row][$column];
    }

    $lowerPrev = $lowerCurrent;
}

$lowerMaximum = $lowerPrev[$n - 1];
$answer = $diagonalSum + $upperMaximum + $lowerMaximum;

