    $op2Value = $canOp2 ? $x - $k : 0;

    $canBoth = false;
    $bothValue = $inf;

    // Operation 2 followed by Operation 1.
    if ($x >= $k) {
        $canBoth = true;
        $bothValue = intdiv(($x - $k) + 1, 2);
    }

    // Operation 1 followed by Operation 2.
    if ($half >= $k) {
        $canBoth = true;
        $bothValue = min($bothValue, $half - $k);
    }

