<?php

function findRoot(array &$parent, int $node): int
{
    while ($parent[$node] !== $node) {
        $parent[$node] = $parent[$parent[$node]];
        $node = $parent[$node];
    }
    return $node;
}

$input = file_get_contents('php://stdin');
preg_match_all('/\d+/', $input, $matches);
$tokens = $matches[0];

$threshold = (int) array_pop($tokens);
$components = count($tokens);

$owner = array_fill(0, $threshold + 1, -1);
$parent = [];
$size = [];

foreach ($tokens as $token) {
    $value = (int) $token;

    // Any value greater than the threshold cannot have an edge.
    if ($value > $threshold) {
        continue;
    }

    $id = count($parent);
    $parent[] = $id;
    $size[] = 1;

    for ($multiple = $value; $multiple <= $threshold; $multiple += $value) {
        $other = $owner[$multiple];

        if ($other === -1) {
            $owner[$multiple] = $id;
            continue;
        }

        $rootA = findRoot($parent, $id);
        $rootB = findRoot($parent, $other);

        if ($rootA === $rootB) {
            continue;
        }

        if ($size[$rootA] < $size[$rootB]) {
            [$rootA, $rootB] = [$rootB, $rootA];
        }

        $parent[$rootB] = $rootA;
        $size[$rootA] += $size[$rootB];
        $components--;
    }
}

echo $components, PHP_EOL;
