const MOD = 1000000007;

function modPow(int $base, int $exponent): int
{
    $base %= MOD;
    $result = 1;

    while ($exponent > 0) {
        if ($exponent & 1) {
            $result = ($result * $base) % MOD;
        }
        $base = ($base * $base) % MOD;
        $exponent = intdiv($exponent, 2);
    }

    return $result;
}

