    $factorialN = ($factorialN * $i) % MOD;
}

$factorialK = 1;
for ($i = 2; $i <= $k; $i++) {
    $factorialK = ($factorialK * $i) % MOD;
}

$remaining = $totalTransitions - $k;
$factorialRemaining = 1;
for ($i = 2; $i <= $remaining; $i++) {
    $factorialRemaining = ($factorialRemaining * $i) % MOD;
