$denominator = ($factorialK * $factorialRemaining) % MOD;
$combination = ($factorialN * modPow($denominator, MOD - 2)) % MOD;

$differentChoices = modPow($m - 1, $remaining);

$answer = (($m % MOD) * $combination) % MOD;
$answer = ($answer * $differentChoices) % MOD;

