// Z-array: z[i] is the common-prefix length of nums and nums[i...].
$z = array_fill(0, $n, 0);
$z[0] = $n;
$left = 0;
$right = 0;

for ($i = 1; $i < $n; ++$i) {
    if ($i <= $right) {
        $z[$i] = min($right - $i + 1, $z[$i - $left]);
    }

    while (
        $i + $z[$i] < $n &&
        $nums[$z[$i]] === $nums[$i + $z[$i]]
    ) {
        ++$z[$i];
    }

    if ($i + $z[$i] - 1 > $right) {
        $left = $i;
        $right = $i + $z[$i] - 1;
    }
}

$answer = 0;

// Count splits where nums1 is a prefix of nums2.
for ($i = 1; 2 * $i <= $n - 1; ++$i) {
    if ($z[$i] >= $i) {
        $answer += $n - 2 * $i;
    }
}

// Rolling LCP rows. lcp[i][j] = common-prefix length of nums[i...] and nums[j...].
$row0 = array_fill(0, $n + 1, 0);
$row1 = array_fill(0, $n + 1, 0);

for ($i = $n - 2; $i >= 1; --$i) {
    $maxBeautifulJ = intdiv($n + $i, 2);
    $firstConditionValid = ($z[$i] >= $i);
    $firstConditionThreshold = 2 * $i;
    $value = $nums[$i];

    if (($i & 1) === 0) {
        for ($j = $n - 1; $j > $maxBeautifulJ; --$j) {
            $row0[$j] = ($value === $nums[$j])
                ? $row1[$j + 1] + 1
                : 0;
        }

        for ($j = $maxBeautifulJ; $j > $i; --$j) {
            if ($value === $nums[$j]) {
                $lcp = $row1[$j + 1] + 1;
                $row0[$j] = $lcp;

