<?php

function pointUpdate(
    int $position,
    int $value,
    int $base,
    array &$sum,
    array &$prefix,
    array &$suffix,
    array &$best
): void {
    $index = $base + $position;

    $sum[$index] = $value;
    $prefix[$index] = $value;
    $suffix[$index] = $value;
    $best[$index] = $value;

    while ($index > 1) {
        $index >>= 1;
        $left = $index << 1;
        $right = $left + 1;

        $sum[$index] = $sum[$left] + $sum[$right];
        $prefix[$index] = max(
            $prefix[$left],
            $sum[$left] + $prefix[$right]
        );
        $suffix[$index] = max(
            $suffix[$right],
            $sum[$right] + $suffix[$left]
        );
        $best[$index] = max(
            $best[$left],
            $best[$right],
            $suffix[$left] + $prefix[$right]
        );
    }
}

