            ($leftX * $leftNonX) * choose2($rightNonX)
            + choose2($leftNonX) * ($rightX * $rightNonX);

        $atLeastThreeX = $allChoices - $noExtraX - $oneExtraX;

        /*
         * Cases where x occurs exactly twice. The other three values must
         * be pairwise distinct for x to be the unique mode.
         */
        $samePairsLeftNonX = $sumSameLeft - choose2($leftX);
        $samePairsRightNonX = $sumSameRight - choose2($rightX);

        $distinctPairsLeft =
            choose2($leftNonX) - $samePairsLeftNonX;
        $distinctPairsRight =
            choose2($rightNonX) - $samePairsRightNonX;

        $crossRight = 0;
        $crossLeft = 0;

        foreach ($left as $value => $leftCount) {
            if ($value === $x) {
                continue;
            }

            $rightCount = $right[$value] ?? 0;
            if ($rightCount === 0) {
                continue;
            }

            $common = $leftCount * $rightCount;
            $crossRight += $common * ($rightNonX - $rightCount);
            $crossLeft += $common * ($leftNonX - $leftCount);
        }

        $exactlyTwoX =
            $leftX * (
                $leftNonX * $distinctPairsRight - $crossRight
            )
            + $rightX * (
                $rightNonX * $distinctPairsLeft - $crossLeft
            );

        $answer = ($answer + $atLeastThreeX + $exactlyTwoX) % $MOD;
    }

    // Add the current element to the left side.
    $oldLeftCount = $left[$x] ?? 0;
    $sumSameLeft += $oldLeftCount;
    $left[$x] = $oldLeftCount + 1;
}

echo $answer . PHP_EOL;
