<?php

function bfsDistances(string $grid, int $totalCells, int $source, array &$targets): array
{
    $dist = array_fill(0, $totalCells, -1);
    $queue = [$source];
    $head = 0;
    $tail = 1;
    $dist[$source] = 0;

    while ($head < $tail) {
        $current = $queue[$head++];
        $nextDistance = $dist[$current] + 1;

        $next = $current - 1;
        if ($grid[$next] !== '#' && $dist[$next] === -1) {
            $dist[$next] = $nextDistance;
            $queue[$tail++] = $next;
        }

        $next = $current + 1;
        if ($grid[$next] !== '#' && $dist[$next] === -1) {
            $dist[$next] = $nextDistance;
            $queue[$tail++] = $next;
        }

        global $stride;

        $next = $current - $stride;
        if ($grid[$next] !== '#' && $dist[$next] === -1) {
            $dist[$next] = $nextDistance;
            $queue[$tail++] = $next;
        }

        $next = $current + $stride;
        if ($grid[$next] !== '#' && $dist[$next] === -1) {
            $dist[$next] = $nextDistance;
            $queue[$tail++] = $next;
        }
    }

    $result = [];
    foreach ($targets as $position) {
        $result[] = $dist[$position];
    }

    return $result;
}

[$H, $W, $T] = array_map(
    'intval',
    preg_split('/\s+/', trim(fgets(STDIN)))
);

$stride = $W + 2;
$grid = str_repeat('#', $stride);
$start = -1;
$goal = -1;
$candies = [];

for ($r = 0; $r < $H; ++$r) {
    $line = rtrim(fgets(STDIN), "\r\n");
    $grid .= '#' . $line . '#';

    for ($c = 0; $c < $W; ++$c) {
        $position = ($r + 1) * $stride + ($c + 1);
        $cell = $line[$c];

        if ($cell === 'S') {
            $start = $position;
        } elseif ($cell === 'G') {
            $goal = $position;
        } elseif ($cell === 'o') {
            $candies[] = $position;
        }
    }
}

$grid .= str_repeat('#', $stride);
$totalCells = ($H + 2) * $stride;

$candyCount = count($candies);
$targets = array_merge([$start], $candies, [$goal]);
$goalIndex = $candyCount + 1;

$startDistances = bfsDistances($grid, $totalCells, $start, $targets);

if ($startDistances[$goalIndex] === -1 || $startDistances[$goalIndex] > $T) {
    echo "-1\n";
    exit;
}

$rows = [0 => $startDistances];
$viableOldIndices = [];

for ($oldIndex = 0; $oldIndex < $candyCount; ++$oldIndex) {
    $distanceFromStart = $startDistances[$oldIndex + 1];

    if ($distanceFromStart === -1 || $distanceFromStart > $T) {
        continue;
    }

    $row = bfsDistances(
        $grid,
        $totalCells,
        $candies[$oldIndex],
        $targets
    );
    $rows[$oldIndex + 1] = $row;

    $distanceToGoal = $row[$goalIndex];
    if (
        $distanceToGoal !== -1 &&
        $distanceFromStart + $distanceToGoal <= $T
    ) {
        $viableOldIndices[] = $oldIndex;
    }
}

$n = count($viableOldIndices);

if ($n === 0) {
    echo "0\n";
    exit;
}

$distanceFromStart = [];
$distanceToGoal = [];
$between = [];

for ($i = 0; $i < $n; ++$i) {
    $oldI = $viableOldIndices[$i];
    $distanceFromStart[$i] = $startDistances[$oldI + 1];
    $distanceToGoal[$i] = $rows[$oldI + 1][$goalIndex];

    $between[$i] = [];
    for ($j = 0; $j < $n; ++$j) {
        $oldJ = $viableOldIndices[$j];
        $between[$i][$j] = $rows[$oldI + 1][$oldJ + 1];
    }
}

unset($grid, $rows, $targets, $candies, $startDistances);

$totalMasks = 1 << $n;
$fullMask = $totalMasks - 1;
$infinity = $T + 1;

$dp = array_fill(0, $totalMasks * $n, $infinity);

$bitIndex = str_repeat("\0", $totalMasks);
for ($i = 0; $i < $n; ++$i) {
    $bitIndex[1 << $i] = chr($i);
}

$popcount = str_repeat("\0", $totalMasks);
for ($mask = 1; $mask < $totalMasks; ++$mask) {
    $popcount[$mask] = chr(
        ord($popcount[$mask >> 1]) + ($mask & 1)
    );
}

for ($i = 0; $i < $n; ++$i) {
    $mask = 1 << $i;
    $dp[$mask * $n + $i] = $distanceFromStart[$i];
}

$answer = 0;

for ($mask = 1; $mask < $totalMasks; ++$mask) {
    $base = $mask * $n;
    $remaining = $fullMask ^ $mask;
    $bits = $mask;
    $hasFeasibleState = false;

    while ($bits !== 0) {
        $bit = $bits & (-$bits);
        $bits -= $bit;
        $i = ord($bitIndex[$bit]);

        $currentDistance = $dp[$base + $i];
        if ($currentDistance > $T) {
            continue;
        }

        if (!$hasFeasibleState) {
            $count = ord($popcount[$mask]);
            if ($count > $answer) {
                $answer = $count;
            }
            $hasFeasibleState = true;
        }

        $nextBits = $remaining;
        $steps = $between[$i];

        while ($nextBits !== 0) {
            $nextBit = $nextBits & (-$nextBits);
            $nextBits -= $nextBit;
            $j = ord($bitIndex[$nextBit]);

            $stepDistance = $steps[$j];
            if ($stepDistance === -1) {
                continue;
            }

            $newDistance = $currentDistance + $stepDistance;

            if ($newDistance + $distanceToGoal[$j] > $T) {
                continue;
            }

            $newMask = $mask | $nextBit;
            $newIndex = $newMask * $n + $j;

            if ($newDistance < $dp[$newIndex]) {
                $dp[$newIndex] = $newDistance;
            }
        }
    }
}

echo $answer . "\n";
