    $inv[$i] = MOD - (intdiv(MOD, $i) * $inv[MOD % $i]) % MOD;
}

$dp = array_fill(0, 27, 0);
$dp[0] = 1;

$maxT = 0;
$fixedUpperCount = 0;
$fixedUpperMask = 0;
$validDistinctPrefix = true;
$distinctTotal = 1;

$safePrefix = [1];

$monoUpper = 1;
$monoLower = 0;

for ($i = 0; $i < $n; $i++) {
    $ord = ord($S[$i]);

    if ($ord === 63) { // ?
        $upperWays = 26;
        $lowerWays = 26;
    } elseif ($ord >= 65 && $ord <= 90) {
        $upperWays = 1;
        $lowerWays = 0;
    } else {
        $upperWays = 0;
        $lowerWays = 1;
    }

    $combined = $monoUpper + $monoLower;
    if ($combined >= MOD) {
        $combined -= MOD;
    }
    $monoLower = ($combined * $lowerWays) % MOD;
    $monoUpper = ($monoUpper * $upperWays) % MOD;

    if ($validDistinctPrefix) {
        if ($ord === 63) {
            $remainingLetters = 26 - $fixedUpperCount;
            $newMaxT = min($maxT + 1, $remainingLetters);
            $sum = 0;

            for ($t = $newMaxT; $t >= 1; $t--) {
                $value = (
                    26 * $dp[$t]
                    + ($remainingLetters - $t + 1) * $dp[$t - 1]
                ) % MOD;
                $dp[$t] = $value;
                $sum += $value;
                if ($sum >= MOD) {
                    $sum -= MOD;
                }
            }

            $dp[0] = (26 * $dp[0]) % MOD;
            $sum += $dp[0];
            if ($sum >= MOD) {
                $sum -= MOD;
            }

            $maxT = $newMaxT;
            $distinctTotal = $sum;
        } elseif ($ord >= 65 && $ord <= 90) {
            $bit = 1 << ($ord - 65);

            if (($fixedUpperMask & $bit) !== 0) {
                $validDistinctPrefix = false;
                $distinctTotal = 0;
            } else {
                $fixedUpperMask |= $bit;
                $remainingLetters = 26 - $fixedUpperCount;
                $newMaxT = min($maxT, $remainingLetters - 1);
                $sum = 0;

                for ($t = 0; $t <= $newMaxT; $t++) {
                    $value = ($dp[$t] * ($remainingLetters - $t)) % MOD;
                    $value = ($value * $inv[$remainingLetters]) % MOD;
                    $dp[$t] = $value;
                    $sum += $value;
                    if ($sum >= MOD) {
                        $sum -= MOD;
                    }
                }

                for ($t = $newMaxT + 1; $t <= $maxT; $t++) {
                    $dp[$t] = 0;
                }

                $maxT = $newMaxT;
                $fixedUpperCount++;
                $distinctTotal = $sum;
            }
        }
    }

    $safePrefix[] = $distinctTotal;
}

$answer = $monoUpper + $monoLower;
if ($answer >= MOD) {
    $answer -= MOD;
}

$lastOrd = ord($S[$n - 1]);
if ($lastOrd === 63) {
    $nextUpperWays = 26;
    $nextLowerWays = 26;
} elseif ($lastOrd >= 65 && $lastOrd <= 90) {
    $nextUpperWays = 1;
    $nextLowerWays = 0;
} else {
    $nextUpperWays = 0;
    $nextLowerWays = 1;
}

$bNext = 0;
$lowerSuffixAfterNext = 1;

for ($pivot = $n - 2; $pivot >= 0; $pivot--) {
    $inside = $lowerSuffixAfterNext + $bNext;
    if ($inside >= MOD) {
        $inside -= MOD;
