    if ($pivotLowerWays !== 0 && $bCurrent !== 0 && $safePrefix[$pivot] !== 0) {
        $term = ($safePrefix[$pivot] * $pivotLowerWays) % MOD;
        $term = ($term * $bCurrent) % MOD;
        $answer += $term;
        if ($answer >= MOD) {
            $answer -= MOD;
        }
    }

    $lowerSuffixAfterNext = ($lowerSuffixAfterNext * $nextLowerWays) % MOD;
    $bNext = $bCurrent;
    $nextUpperWays = $pivotUpperWays;
    $nextLowerWays = $pivotLowerWays;
}

echo $answer, PHP_EOL;
