<?php

final class FastScanner
{
    private string $data;
    private int $index = 0;
    private int $length;

    public function __construct()
    {
        $this->data = file_get_contents('php://stdin');
        $this->length = strlen($this->data);
    }

    public function nextInt(): int
    {
        while ($this->index < $this->length && ord($this->data[$this->index]) <= 32) {
            $this->index++;
        }

        $number = 0;
        while ($this->index < $this->length) {
            $c = ord($this->data[$this->index]);
            if ($c < 48 || $c > 57) {
                break;
            }
            $number = $number * 10 + ($c - 48);
            $this->index++;
        }

        return $number;
    }
}

$scanner = new FastScanner();
$n = $scanner->nextInt();

$graph = array_fill(0, $n, []);

for ($i = 0; $i < $n - 1; $i++) {
    $u = $scanner->nextInt() - 1;
    $v = $scanner->nextInt() - 1;
    $graph[$u][] = $v;
    $graph[$v][] = $u;
}

$start = 0;
for ($i = 0; $i < $n; $i++) {
    if (count($graph[$i]) === 1) {
        $start = $i;
        break;
    }
}

$distance = array_fill(0, $n, -1);
$distance[$start] = 0;

$queue = [$start];
$head = 0;
$levels = [];

while ($head < count($queue)) {
    $vertex = $queue[$head++];

    if ($distance[$vertex] % 3 === 1) {
        $levels[] = count($graph[$vertex]);
    }

    foreach ($graph[$vertex] as $next) {
        if ($distance[$next] !== -1) {
            continue;
        }

        $distance[$next] = $distance[$vertex] + 1;
        $queue[] = $next;
    }
}

sort($levels, SORT_NUMERIC);
echo implode(' ', $levels), PHP_EOL;
