$input = file_get_contents("php://stdin");
$pos = 0;
$inputLength = strlen($input);

function nextInt(): int
{
    global $input, $pos, $inputLength;

    while ($pos < $inputLength && ord($input[$pos]) <= 32) {
        ++$pos;
    }

    $value = 0;
    while ($pos < $inputLength) {
        $code = ord($input[$pos]);
        if ($code < 48 || $code > 57) {
            break;
        }
        $value = $value * 10 + ($code - 48);
        ++$pos;
    }

    return $value;
}

function findRoot(array &$dsu, int $x): int
{
    $root = $x;
    while ($dsu[$root] >= 0) {
        $root = $dsu[$root];
    }

    while ($x !== $root) {
        $parent = $dsu[$x];
        $dsu[$x] = $root;
        $x = $parent;
    }

    return $root;
}

function unite(array &$dsu, int $a, int $b): void
{
    $a = findRoot($dsu, $a);
    $b = findRoot($dsu, $b);

    if ($a === $b) {
        return;
    }

    if ($dsu[$a] > $dsu[$b]) {
        [$a, $b] = [$b, $a];
    }

    $dsu[$a] += $dsu[$b];
    $dsu[$b] = $a;
}

$n = nextInt();
$m = nextInt();

$dsu = array_fill(0, $n + 1, -1);

for ($i = 0; $i < $m; ++$i) {
    $u = nextInt();
    $v = nextInt();
    unite($dsu, $u, $v);
}

$component = array_fill(0, $n + 1, 0);
for ($i = 1; $i <= $n; ++$i) {
    $component[$i] = findRoot($dsu, $i);
}

$base = $n + 1;
$forbidden = [];

$k = nextInt();
for ($i = 0; $i < $k; ++$i) {
    $x = nextInt();
    $y = nextInt();

    $a = $component[$x];
    $b = $component[$y];

    if ($a > $b) {
        [$a, $b] = [$b, $a];
    }

    $key = $a * $base + $b;
    $forbidden[$key] = true;
}

$q = nextInt();
$output = '';

for ($i = 0; $i < $q; ++$i) {
    $p = nextInt();
    $qVertex = nextInt();

