    $b = $component[$qVertex];

    if ($a > $b) {
        [$a, $b] = [$b, $a];
    }

    $key = $a * $base + $b;
    $output .= isset($forbidden[$key]) ? "No\n" : "Yes\n";
}

echo $output;
