function sleptUntil(int $time, array &$times, array &$prefix, int $n): int
{
    // Find the greatest index i such that times[i] <= time.
    $low = 0;
    $high = $n;

    while ($low < $high) {
        $mid = intdiv($low + $high, 2);
        if ($times[$mid] <= $time) {
            $low = $mid + 1;
        } else {
            $high = $mid;
        }
    }

    $index = $low - 1;
    $result = $prefix[$index];

    // At odd zero-based indices, Takahashi has just fallen asleep.
    if (($index & 1) === 1) {
        $result += $time - $times[$index];
    }

    return $result;
}

$n = nextInt();

