for ($i = 0; $i < $n; $i++) {
    $times[$i] = nextInt();
}

$prefix = array_fill(0, $n, 0);
for ($i = 1; $i < $n; $i++) {
    $prefix[$i] = $prefix[$i - 1];
    if (($i & 1) === 0) {
        $prefix[$i] += $times[$i] - $times[$i - 1];
    }
}

$q = nextInt();
$output = '';

for ($i = 0; $i < $q; $i++) {
    $left = nextInt();
    $right = nextInt();

    $answer = sleptUntil($right, $times, $prefix, $n)
            - sleptUntil($left, $times, $prefix, $n);

    $output .= $answer . "\n";
}

echo $output;
