<?php

function nextInt(string $data, int &$pos, int $length): int
{
    while ($pos < $length && ord($data[$pos]) <= 32) {
        ++$pos;
    }

    $value = 0;
    while ($pos < $length) {
        $c = ord($data[$pos]);
        if ($c < 48 || $c > 57) {
            break;
        }
        $value = $value * 10 + ($c - 48);
        ++$pos;
    }

    return $value;
}

$input = file_get_contents('php://stdin');
$inputLength = strlen($input);
$pos = 0;

$n = nextInt($input, $pos, $inputLength);
$k = nextInt($input, $pos, $inputLength);
$q = nextInt($input, $pos, $inputLength);

$positions = [];
$newRanks = [];
$values = [0];

for ($i = 0; $i < $q; ++$i) {
    $x = nextInt($input, $pos, $inputLength);
    $y = nextInt($input, $pos, $inputLength);

    $positions[] = $x - 1;
    $newRanks[] = $y;
    $values[] = $y;
}

unset($input);

sort($values, SORT_NUMERIC);
$valueCount = count($values);

$rankByValue = [];
for ($i = 0; $i < $valueCount; ++$i) {
    $rankByValue[$values[$i]] = $i + 1;
}

for ($i = 0; $i < $q; ++$i) {
    $newRanks[$i] = $rankByValue[$newRanks[$i]];
}

$zeroRank = $rankByValue[0];
unset($rankByValue);

$currentRanks = array_fill(0, $n, $zeroRank);
$countTree = array_fill(0, $valueCount + 1, 0);
$sumTree = array_fill(0, $valueCount + 1, 0);

for ($i = $zeroRank; $i <= $valueCount; $i += $i & (-$i)) {
    $countTree[$i] += $n;
}

$maxPower = 1;
while (($maxPower << 1) <= $valueCount) {
    $maxPower <<= 1;
}

$smallestCount = $n - $k;
$totalSum = 0;
$output = '';

for ($query = 0; $query < $q; ++$query) {
    $arrayIndex = $positions[$query];
    $oldRank = $currentRanks[$arrayIndex];
    $newRank = $newRanks[$query];

    if ($oldRank !== $newRank) {
        $oldValue = $values[$oldRank - 1];
        $newValue = $values[$newRank - 1];

        for ($i = $oldRank; $i <= $valueCount; $i += $i & (-$i)) {
            --$countTree[$i];
            $sumTree[$i] -= $oldValue;
        }

        for ($i = $newRank; $i <= $valueCount; $i += $i & (-$i)) {
            ++$countTree[$i];
            $sumTree[$i] += $newValue;
        }

        $currentRanks[$arrayIndex] = $newRank;
        $totalSum += $newValue - $oldValue;
    }

    if ($smallestCount === 0) {
        $answer = $totalSum;
    } else {
        $index = 0;
        $countBefore = 0;
        $sumBefore = 0;

        for ($step = $maxPower; $step > 0; $step >>= 1) {
            $next = $index + $step;
            if ($next <= $valueCount) {
                $candidateCount = $countBefore + $countTree[$next];
                if ($candidateCount < $smallestCount) {
                    $index = $next;
                    $countBefore = $candidateCount;
                    $sumBefore += $sumTree[$next];
                }
            }
        }

        $remaining = $smallestCount - $countBefore;
        $smallestSum = $sumBefore + $remaining * $values[$index];
        $answer = $totalSum - $smallestSum;
    }

    $output .= $answer . "\n";
}

echo $output;
