    $a = (int)$data[$pos++] - 1;
    $b = (int)$data[$pos++] - 1;
    $incompatible[$a] |= 1 << $b;
    $incompatible[$b] |= 1 << $a;
}

// Processing highly constrained players first reduces the search space.
$order = range(0, $N - 1);
usort($order, function (int $a, int $b) use ($incompatible): int {
    $degreeA = substr_count(decbin($incompatible[$a]), '1');
    $degreeB = substr_count(decbin($incompatible[$b]), '1');
    return $degreeB <=> $degreeA;
});

$teams = array_fill(0, $T, 0);

$search = function (int $index, int $usedTeams) use (
    &$search,
    &$teams,
    $order,
    $incompatible,
    $N,
    $T
): int {
    if ($usedTeams > $T || $usedTeams + ($N - $index) < $T) {
        return 0;
    }

    if ($index === $N) {
        return $usedTeams === $T ? 1 : 0;
    }

    $player = $order[$index];
    $playerBit = 1 << $player;
    $count = 0;

    // Put the player into an existing compatible team.
    for ($team = 0; $team < $usedTeams; $team++) {
        if (($teams[$team] & $incompatible[$player]) === 0) {
            $teams[$team] |= $playerBit;
            $count += $search($index + 1, $usedTeams);
            $teams[$team] ^= $playerBit;
        }
    }

    // Create one new team. This canonical rule avoids counting team labels.
    if ($usedTeams < $T) {
        $teams[$usedTeams] = $playerBit;
        $count += $search($index + 1, $usedTeams + 1);
        $teams[$usedTeams] = 0;
    }

    return $count;
};

echo $search(0, 0), PHP_EOL;
