<?php

const MOD = 998244353;
const MASK_LIMIT = 2047; // Bits 0 through 10.

function modPow(int $base, int $exp): int
{
    $result = 1;
    while ($exp > 0) {
        if ($exp & 1) {
            $result = (int)(($result * $base) % MOD);
        }
        $base = (int)(($base * $base) % MOD);
        $exp >>= 1;
    }
    return $result;
}

$tokens = preg_split('/\s+/', trim(stream_get_contents(STDIN)));
$index = 0;
$n = (int)$tokens[$index++];

$dp = array_fill(0, 2048, 0);
$dp[1] = 1; // Only sum 0 is initially achievable.

for ($i = 0; $i < $n; ++$i) {
    $a = (int)$tokens[$index++];
    $inverseA = modPow($a, MOD - 2);
    $limit = min($a, 10);
    $largeCount = max(0, $a - 10);

    $next = array_fill(0, 2048, 0);

    for ($mask = 0; $mask < 2048; ++$mask) {
        $probability = $dp[$mask];
        if ($probability === 0) {
            continue;
        }

        $unitProbability = (int)(($probability * $inverseA) % MOD);

        if ($largeCount > 0) {
            $add = (int)(($unitProbability * $largeCount) % MOD);
            $next[$mask] += $add;
            if ($next[$mask] >= MOD) {
                $next[$mask] -= MOD;
            }
        }

        for ($value = 1; $value <= $limit; ++$value) {
            $newMask = $mask | (($mask << $value) & MASK_LIMIT);
            $next[$newMask] += $unitProbability;
            if ($next[$newMask] >= MOD) {
                $next[$newMask] -= MOD;
            }
        }
    }

    $dp = $next;
}

$answer = 0;
for ($mask = 0; $mask < 2048; ++$mask) {
    if (($mask & (1 << 10)) !== 0) {
        $answer += $dp[$mask];
        if ($answer >= MOD) {
            $answer -= MOD;
        }
    }
}

echo $answer . PHP_EOL;
