$scanner = new FastScanner();

$n = $scanner->nextInt();
$m = $scanner->nextInt();

$pullTabCans = [];
$regularCans = [];
$openers = [];

for ($i = 0; $i < $n; $i++) {
    $type = $scanner->nextInt();
    $value = $scanner->nextInt();

    if ($type === 0) {
        $pullTabCans[] = $value;
    } elseif ($type === 1) {
        $regularCans[] = $value;
    } else {
        $openers[] = $value;
    }
}

rsort($pullTabCans, SORT_NUMERIC);
rsort($regularCans, SORT_NUMERIC);
rsort($openers, SORT_NUMERIC);

$pullTabCount = count($pullTabCans);
$regularCount = count($regularCans);
$openerCount = count($openers);

for ($i = 1; $i < $pullTabCount; $i++) {
    $pullTabCans[$i] += $pullTabCans[$i - 1];
}

$answer = 0;
$regularSum = 0;
$capacity = 0;
$usedOpeners = 0;
$maxRegular = min($regularCount, $m);

for ($usedRegular = 0; $usedRegular <= $maxRegular; $usedRegular++) {
    if ($usedRegular > 0) {
        $regularSum += $regularCans[$usedRegular - 1];
    }

    while ($capacity < $usedRegular && $usedOpeners < $openerCount) {
        $capacity += $openers[$usedOpeners];
        $usedOpeners++;
    }

    if ($capacity < $usedRegular || $usedRegular + $usedOpeners > $m) {
        break;
    }

    $remainingSlots = $m - $usedRegular - $usedOpeners;
    $takePullTabs = min($remainingSlots, $pullTabCount);
    $pullTabSum = $takePullTabs > 0 ? $pullTabCans[$takePullTabs - 1] : 0;

    $answer = max($answer, $regularSum + $pullTabSum);
}

echo $answer, PHP_EOL;
