<?php

const MOD = 998244353;

final class FastScanner
{
    private string $data;
    private int $index = 0;
    private int $length;

    public function __construct()
    {
        $this->data = file_get_contents('php://stdin');
        $this->length = strlen($this->data);
    }

    public function nextInt(): int
    {
        while ($this->index < $this->length) {
            $c = ord($this->data[$this->index]);
            if ($c > 32) {
                break;
            }
            ++$this->index;
        }

        $value = 0;
        while ($this->index < $this->length) {
            $c = ord($this->data[$this->index]);
            if ($c < 48 || $c > 57) {
                break;
            }
            $value = $value * 10 + ($c - 48);
            ++$this->index;
        }

        return $value;
    }
}

function findRoot(array &$dsu, int $x): int
{
    $root = $x;
    while ($dsu[$root] >= 0) {
        $root = $dsu[$root];
    }

    while ($x !== $root) {
        $parent = $dsu[$x];
        $dsu[$x] = $root;
        $x = $parent;
    }

    return $root;
}

$scanner = new FastScanner();
$n = $scanner->nextInt();

$inverse = array_fill(0, $n + 1, 0);
$inverse[1] = 1;
for ($i = 2; $i <= $n; ++$i) {
    $inverse[$i] = MOD - (intdiv(MOD, $i) * $inverse[MOD % $i]) % MOD;
}

$dsu = array_fill(0, $n + 1, -1);
$componentNode = range(0, $n);

$nodeCount = 2 * $n;
$treeParent = array_fill(0, $nodeCount, 0);
$weight = array_fill(0, $nodeCount, 0);

for ($match = 1; $match < $n; ++$match) {
    $p = $scanner->nextInt();
    $q = $scanner->nextInt();

    $rootP = findRoot($dsu, $p);
    $rootQ = findRoot($dsu, $q);

    $sizeP = -$dsu[$rootP];
    $sizeQ = -$dsu[$rootQ];
    $totalSize = $sizeP + $sizeQ;

    $nodeP = $componentNode[$rootP];
    $nodeQ = $componentNode[$rootQ];
    $newNode = $n + $match;

    $treeParent[$nodeP] = $newNode;
    $treeParent[$nodeQ] = $newNode;

    $weight[$nodeP] = ($sizeP * $inverse[$totalSize]) % MOD;
    $weight[$nodeQ] = ($sizeQ * $inverse[$totalSize]) % MOD;

    if ($dsu[$rootP] > $dsu[$rootQ]) {
        $tmp = $rootP;
        $rootP = $rootQ;
        $rootQ = $tmp;
    }

    $dsu[$rootP] += $dsu[$rootQ];
    $dsu[$rootQ] = $rootP;
    $componentNode[$rootP] = $newNode;
}

unset($scanner, $inverse, $dsu, $componentNode);

$rootNode = 2 * $n - 1;
for ($node = $rootNode - 1; $node >= 1; --$node) {
    $value = $weight[$node] + $weight[$treeParent[$node]];
    if ($value >= MOD) {
        $value -= MOD;
    }
    $weight[$node] = $value;
}

$output = (string)$weight[1];
for ($i = 2; $i <= $n; ++$i) {
    $output .= ' ' . $weight[$i];
}

echo $output, "\n";
