<?php

$input = file_get_contents("php://stdin");
$inputIndex = 0;
$inputLength = strlen($input);

function nextInt(): int
{
    global $input, $inputIndex, $inputLength;

    while ($inputIndex < $inputLength && ord($input[$inputIndex]) <= 32) {
        $inputIndex++;
    }

    $value = 0;
    while ($inputIndex < $inputLength) {
        $c = ord($input[$inputIndex]);
        if ($c < 48 || $c > 57) {
            break;
        }
        $value = $value * 10 + ($c - 48);
        $inputIndex++;
    }

    return $value;
}

function gcdInt(int $a, int $b): int
{
    while ($b !== 0) {
        $tmp = $a % $b;
        $a = $b;
        $b = $tmp;
    }
    return $a;
}

$N = nextInt();
$X = nextInt();
$Y = nextInt();

$routeCount = $N - 1;
$periods = [];
$travelTimes = [];
$lcm = 1;

for ($i = 0; $i < $routeCount; $i++) {
    $p = nextInt();
    $t = nextInt();

    $periods[$i] = $p;
    $travelTimes[$i] = $t;

    if ($lcm % $p !== 0) {
        $lcm = intdiv($lcm, gcdInt($lcm, $p)) * $p;
    }
}

/*
 * Groups contain consecutive starting residues that currently have the
 * same arrival time. Travel times common to every residue are kept in
 * $offset, while residue-dependent waiting times are stored in $values.
 */
$values = [];
$ends = [];

for ($r = 0; $r < $lcm; $r++) {
    $values[$r] = $r;
    $ends[$r] = $r;
}

$groupCount = $lcm;
$differenceGcd = ($lcm > 1) ? 1 : 0;
$offset = 0;

for ($i = 0; $i < $routeCount; $i++) {
    $p = $periods[$i];
    $t = $travelTimes[$i];

    if ($p === 1) {
        $offset += $t;
        continue;
    }

    // All group values have the same residue modulo p.
    if ($differenceGcd % $p === 0) {
        $remainder = ($values[0] + $offset) % $p;
        $wait = ($remainder === 0) ? 0 : ($p - $remainder);
        $offset += $wait + $t;
        continue;
    }

    $write = 0;
    $newGcd = 0;
    $previousValue = 0;

    for ($read = 0; $read < $groupCount; $read++) {
        $value = $values[$read];
        $remainder = ($value + $offset) % $p;
        if ($remainder !== 0) {
            $value += $p - $remainder;
        }

        if ($write > 0 && $value === $previousValue) {
            $ends[$write - 1] = $ends[$read];
            continue;
        }

        if ($write > 0) {
            $difference = $value - $previousValue;

            if ($newGcd === 0) {
                $newGcd = $difference;
            } elseif ($newGcd !== $p) {
                $a = $newGcd;
                $b = $difference;
                while ($b !== 0) {
                    $tmp = $a % $b;
                    $a = $b;
                    $b = $tmp;
                }
                $newGcd = $a;
            }
        }

        $values[$write] = $value;
        $ends[$write] = $ends[$read];
        $previousValue = $value;
        $write++;
    }

    $groupCount = $write;
    $differenceGcd = ($groupCount === 1) ? 0 : $newGcd;
    $offset += $t;
}

unset($periods, $travelTimes);

$arrivalByResidue = [];
$start = 0;

for ($i = 0; $i < $groupCount; $i++) {
    $end = $ends[$i];
    $arrival = $values[$i] + $offset;

    for ($r = $start; $r <= $end; $r++) {
        $arrivalByResidue[$r] = $arrival;
    }

    $start = $end + 1;
}

$Q = nextInt();
$output = '';

for ($i = 0; $i < $Q; $i++) {
    $departure = nextInt();
    $atFirstStop = $departure + $X;
    $residue = $atFirstStop % $lcm;

    $answer = ($atFirstStop - $residue)
        + $arrivalByResidue[$residue]
        + $Y;

    $output .= $answer . "\n";
}

echo $output;
