<?php

final class FastScanner
{
    private string $data;
    private int $index = 0;
    private int $length;

    public function __construct()
    {
        $this->data = file_get_contents("php://stdin");
        $this->length = strlen($this->data);
    }

    public function nextInt(): int
    {
        while ($this->index < $this->length && ord($this->data[$this->index]) <= 32) {
            $this->index++;
        }

        $sign = 1;
        if ($this->data[$this->index] === '-') {
            $sign = -1;
            $this->index++;
        }

        $number = 0;
        while ($this->index < $this->length) {
            $code = ord($this->data[$this->index]);
            if ($code < 48 || $code > 57) {
                break;
            }
            $number = $number * 10 + ($code - 48);
            $this->index++;
        }

        return $number * $sign;
    }
}

$scanner = new FastScanner();

$n = $scanner->nextInt();
$m = $scanner->nextInt();

$head = array_fill(0, $n + 1, -1);
$to = [];
$dx = [];
$dy = [];
$next = [];
$edgeCount = 0;

for ($i = 0; $i < $m; $i++) {
    $a = $scanner->nextInt();
    $b = $scanner->nextInt();
    $x = $scanner->nextInt();
    $y = $scanner->nextInt();

    $to[$edgeCount] = $b;
    $dx[$edgeCount] = $x;
    $dy[$edgeCount] = $y;
    $next[$edgeCount] = $head[$a];
    $head[$a] = $edgeCount++;

    $to[$edgeCount] = $a;
    $dx[$edgeCount] = -$x;
    $dy[$edgeCount] = -$y;
    $next[$edgeCount] = $head[$b];
    $head[$b] = $edgeCount++;
}

unset($scanner);

$posX = array_fill(0, $n + 1, null);
$posY = array_fill(0, $n + 1, null);
$posX[1] = 0;
$posY[1] = 0;

$queue = [1];
$front = 0;

while ($front < count($queue)) {
    $current = $queue[$front++];
    $currentX = $posX[$current];
    $currentY = $posY[$current];

    for ($edge = $head[$current]; $edge !== -1; $edge = $next[$edge]) {
        $neighbor = $to[$edge];

        if ($posX[$neighbor] === null) {
            $posX[$neighbor] = $currentX + $dx[$edge];
            $posY[$neighbor] = $currentY + $dy[$edge];
            $queue[] = $neighbor;
        }
    }
}

$output = '';
for ($i = 1; $i <= $n; $i++) {
    if ($posX[$i] === null) {
        $output .= "undecidable\n";
    } else {
        $output .= $posX[$i] . ' ' . $posY[$i] . "\n";
    }
}

echo $output;
