<?php

$input = file_get_contents('php://stdin');
$inputLength = strlen($input);
$inputPosition = 0;

function nextInt(): int
{
    global $input, $inputLength, $inputPosition;

    while (
        $inputPosition < $inputLength &&
        ord($input[$inputPosition]) <= 32
    ) {
        $inputPosition++;
    }

    $value = 0;
    while ($inputPosition < $inputLength) {
        $digit = ord($input[$inputPosition]) - 48;
        if ($digit < 0 || $digit > 9) {
            break;
        }
        $value = $value * 10 + $digit;
        $inputPosition++;
    }

    return $value;
}

$n = nextInt();
$m = nextInt();

$answers = array_fill(0, $n + 1, 0);

// Fenwick tree: 1 if the person is currently in the row, otherwise 0.
$fenwick = array_fill(0, $n + 1, 0);
for ($i = 1; $i <= $n; $i++) {
    $fenwick[$i] = $i & (-$i);
}

$highestPower = 1;
while (($highestPower << 1) <= $n) {
    $highestPower <<= 1;
}

$availableCount = $n;

// Max-heap with negative return times, effectively a min-heap.
$returnQueue = new SplPriorityQueue();
$returnQueue->setExtractFlags(SplPriorityQueue::EXTR_BOTH);

for ($event = 0; $event < $m; $event++) {
    $time = nextInt();
    $noodles = nextInt();
    $absence = nextInt();

    while (!$returnQueue->isEmpty()) {
        $top = $returnQueue->top();
        $returnTime = -$top['priority'];

        if ($returnTime > $time) {
            break;
        }

        $item = $returnQueue->extract();
        $person = $item['data'];

        for ($x = $person; $x <= $n; $x += $x & (-$x)) {
            $fenwick[$x]++;
        }
        $availableCount++;
    }

    if ($availableCount === 0) {
        continue;
    }

    // Find the smallest index whose Fenwick prefix sum is at least 1.
    $index = 0;
    $target = 1;

    for ($step = $highestPower; $step > 0; $step >>= 1) {
        $next = $index + $step;
        if ($next <= $n && $fenwick[$next] < $target) {
            $index = $next;
            $target -= $fenwick[$next];
        }
    }

    $person = $index + 1;
    $answers[$person] += $noodles;

    for ($x = $person; $x <= $n; $x += $x & (-$x)) {
        $fenwick[$x]--;
    }
    $availableCount--;

    $returnTime = $time + $absence;
    $returnQueue->insert($person, -$returnTime);
}

$output = [];
for ($i = 1; $i <= $n; $i++) {
    $output[] = (string)$answers[$i];
}

echo implode("\n", $output), "\n";
