final class FastScanner
{
    private string $data;
    private int $index = 0;
    private int $length;

    public function __construct()
    {
        $this->data = file_get_contents('php://stdin');
        $this->length = strlen($this->data);
    }

    public function nextInt(): int
    {
        while ($this->index < $this->length && ord($this->data[$this->index]) <= 32) {
            ++$this->index;
        }

        $number = 0;
        while ($this->index < $this->length) {
            $code = ord($this->data[$this->index]);
            if ($code < 48 || $code > 57) {
                break;
            }
            $number = $number * 10 + ($code - 48);
            ++$this->index;
        }

        return $number;
    }
}

$scanner = new FastScanner();

$n = $scanner->nextInt();
$m = $scanner->nextInt();
$p = $scanner->nextInt();

$a = [];
for ($i = 0; $i < $n; ++$i) {
    $a[] = $scanner->nextInt();
}

$b = [];
for ($i = 0; $i < $m; ++$i) {
    $b[] = $scanner->nextInt();
}

sort($b, SORT_NUMERIC);

$prefix = array_fill(0, $m + 1, 0);
for ($i = 0; $i < $m; ++$i) {
    $prefix[$i + 1] = $prefix[$i] + $b[$i];
}

$answer = 0;

foreach ($a as $mainPrice) {
    $threshold = $p - $mainPrice;

    $left = 0;
    $right = $m;

    // Find the number of side dishes with mainPrice + sidePrice < P.
    while ($left < $right) {
        $mid = intdiv($left + $right, 2);
        if ($b[$mid] < $threshold) {
            $left = $mid + 1;
        } else {
            $right = $mid;
        }
    }

    $countBelow = $left;
    $answer += $mainPrice * $countBelow
        + $prefix[$countBelow]
        + ($m - $countBelow) * $p;
}

echo $answer, PHP_EOL;
?>
