<?php

$input = file_get_contents('php://stdin');
$inputLength = strlen($input);
$inputPosition = 0;

function nextInt(): int
{
    global $input, $inputLength, $inputPosition;

    while ($inputPosition < $inputLength && ord($input[$inputPosition]) <= 32) {
        $inputPosition++;
    }

    $value = 0;
    while ($inputPosition < $inputLength) {
        $c = ord($input[$inputPosition]);
        if ($c < 48 || $c > 57) {
            break;
        }
        $value = $value * 10 + ($c - 48);
        $inputPosition++;
    }

    return $value;
}

function countDescendantsAtDepth(int $vertex, int $depth, int $n): int
{
    // 2^60 > 10^18, so no vertex can exist at such a depth.
    if ($depth >= 60) {
        return 0;
    }

    $width = 1 << $depth;

    // Avoid overflowing vertex * width.
    if ($vertex > intdiv($n, $width)) {
        return 0;
    }

    $left = $vertex * $width;
    $available = $n - $left + 1;

    return $available < $width ? $available : $width;
}

$t = nextInt();
$output = [];

for ($case = 0; $case < $t; $case++) {
    $n = nextInt();
    $x = nextInt();
    $k = nextInt();

    // Vertices below X.
    $answer = countDescendantsAtDepth($x, $k, $n);

    // Vertices reached by first moving upward, then into the sibling subtree.
    $child = $x;
    $upDistance = 0;

    while ($child > 1 && $upDistance < $k) {
        $parent = intdiv($child, 2);
        $upDistance++;

        if ($upDistance === $k) {
            // The ancestor itself is exactly K edges away.
            $answer++;
            break;
        }

        $sibling = ($child ^ 1);
        $remainingDepth = $k - $upDistance - 1;
        $answer += countDescendantsAtDepth($sibling, $remainingDepth, $n);

        $child = $parent;
    }

    $output[] = (string)$answer;
}

echo implode("\n", $output);
