function normalizeShape(array $shape): array
{
    $minR = PHP_INT_MAX;
    $minC = PHP_INT_MAX;

    foreach ($shape as [$r, $c]) {
        $minR = min($minR, $r);
        $minC = min($minC, $c);
    }

    $normalized = [];
    foreach ($shape as [$r, $c]) {
        $normalized[] = [$r - $minR, $c - $minC];
    }

    usort($normalized, function (array $a, array $b): int {
        return $a[0] === $b[0] ? $a[1] <=> $b[1] : $a[0] <=> $b[0];
    });

    return $normalized;
}

function shapeKey(array $shape): string
{
    $parts = [];
    foreach ($shape as [$r, $c]) {
        $parts[] = $r . ',' . $c;
    }
    return implode(';', $parts);
}

function generatePlacements(array $shape): array
{
    $orientations = [];
    $current = $shape;

    for ($rotation = 0; $rotation < 4; $rotation++) {
        $normalized = normalizeShape($current);
        $orientations[shapeKey($normalized)] = $normalized;

        $rotated = [];
        foreach ($current as [$r, $c]) {
            $rotated[] = [$c, -$r];
        }
        $current = $rotated;
    }

    $placements = [];

    foreach ($orientations as $orientation) {
        $maxR = 0;
        $maxC = 0;

        foreach ($orientation as [$r, $c]) {
            $maxR = max($maxR, $r);
            $maxC = max($maxC, $c);
        }

        $height = $maxR + 1;
        $width = $maxC + 1;

        for ($dr = 0; $dr + $height <= 4; $dr++) {
            for ($dc = 0; $dc + $width <= 4; $dc++) {
                $mask = 0;
                foreach ($orientation as [$r, $c]) {
                    $position = ($r + $dr) * 4 + ($c + $dc);
                    $mask |= 1 << $position;
                }
                $placements[$mask] = true;
            }
        }
    }

    return array_keys($placements);
}

$placements = [];
for ($i = 0; $i < 3; $i++) {
    $placements[$i] = generatePlacements($shapes[$i]);
}

foreach ($placements[0] as $first) {
    foreach ($placements[1] as $second) {
        if (($first & $second) !== 0) {
