$data = trim(stream_get_contents(STDIN));
$tokens = preg_split('/\s+/', $data);
$idx = 0;

$N = (int)$tokens[$idx++];
$K = (int)$tokens[$idx++];
$P = (int)$tokens[$idx++];

$plans = [];
for ($i = 0; $i < $N; $i++) {
    $cost = (int)$tokens[$idx++];
    $gain = [];
    for ($j = 0; $j < $K; $j++) {
        $gain[] = (int)$tokens[$idx++];
    }
    $plans[] = [$cost, $gain];
}

$base = $P + 1;
$stateCount = 1;
for ($j = 0; $j < $K; $j++) {
    $stateCount *= $base;
}

$INF = PHP_INT_MAX;
$dp = array_fill(0, $stateCount, $INF);
$dp[0] = 0;

foreach ($plans as [$cost, $gain]) {
    $next = $dp;

    for ($state = 0; $state < $stateCount; $state++) {
        if ($dp[$state] === $INF) {
            continue;
        }

        $value = $state;
        $newState = 0;
        $place = 1;

        for ($j = 0; $j < $K; $j++) {
            $current = $value % $base;
            $value = intdiv($value, $base);

            $updated = min($P, $current + $gain[$j]);
            $newState += $updated * $place;
            $place *= $base;
        }

        $newCost = $dp[$state] + $cost;
        if ($newCost < $next[$newState]) {
            $next[$newState] = $newCost;
        }
    }

    $dp = $next;
}

$answer = $dp[$stateCount - 1];
echo ($answer === $INF ? -1 : $answer) . PHP_EOL;
