<?php

const MOD = 998244353;

function modPow(int $base, int $exp, int $mod): int
{
    $result = 1;
    while ($exp > 0) {
        if (($exp & 1) === 1) {
            $result = ($result * $base) % $mod;
        }
        $base = ($base * $base) % $mod;
        $exp >>= 1;
    }
    return $result;
}

$input = trim(stream_get_contents(STDIN));
$values = preg_split('/\s+/', $input);
$index = 0;

$n = (int)$values[$index++];
$x = (int)$values[$index++];

$durations = [];
for ($i = 0; $i < $n; ++$i) {
    $durations[] = (int)$values[$index++];
}

$t1 = $durations[0];
$inverseN = modPow($n, MOD - 2, MOD);

$frequency = [];
foreach ($durations as $duration) {
    if ($duration <= $x) {
        if (isset($frequency[$duration])) {
            ++$frequency[$duration];
        } else {
            $frequency[$duration] = 1;
        }
    }
}
ksort($frequency, SORT_NUMERIC);

$dp = array_fill(0, $x + 1, 0);
$dp[0] = 1;

for ($time = 1; $time <= $x; ++$time) {
    $sum = 0;
    foreach ($frequency as $duration => $count) {
        if ($duration > $time) {
            break;
        }
        $sum += $dp[$time - $duration] * $count;
    }
    $dp[$time] = (($sum % MOD) * $inverseN) % MOD;
}

$start = max(0, $x - $t1 + 1);
$sum = 0;

for ($time = $start; $time <= $x; ++$time) {
    $sum += $dp[$time];
    if ($sum >= MOD) {
        $sum -= MOD;
    }
}

$answer = ($sum * $inverseN) % MOD;
echo $answer, PHP_EOL;
