        $mismatches = 0;

        for ($i = 0; $i < $targetLength; $i++) {
            if ($candidate[$i] !== $target[$i]) {
                $mismatches++;
                if ($mismatches > 1) {
                    $isPossible = false;
                    break;
                }
            }
        }
    } else {
        if ($candidateLength < $targetLength) {
            $shorter = $candidate;
            $longer = $target;
            $shorterLength = $candidateLength;
            $longerLength = $targetLength;
        } else {
            $shorter = $target;
            $longer = $candidate;
            $shorterLength = $targetLength;
            $longerLength = $candidateLength;
        }

        $i = 0;
        $j = 0;
        $skipped = false;

        while ($i < $shorterLength && $j < $longerLength) {
            if ($shorter[$i] === $longer[$j]) {
                $i++;
                $j++;
            } else {
                if ($skipped) {
                    $isPossible = false;
                    break;
                }
                $skipped = true;
                $j++;
            }
        }
