$input = preg_split('/\s+/', trim(stream_get_contents(STDIN)));
$N = (int)$input[0];
$S = $input[1];

$base = 14;
$power = array_fill(0, 10, 1);
for ($d = 1; $d <= 9; $d++) {
    $power[$d] = $power[$d - 1] * $base;
}

$targetSignature = 0;
$digitSum = 0;

for ($i = 0; $i < $N; $i++) {
    $digit = ord($S[$i]) - 48;
    $targetSignature += $power[$digit];
    $digitSum += $digit;
}

$targetMod9 = $digitSum % 9;

$limit = 1;
for ($i = 0; $i < $N; $i++) {
    $limit *= 10;
}

$answer = 0;

for ($residue = 0; $residue < 9; $residue++) {
    if (($residue * $residue) % 9 !== $targetMod9) {
        continue;
    }

    for ($root = $residue; ; $root += 9) {
        $square = $root * $root;
        if ($square >= $limit) {
            break;
        }

        // Begin with N zero digits, then replace one zero for each
        // digit in the ordinary decimal representation of the square.
        $signature = $N;
        $value = $square;

        do {
            $quotient = intdiv($value, 10);
            $digit = $value - $quotient * 10;
            $signature += $power[$digit] - 1;
            $value = $quotient;
        } while ($value > 0);

        if ($signature === $targetSignature) {
            $answer++;
        }
    }
}

echo $answer, PHP_EOL;
