function dijkstra(
    array &$matrix,
    int $n,
    int $source,
    int $multiplier,
    int $fixedCost
): array {
    $inf = PHP_INT_MAX;
    $distance = array_fill(0, $n, $inf);
    $used = array_fill(0, $n, false);
    $distance[$source] = 0;

    for ($iteration = 0; $iteration < $n; ++$iteration) {
        $city = -1;
        $best = $inf;

        for ($i = 0; $i < $n; ++$i) {
            if (!$used[$i] && $distance[$i] < $best) {
                $best = $distance[$i];
                $city = $i;
            }
        }

        if ($city === -1) {
            break;
        }

        $used[$city] = true;

        if ($iteration === $n - 1) {
            break;
        }

        $row = unpack('V*', $matrix[$city]);
        $to = 0;

        foreach ($row as $d) {
            if (!$used[$to]) {
                $newDistance = $best + $d * $multiplier + $fixedCost;
                if ($newDistance < $distance[$to]) {
                    $distance[$to] = $newDistance;
                }
            }
            ++$to;
        }
    }

    return $distance;
}

