<?php

function ceilDiv(int $a, int $b): int
{
    return intdiv($a + $b - 1, $b);
}

function gcdInt(int $a, int $b): int
{
    while ($b !== 0) {
        $t = $a % $b;
        $a = $b;
        $b = $t;
    }
    return $a;
}

function estimateOrientation(array $demands, int $lengthA, int $limitA, int $lengthB): int
{
    $g = gcdInt($lengthA, $lengthB);
    $period = intdiv($lengthB, $g);
    $score = 0;

    foreach ($demands as $d) {
        $fullT = ceilDiv($d, $lengthA);
        $tMax = min($limitA, $fullT);

        $lastY = ceilDiv($d, $lengthB);
        $optionCount = 1;

        for ($t = 1; $t <= $tMax; ++$t) {
            $remaining = $d - $lengthA * $t;
            $y = $remaining > 0 ? ceilDiv($remaining, $lengthB) : 0;
            if ($y < $lastY) {
                ++$optionCount;
                $lastY = $y;
            }
        }

        $regularMax = ($tMax === $fullT) ? $tMax - 1 : $tMax;
        $residueCount = $regularMax >= 0 ? min($period, $regularMax + 1) : 0;

        $rawEstimate = $optionCount * ($limitA + 1);
        $periodicEstimate = 3 * max(1, $residueCount) * ($limitA + 1);
        $score += min($rawEstimate, $periodicEstimate);
    }

    return $score;
}

function solveOrientation(
    array $demands,
    int $lengthA,
    int $costA,
    int $limitA,
    int $lengthB,
    int $costB,
    int $limitB
): int {
    $INF = PHP_INT_MAX >> 3;

    $g = gcdInt($lengthA, $lengthB);
    $period = intdiv($lengthB, $g);
    $periodReduction = intdiv($lengthA, $g);

    $dp = [0];
    $currentMax = 0;

    foreach ($demands as $d) {
        $fullT = ceilDiv($d, $lengthA);
        $tMax = min($limitA, $fullT);
        $hasCompletion = ($tMax === $fullT);
        $regularMax = $hasCompletion ? $tMax - 1 : $tMax;
        $newMax = min($limitA, $currentMax + $tMax);

        $optionT = [0];
        $optionY = [ceilDiv($d, $lengthB)];
        $lastY = $optionY[0];

        for ($t = 1; $t <= $tMax; ++$t) {
            $remaining = $d - $lengthA * $t;
            $y = $remaining > 0 ? ceilDiv($remaining, $lengthB) : 0;
            if ($y < $lastY) {
                $optionT[] = $t;
                $optionY[] = $y;
                $lastY = $y;
            }
        }

        $rawOps = 0;
        $optionCount = count($optionT);
        for ($i = 0; $i < $optionCount; ++$i) {
            $limit = min($currentMax, $limitA - $optionT[$i]);
            if ($limit >= 0) {
                $rawOps += $limit + 1;
            }
        }

        $residueCount = $regularMax >= 0 ? min($period, $regularMax + 1) : 0;
        $periodicOps = $residueCount * ($newMax + 1);
        if ($hasCompletion) {
            $periodicOps += $currentMax + 1;
        }

        $usePeriodic = $regularMax >= 0 && $periodicOps * 2 <= $rawOps;
        $next = array_fill(0, $newMax + 1, $INF);

        if (!$usePeriodic) {
            for ($i = 0; $i < $optionCount; ++$i) {
                $t = $optionT[$i];
                $y = $optionY[$i];
                $limit = min($currentMax, $newMax - $t);

                for ($x = 0; $x <= $limit; ++$x) {
                    $base = $dp[$x];
                    if ($base > $limitB) {
                        continue;
                    }

                    $value = $base + $y;
                    if ($value <= $limitB && $value < $next[$x + $t]) {
                        $next[$x + $t] = $value;
                    }
                }
            }
        } else {
            if ($hasCompletion && $tMax <= $newMax) {
                $limit = min($currentMax, $newMax - $tMax);
                for ($x = 0; $x <= $limit; ++$x) {
                    $value = $dp[$x];
                    if ($value <= $limitB && $value < $next[$x + $tMax]) {
                        $next[$x + $tMax] = $value;
                    }
                }
            }

            $aMax = min($period - 1, $regularMax);

            for ($a = 0; $a <= $aMax; ++$a) {
                $remainingAtA = $d - $lengthA * $a;
                $fA = ceilDiv($remainingAtA, $lengthB);
                $kMax = intdiv($regularMax - $a, $period);
                $maxU = $newMax - $a;

                if ($maxU < 0) {
                    continue;
                }

                $rMax = min($period - 1, $maxU);

                for ($r = 0; $r <= $rMax; ++$r) {
                    $mMax = intdiv($maxU - $r, $period);
                    $dequeIndex = [];
                    $dequeValue = [];
                    $head = 0;
                    $tail = -1;

                    for ($m = 0; $m <= $mMax; ++$m) {
                        $minimumZ = $m - $kMax;
                        while ($head <= $tail && $dequeIndex[$head] < $minimumZ) {
                            ++$head;
                        }

                        $inputIndex = $r + $m * $period;
                        if ($inputIndex <= $currentMax) {
                            $base = $dp[$inputIndex];
                            if ($base <= $limitB) {
                                $transformed = $base + $periodReduction * $m;

                                while ($head <= $tail && $dequeValue[$tail] >= $transformed) {
                                    --$tail;
                                }

                                ++$tail;
                                $dequeIndex[$tail] = $m;
                                $dequeValue[$tail] = $transformed;
                            }
                        }

                        if ($head <= $tail) {
                            $value = $dequeValue[$head]
                                - $periodReduction * $m
                                + $fA;

                            $outputIndex = $a + $r + $m * $period;
                            if (
                                $value <= $limitB &&
                                $value < $next[$outputIndex]
                            ) {
                                $next[$outputIndex] = $value;
                            }
                        }
                    }
                }
            }
        }

        $dp = $next;
        $currentMax = $newMax;
    }

    $answer = PHP_INT_MAX;

    for ($x = 0; $x <= $currentMax; ++$x) {
        $y = $dp[$x];
        if ($y <= $limitB) {
            $totalCost = $x * $costA + $y * $costB;
            if ($totalCost < $answer) {
                $answer = $totalCost;
            }
        }
    }

    return $answer === PHP_INT_MAX ? -1 : $answer;
}

