<?php

function nextInt(string $data, int &$index, int $length): int
{
    while ($index < $length && ord($data[$index]) <= 32) {
        $index++;
    }

    $number = 0;
    while ($index < $length) {
        $code = ord($data[$index]);
        if ($code < 48 || $code > 57) {
            break;
        }
        $number = $number * 10 + ($code - 48);
        $index++;
    }

    return $number;
}

function findRoot(array &$parent, array &$parity, int $node, int &$xorToRoot): int
{
    $root = $node;
    $xorToRoot = 0;

    while ($parent[$root] !== $root) {
        $xorToRoot ^= $parity[$root];
        $root = $parent[$root];
    }

    $current = $node;
    $prefixXor = 0;

    while ($parent[$current] !== $current) {
        $next = $parent[$current];
        $edgeParity = $parity[$current];

        $parent[$current] = $root;
        $parity[$current] = $xorToRoot ^ $prefixXor;

        $prefixXor ^= $edgeParity;
        $current = $next;
    }

    return $root;
}

$input = file_get_contents('php://stdin');
$index = 0;
$length = strlen($input);

$N = nextInt($input, $index, $length);
$M = nextInt($input, $index, $length);

