for ($i = 0; $i < $M; $i++) {
    $A[] = nextInt($input, $index, $length);
}

$parent = range(0, $N);
$size = array_fill(0, $N + 1, 1);
$parity = array_fill(0, $N + 1, 0);

for ($i = 0; $i < $M; $i++) {
    $b = nextInt($input, $index, $length);
    $a = $A[$i];

    $xorA = 0;
    $xorB = 0;
    $rootA = findRoot($parent, $parity, $a, $xorA);
    $rootB = findRoot($parent, $parity, $b, $xorB);

    if ($rootA === $rootB) {
        if (($xorA ^ $xorB) !== 1) {
            echo "No\n";
            exit;
        }
        continue;
    }

    $rootParity = 1 ^ $xorA ^ $xorB;

    if ($size[$rootA] < $size[$rootB]) {
        $parent[$rootA] = $rootB;
        $parity[$rootA] = $rootParity;
        $size[$rootB] += $size[$rootA];
    } else {
        $parent[$rootB] = $rootA;
        $parity[$rootB] = $rootParity;
        $size[$rootA] += $size[$rootB];
    }
}

echo "Yes\n";
