$mod = (int)$data[$p++];

$edgeU = [];
$edgeV = [];
$edgeW = [];

for ($i = 0; $i < $m; $i++) {
    $edgeU[$i] = (int)$data[$p++] - 1;
    $edgeV[$i] = (int)$data[$p++] - 1;
    $edgeW[$i] = (int)$data[$p++];
}

if ($mod === 1) {
    echo "0\n";
    exit;
}

$parent = $rank = [];
for ($i = 0; $i < $n; $i++) {
    $parent[$i] = $i;
    $rank[$i] = 0;
}

$required = $n - 1;
$answer = $mod;

function findRoot(int $x): int
{
    global $parent;
    while ($parent[$x] !== $x) {
        $x = $parent[$x];
    }
    return $x;
}

function searchTrees(int $index, int $selected, int $sum): void
{
    global $m, $required, $mod, $answer;
    global $edgeU, $edgeV, $edgeW, $parent, $rank;

    if ($answer === 0) {
        return;
    }

    if ($selected === $required) {
        if ($sum < $answer) {
            $answer = $sum;
        }
        return;
    }

    if ($index === $m || $selected + ($m - $index) < $required) {
        return;
    }

    $rootU = findRoot($edgeU[$index]);
    $rootV = findRoot($edgeV[$index]);

    if ($rootU !== $rootV) {
        if ($rank[$rootU] < $rank[$rootV]) {
            $tmp = $rootU;
            $rootU = $rootV;
            $rootV = $tmp;
        }

        $sameRank = ($rank[$rootU] === $rank[$rootV]);
        $parent[$rootV] = $rootU;
        if ($sameRank) {
            $rank[$rootU]++;
        }

        $nextSum = ($sum + $edgeW[$index]) % $mod;
        searchTrees($index + 1, $selected + 1, $nextSum);

        $parent[$rootV] = $rootV;
        if ($sameRank) {
            $rank[$rootU]--;
        }
    }

    searchTrees($index + 1, $selected, $sum);
}

searchTrees(0, 0, 0);

echo $answer, PHP_EOL;
