$input = file_get_contents('php://stdin');
$inputLength = strlen($input);
$inputPosition = 0;

function nextInt(): int
{
    global $input, $inputLength, $inputPosition;

    while ($inputPosition < $inputLength && ord($input[$inputPosition]) <= 32) {
        $inputPosition++;
    }

    $value = 0;
    while ($inputPosition < $inputLength) {
        $digit = ord($input[$inputPosition]) - 48;
        if ($digit < 0 || $digit > 9) {
            break;
        }
        $value = $value * 10 + $digit;
        $inputPosition++;
    }

    return $value;
}

function updateLeaf(array &$tree, int $size, int $index, int $value): void
{
    $position = $size + $index;

    if ($tree[$position] === $value) {
        return;
    }

    $tree[$position] = $value;

    while ($position > 1) {
        $position >>= 1;
        $left = $position << 1;
        $newValue = $tree[$left] < $tree[$left + 1]
            ? $tree[$left]
            : $tree[$left + 1];

        if ($tree[$position] === $newValue) {
            break;
        }

        $tree[$position] = $newValue;
    }
}

$n = nextInt();
$q = nextInt();

$values = array_fill(0, $n, 0);
$counts = array_fill(0, $n + 1, 0);

for ($i = 0; $i < $n; $i++) {
    $value = nextInt();
    $values[$i] = $value;

    if ($value <= $n) {
        $counts[$value]++;
    }
}

$size = 1;
while ($size < $n + 1) {
    $size <<= 1;
}

$inf = $n + 1;
$tree = array_fill(0, $size << 1, $inf);

for ($value = 0; $value <= $n; $value++) {
    if ($counts[$value] === 0) {
        $tree[$size + $value] = $value;
    }
}

for ($position = $size - 1; $position >= 1; $position--) {
    $left = $position << 1;
    $tree[$position] = $tree[$left] < $tree[$left + 1]
        ? $tree[$left]
        : $tree[$left + 1];
}

$output = '';

for ($query = 0; $query < $q; $query++) {
    $index = nextInt() - 1;
    $newValue = nextInt();
    $oldValue = $values[$index];

    if ($oldValue !== $newValue) {
        if ($oldValue <= $n) {
            $counts[$oldValue]--;
            if ($counts[$oldValue] === 0) {
                updateLeaf($tree, $size, $oldValue, $oldValue);
            }
        }

        if ($newValue <= $n) {
            if ($counts[$newValue] === 0) {
                updateLeaf($tree, $size, $newValue, $inf);
            }
            $counts[$newValue]++;
        }

        $values[$index] = $newValue;
    }

    $output .= $tree[1] . "\n";
}

echo $output;
?>
