function countBlackPrefix(int $rows, int $cols, int $n, int $total, array &$prefix): int
{
    $fullRowTiles = intdiv($rows, $n);
    $fullColTiles = intdiv($cols, $n);
    $remainingRows = $rows % $n;
    $remainingCols = $cols % $n;

