        - countBlackPrefix($A, $D + 1, $N, $totalInTile, $prefix)
        - countBlackPrefix($C + 1, $B, $N, $totalInTile, $prefix)
        + countBlackPrefix($A, $B, $N, $totalInTile, $prefix);

