function generatePermutations(int $n): array
{
    $result = [];
    $current = [];
    $used = array_fill(0, $n, false);

    $dfs = function () use (&$dfs, &$result, &$current, &$used, $n): void {
        if (count($current) === $n) {
            $inversions = 0;
            for ($i = 0; $i < $n; $i++) {
                for ($j = $i + 1; $j < $n; $j++) {
                    if ($current[$i] > $current[$j]) {
                        $inversions++;
                    }
                }
            }
            $result[] = [$current, $inversions];
            return;
        }

        for ($i = 0; $i < $n; $i++) {
            if (!$used[$i]) {
                $used[$i] = true;
                $current[] = $i;
                $dfs();
                array_pop($current);
                $used[$i] = false;
            }
        }
    };

    $dfs();
    return $result;
}

$rowPermutations = generatePermutations($H);
$columnPermutations = generatePermutations($W);

$answer = PHP_INT_MAX;

foreach ($rowPermutations as [$rows, $rowCost]) {
    foreach ($columnPermutations as [$columns, $columnCost]) {
        $cost = $rowCost + $columnCost;
        if ($cost >= $answer) {
