<?php

const MOD = 998244353;

function findRoot(array &$parent, int $x): int
{
    $root = $x;
    while ($parent[$root] >= 0) {
        $root = $parent[$root];
    }

    while ($x !== $root) {
        $next = $parent[$x];
        $parent[$x] = $root;
        $x = $next;
    }

    return $root;
}

function unionSets(array &$parent, int $a, int $b): bool
{
    $a = findRoot($parent, $a);
    $b = findRoot($parent, $b);

    if ($a === $b) {
        return false;
    }

    if ($parent[$a] > $parent[$b]) {
        $tmp = $a;
        $a = $b;
        $b = $tmp;
    }

    $parent[$a] += $parent[$b];
    $parent[$b] = $a;

    return true;
}

function modPow(int $base, int $exponent): int
{
    $result = 1;
    while ($exponent > 0) {
        if (($exponent & 1) === 1) {
            $result = ($result * $base) % MOD;
        }
        $base = ($base * $base) % MOD;
        $exponent = intdiv($exponent, 2);
    }
    return $result;
}

[$H, $W] = array_map('intval', explode(' ', trim(fgets(STDIN))));

$grid = [];
for ($i = 0; $i < $H; ++$i) {
    $grid[] = trim(fgets(STDIN));
}

$totalCells = $H * $W;
$parent = array_fill(0, $totalCells, 0);

$components = 0;
$redCount = 0;

for ($i = 0; $i < $H; ++$i) {
    $base = $i * $W;
    $row = $grid[$i];

    for ($j = 0; $j < $W; ++$j) {
        $id = $base + $j;

        if ($row[$j] === '.') {
            ++$redCount;
            continue;
        }

        $parent[$id] = -1;
        ++$components;

        if ($j > 0 && $row[$j - 1] === '#') {
            if (unionSets($parent, $id, $id - 1)) {
                --$components;
            }
        }

        if ($i > 0 && $grid[$i - 1][$j] === '#') {
            if (unionSets($parent, $id, $id - $W)) {
                --$components;
            }
        }
    }
}

$sumDistinctNeighbors = 0;

for ($i = 0; $i < $H; ++$i) {
    $base = $i * $W;
    $row = $grid[$i];

    for ($j = 0; $j < $W; ++$j) {
        if ($row[$j] !== '.') {
            continue;
        }

        $a = -1;
        $b = -1;
        $c = -1;
        $d = -1;
        $count = 0;

        if ($i > 0 && $grid[$i - 1][$j] === '#') {
            $root = findRoot($parent, $base + $j - $W);
            $a = $root;
            ++$count;
        }

        if ($i + 1 < $H && $grid[$i + 1][$j] === '#') {
            $root = findRoot($parent, $base + $j + $W);
            if ($root !== $a) {
                if ($count === 0) {
                    $a = $root;
                } else {
                    $b = $root;
                }
                ++$count;
            }
        }

        if ($j > 0 && $row[$j - 1] === '#') {
            $root = findRoot($parent, $base + $j - 1);
            if ($root !== $a && $root !== $b) {
                if ($count === 0) {
                    $a = $root;
                } elseif ($count === 1) {
                    $b = $root;
                } else {
                    $c = $root;
                }
                ++$count;
            }
        }

        if ($j + 1 < $W && $row[$j + 1] === '#') {
            $root = findRoot($parent, $base + $j + 1);
            if ($root !== $a && $root !== $b && $root !== $c) {
                if ($count === 0) {
                    $a = $root;
                } elseif ($count === 1) {
                    $b = $root;
                } elseif ($count === 2) {
                    $c = $root;
                } else {
                    $d = $root;
                }
                ++$count;
            }
        }

        $sumDistinctNeighbors += $count;
    }
}

$totalComponentSum = $redCount * ($components + 1) - $sumDistinctNeighbors;
$numerator = $totalComponentSum % MOD;
$inverse = modPow($redCount % MOD, MOD - 2);
$answer = ($numerator * $inverse) % MOD;

echo $answer, PHP_EOL;
