$openCount = 0;

for ($r = 0; $r < $N; $r++) {
    for ($c = 0; $c < $N; $c++) {
        if ($grid[$r][$c] === '#') {
            continue;
        }

        $linear = $r * $N + $c;
        $cellId[$linear] = $openCount;
        $positions[] = $linear;

        if ($grid[$r][$c] === 'P') {
            $players[] = $openCount;
        }

        $openCount++;
    }
}

$K = $openCount;
$next = [];

for ($id = 0; $id < $K; $id++) {
    $linear = $positions[$id];
    $r = intdiv($linear, $N);
    $c = $linear % $N;

    $next[] = ($r > 0 && $cellId[$linear - $N] !== -1)
        ? $cellId[$linear - $N] : $id;
    $next[] = ($r + 1 < $N && $cellId[$linear + $N] !== -1)
        ? $cellId[$linear + $N] : $id;
    $next[] = ($c > 0 && $cellId[$linear - 1] !== -1)
        ? $cellId[$linear - 1] : $id;
    $next[] = ($c + 1 < $N && $cellId[$linear + 1] !== -1)
        ? $cellId[$linear + 1] : $id;
}

$startA = $players[0];
$startB = $players[1];

// If the players are in different connected components, they can never meet.
$componentSeen = array_fill(0, $K, false);
$componentSeen[$startA] = true;
$stack = [$startA];

