    echo "-1\n";
    exit;
}

// Player identities are interchangeable, so store each pair in sorted order.
if ($startA > $startB) {
    $tmp = $startA;
    $startA = $startB;
    $startB = $tmp;
}

$stateCount = $K * $K;
$visited = str_repeat("\0", intdiv($stateCount + 7, 8));

$startState = $startA * $K + $startB;
$byteIndex = $startState >> 3;
$visited[$byteIndex] = chr(ord($visited[$byteIndex]) | (1 << ($startState & 7)));

// Each queue record contains two unsigned 16-bit cell IDs.
$queue = pack('v2', $startA, $startB);
$head = 0;
$distance = 0;

while ($head < strlen($queue)) {
    $levelEnd = strlen($queue);
    $distance++;

    while ($head < $levelEnd) {
        $a = ord($queue[$head]) | (ord($queue[$head + 1]) << 8);
        $b = ord($queue[$head + 2]) | (ord($queue[$head + 3]) << 8);
        $head += 4;

        $baseA = $a << 2;
        $baseB = $b << 2;

        for ($d = 0; $d < 4; $d++) {
            $na = $next[$baseA + $d];
            $nb = $next[$baseB + $d];

            if ($na === $nb) {
                echo $distance . "\n";
                exit;
            }

            if ($na > $nb) {
                $tmp = $na;
                $na = $nb;
                $nb = $tmp;
            }

            $state = $na * $K + $nb;
            $byteIndex = $state >> 3;
            $mask = 1 << ($state & 7);
            $currentByte = ord($visited[$byteIndex]);

            if (($currentByte & $mask) !== 0) {
                continue;
            }

            $visited[$byteIndex] = chr($currentByte | $mask);
            $queue .= pack('v2', $na, $nb);
        }
    }
}

echo "-1\n";
