<?php

class FastScanner
{
    private string $data;
    private int $position = 0;
    private int $length;

    public function __construct()
    {
        $this->data = file_get_contents("php://stdin");
        $this->length = strlen($this->data);
    }

    public function nextInt(): int
    {
        while (
            $this->position < $this->length &&
            ord($this->data[$this->position]) <= 32
        ) {
            $this->position++;
        }

        $value = 0;
        while ($this->position < $this->length) {
            $code = ord($this->data[$this->position]);
            if ($code < 48 || $code > 57) {
                break;
            }
            $value = $value * 10 + ($code - 48);
            $this->position++;
        }

        return $value;
    }
}

function bitAdd(array &$bit, int $n, int $index, int $value): void
{
    for ($i = $index; $i <= $n; $i += $i & (-$i)) {
        $bit[$i] += $value;
    }
}

function rangeAdd(
    array &$bit,
    int $n,
    int $left,
    int $right,
    int $value
): void {
    if ($left > $right || $value === 0) {
        return;
    }

    bitAdd($bit, $n, $left + 1, $value);

    $after = $right + 2;
    if ($after <= $n) {
        bitAdd($bit, $n, $after, -$value);
    }
}

function pointQuery(array &$bit, int $index): int
{
    $sum = 0;
    for ($i = $index + 1; $i > 0; $i -= $i & (-$i)) {
        $sum += $bit[$i];
    }
    return $sum;
}

$scanner = new FastScanner();

$n = $scanner->nextInt();
$m = $scanner->nextInt();

/*
 * The Fenwick tree stores the difference array, allowing:
 * - range addition
 * - point queries
 */
$bit = array_fill(0, $n + 1, 0);
$previous = 0;

for ($i = 1; $i <= $n; $i++) {
    $current = $scanner->nextInt();
    $bit[$i] = $current - $previous;
    $previous = $current;
}

// Build the Fenwick tree in O(N).
for ($i = 1; $i <= $n; $i++) {
    $parent = $i + ($i & (-$i));
    if ($parent <= $n) {
        $bit[$parent] += $bit[$i];
    }
}

for ($operation = 0; $operation < $m; $operation++) {
    $box = $scanner->nextInt();
    $balls = pointQuery($bit, $box);

    // Remove all balls from the selected box.
    rangeAdd($bit, $n, $box, $box, -$balls);

    // Every box receives this many balls.
    $quotient = intdiv($balls, $n);
    $remainder = $balls % $n;

    rangeAdd($bit, $n, 0, $n - 1, $quotient);

    // The next "remainder" boxes receive one additional ball.
    if ($remainder > 0) {
        $start = ($box + 1) % $n;
        $end = $start + $remainder - 1;

        if ($end < $n) {
            rangeAdd($bit, $n, $start, $end, 1);
        } else {
            rangeAdd($bit, $n, $start, $n - 1, 1);
            rangeAdd($bit, $n, 0, $end - $n, 1);
        }
    }
}

$result = [];
for ($i = 0; $i < $n; $i++) {
    $result[] = (string) pointQuery($bit, $i);
}

echo implode(' ', $result), PHP_EOL;
