{
    global $input, $length, $position;

    while ($position < $length) {
        $c = ord($input[$position]);
        if ($c > 32) {
            break;
        }
        $position++;
    }

    $value = 0;
    while ($position < $length) {
        $c = ord($input[$position]);
        if ($c < 48 || $c > 57) {
            break;
        }
        $value = $value * 10 + ($c - 48);
        $position++;
    }

    return $value;
}

$n = nextInt();
$m = nextInt();

$adjacency = array_fill(0, $n, []);

for ($i = 0; $i < $m; $i++) {
    $u = nextInt() - 1;
    $v = nextInt() - 1;
    $adjacency[$u][] = $v;
    $adjacency[$v][] = $u;
}

$weights = [];
for ($i = 0; $i < $n; $i++) {
    $weights[$i] = nextInt();
}

$pieces = [];
for ($i = 0; $i < $n; $i++) {
    $pieces[$i] = nextInt();
}

$order = range(0, $n - 1);
usort($order, static function (int $a, int $b) use ($weights): int {
    return $weights[$a] <=> $weights[$b];
});

$value = array_fill(0, $n, 1);

foreach ($order as $vertex) {
    $capacity = $weights[$vertex] - 1;

    if ($capacity === 0) {
        $value[$vertex] = 1;
        continue;
    }

    $dp = array_fill(0, $capacity + 1, 0);

    foreach ($adjacency[$vertex] as $neighbor) {
        $itemWeight = $weights[$neighbor];

        if ($itemWeight >= $weights[$vertex]) {
            continue;
        }

        $itemValue = $value[$neighbor];

        for ($current = $capacity; $current >= $itemWeight; $current--) {
            $candidate = $dp[$current - $itemWeight] + $itemValue;
            if ($candidate > $dp[$current]) {
                $dp[$current] = $candidate;
            }
        }
    }

    $value[$vertex] = $dp[$capacity] + 1;
}

$answer = 0;
for ($i = 0; $i < $n; $i++) {
    $answer += $pieces[$i] * $value[$i];
