$N = nextInt();
$M = nextInt();

$head = array_fill(0, $N + 1, -1);

$start = [];
$interval = [];
$last = [];
$travel = [];
$from = [];
$nextEdge = [];

for ($i = 0; $i < $M; ++$i) {
    $l = nextInt();
    $d = nextInt();
    $k = nextInt();
    $c = nextInt();
    $a = nextInt();
    $b = nextInt();

    $start[$i] = $l;
    $interval[$i] = $d;
    $last[$i] = $l + ($k - 1) * $d;
    $travel[$i] = $c;
    $from[$i] = $a;

    $nextEdge[$i] = $head[$b];
    $head[$b] = $i;
}

$latest = array_fill(0, $N + 1, -1);
$latest[$N] = PHP_INT_MAX;

$queue = new SplPriorityQueue();
$queue->setExtractFlags(SplPriorityQueue::EXTR_BOTH);
$queue->insert($N, PHP_INT_MAX);

while (!$queue->isEmpty()) {
    $item = $queue->extract();
    $station = $item['data'];
    $deadline = $item['priority'];

    if ($latest[$station] !== $deadline) {
        continue;
    }

    for ($edge = $head[$station]; $edge !== -1; $edge = $nextEdge[$edge]) {
        $limit = $deadline - $travel[$edge];

        if ($limit < $start[$edge]) {
            continue;
        }

        if ($limit >= $last[$edge]) {
            $departure = $last[$edge];
        } else {
            $count = intdiv($limit - $start[$edge], $interval[$edge]);
            $departure = $start[$edge] + $count * $interval[$edge];
        }

        $previousStation = $from[$edge];

        if ($departure > $latest[$previousStation]) {
            $latest[$previousStation] = $departure;
            $queue->insert($previousStation, $departure);
        }
    }
}

