$data = preg_split('/\s+/', trim(stream_get_contents(STDIN)));
$pos = 0;

$N = (int)$data[$pos++];
$H = (int)$data[$pos++];
$W = (int)$data[$pos++];

$tiles = [];
$areas = [];

for ($i = 0; $i < $N; $i++) {
    $a = (int)$data[$pos++];
    $b = (int)$data[$pos++];
    $tiles[] = [$a, $b];
    $areas[] = $a * $b;
}

$limit = 1 << $N;
$subsetArea = array_fill(0, $limit, 0);

for ($mask = 1; $mask < $limit; $mask++) {
    $bit = $mask & (-$mask);
    $index = 0;
    while ((1 << $index) !== $bit) {
        $index++;
    }
    $subsetArea[$mask] = $subsetArea[$mask ^ $bit] + $areas[$index];
}

$targetArea = $H * $W;
$allTilesMask = $limit - 1;
$canComplete = array_fill(0, $limit, false);

for ($used = 0; $used < $limit; $used++) {
    if ($subsetArea[$used] > $targetArea) {
        continue;
    }

    $remaining = $allTilesMask ^ $used;
    $sub = $remaining;

    while (true) {
        if ($subsetArea[$used] + $subsetArea[$sub] === $targetArea) {
            $canComplete[$used] = true;
            break;
        }

        if ($sub === 0) {
            break;
        }
        $sub = ($sub - 1) & $remaining;
    }
}

$fullRowMask = (1 << $W) - 1;
$initialRows = array_fill(0, $H, 0);
$memo = [];

$dfs = function (int $used, array $rows) use (
    &$dfs,
    &$memo,
    $tiles,
    $N,
    $H,
    $W,
    $fullRowMask,
    $targetArea,
    $subsetArea,
    $canComplete
): bool {
    if ($subsetArea[$used] === $targetArea) {
        for ($r = 0; $r < $H; $r++) {
            if ($rows[$r] !== $fullRowMask) {
                return false;
            }
        }
        return true;
    }

    if (!$canComplete[$used]) {
        return false;
    }

    $key = $used . ':' . implode(',', $rows);
    if (isset($memo[$key])) {
        return false;
    }

    $firstRow = -1;
    $firstCol = -1;

    for ($r = 0; $r < $H; $r++) {
        if ($rows[$r] === $fullRowMask) {
            continue;
        }

        for ($c = 0; $c < $W; $c++) {
            if ((($rows[$r] >> $c) & 1) === 0) {
                $firstRow = $r;
                $firstCol = $c;
                break 2;
            }
        }
    }

    if ($firstRow === -1) {
        return true;
    }

    for ($i = 0; $i < $N; $i++) {
        if (($used & (1 << $i)) !== 0) {
            continue;
        }

        [$a, $b] = $tiles[$i];
        $orientations = [[$a, $b]];
        if ($a !== $b) {
            $orientations[] = [$b, $a];
        }

        foreach ($orientations as [$tileH, $tileW]) {
            if ($firstRow + $tileH > $H || $firstCol + $tileW > $W) {
                continue;
            }

            $placementMask = ((1 << $tileW) - 1) << $firstCol;
            $fits = true;

            for ($r = $firstRow; $r < $firstRow + $tileH; $r++) {
                if (($rows[$r] & $placementMask) !== 0) {
                    $fits = false;
                    break;
                }
            }

            if (!$fits) {
                continue;
            }

            $newRows = $rows;
            for ($r = $firstRow; $r < $firstRow + $tileH; $r++) {
                $newRows[$r] |= $placementMask;
            }

            if ($dfs($used | (1 << $i), $newRows)) {
                return true;
            }
        }
    }

    $memo[$key] = true;
    return false;
};

