<?php

final class FastScanner
{
    private string $data;
    private int $position = 0;
    private int $length;

    public function __construct()
    {
        $this->data = file_get_contents('php://stdin');
        $this->length = strlen($this->data);
    }

    public function nextInt(): int
    {
        $data = $this->data;
        $length = $this->length;
        $position = $this->position;

        while ($position < $length && ord($data[$position]) <= 32) {
            ++$position;
        }

        $value = 0;
        while ($position < $length) {
            $digit = ord($data[$position]) - 48;
            if ($digit < 0 || $digit > 9) {
                break;
            }
            $value = $value * 10 + $digit;
            ++$position;
        }

        $this->position = $position;
        return $value;
    }
}

$scanner = new FastScanner();
$n = $scanner->nextInt();

$head = array_fill(0, $n + 1, -1);
$to = [];
$next = [];
$edgeCount = 0;

for ($i = 0; $i < $n - 1; ++$i) {
    $a = $scanner->nextInt();
    $b = $scanner->nextInt();

    $to[] = $b;
    $next[] = $head[$a];
    $head[$a] = $edgeCount++;

    $to[] = $a;
    $next[] = $head[$b];
    $head[$b] = $edgeCount++;
}

$weight = array_fill(0, $n + 1, 0);
$totalWeight = 0;

for ($i = 1; $i <= $n; ++$i) {
    $weight[$i] = $scanner->nextInt();
    $totalWeight += $weight[$i];
}

$parent = array_fill(0, $n + 1, 0);
$value = array_fill(0, $n + 1, 0);
$order = [1];
$parent[1] = -1;
$orderCount = 1;
$rootCost = 0;

for ($i = 0; $i < $orderCount; ++$i) {
    $v = $order[$i];

    for ($edge = $head[$v]; $edge !== -1; $edge = $next[$edge]) {
        $u = $to[$edge];
        if ($u === $parent[$v]) {
            continue;
        }

        $parent[$u] = $v;
        $value[$u] = $value[$v] + 1;
        $rootCost += $weight[$u] * $value[$u];
        $order[] = $u;
        ++$orderCount;
    }
}

$subtreeWeight = $weight;

for ($i = $n - 1; $i >= 1; --$i) {
    $v = $order[$i];
    $subtreeWeight[$parent[$v]] += $subtreeWeight[$v];
}

$value[1] = $rootCost;
$answer = $rootCost;

for ($i = 1; $i < $n; ++$i) {
    $v = $order[$i];
    $p = $parent[$v];

    $value[$v] = $value[$p] + $totalWeight - 2 * $subtreeWeight[$v];

    if ($value[$v] < $answer) {
        $answer = $value[$v];
    }
}

echo $answer, PHP_EOL;
