    $occupied = $redMask | $blueMask;

    if (($moves & 1) === 0) {
        // Takahashi chooses a move that lets him win.
        for ($cell = 0; $cell < 9; $cell++) {
            $bit = 1 << $cell;
            if (($occupied & $bit) !== 0) {
                continue;
            }

            if ($solve(
                $redMask | $bit,
                $blueMask,
                $code + $pow3[$cell],
                $moves + 1,
                $scoreDifference + $values[$cell]
            )) {
                $memo[$code] = 1;
                return true;
            }
        }

        $memo[$code] = 0;
        return false;
    }

    // Aoki chooses a move that prevents Takahashi from winning.
    for ($cell = 0; $cell < 9; $cell++) {
        $bit = 1 << $cell;
        if (($occupied & $bit) !== 0) {
            continue;
        }

        if (!$solve(
            $redMask,
            $blueMask | $bit,
            $code + 2 * $pow3[$cell],
            $moves + 1,
            $scoreDifference - $values[$cell]
        )) {
            $memo[$code] = 0;
            return false;
        }
    }

    $memo[$code] = 1;
    return true;
};

echo $solve(0, 0, 0, 0, 0) ? "Takahashi\n" : "Aoki\n";
