function findRoot(array &$parent, int $x): int
{
    $root = $x;
    while ($parent[$root] >= 0) {
        $root = $parent[$root];
    }

    while ($x !== $root) {
        $next = $parent[$x];
        $parent[$x] = $root;
        $x = $next;
    }

    return $root;
}

$n = nextInt();
