    $a = nextInt();
    $b = nextInt();

    $rootA = findRoot($parent, $a);
    $rootB = findRoot($parent, $b);

    if ($rootA === $rootB) {
        continue;
    }

    if ($parent[$rootA] > $parent[$rootB]) {
        [$rootA, $rootB] = [$rootB, $rootA];
    }

    $parent[$rootA] += $parent[$rootB];
    $parent[$rootB] = $rootA;
}

$answer = -$m;

