$input = trim(stream_get_contents(STDIN));
[$N, $A, $X, $Y] = array_map('intval', preg_split('/\s+/', $input));

$memo = [0 => 0.0];

$solve = function (int $n) use (&$solve, &$memo, $A, $X, $Y): float {
    if (isset($memo[$n])) {
        return $memo[$n];
    }

    $fixedCost = (float)$X + $solve(intdiv($n, $A));

    $sum = 0.0;
    for ($b = 2; $b <= 6; ++$b) {
        $sum += $solve(intdiv($n, $b));
    }

    // The outcome b = 1 leaves n unchanged, so its self-loop is eliminated:
    // E = Y + (E + sum(E(floor(n / b)), b=2..6)) / 6.
    $diceCost = (6.0 * (float)$Y + $sum) / 5.0;

    return $memo[$n] = min($fixedCost, $diceCost);
};

