            $nr = $r + $dr[$d];
            $nc = $c + $dc[$d];

            if (
                $nr >= 0 && $nr < $H &&
                $nc >= 0 && $nc < $W &&
                $grid[$nr][$nc] === '.'
            ) {
                $grid[$nr][$nc] = 'x';
            }
        }
    }
}

$answer = 1;
$queue = new SplQueue();

for ($startR = 0; $startR < $H; $startR++) {
    for ($startC = 0; $startC < $W; $startC++) {
        if ($grid[$startR][$startC] !== '.') {
            continue;
        }

        $grid[$startR][$startC] = 'v';
        $queue->enqueue(($startR << 10) | $startC);

        $safeCount = 0;
        $boundaryCount = 0;
        $boundaryCells = [];

        while (!$queue->isEmpty()) {
            $id = $queue->dequeue();
            $r = $id >> 10;
            $c = $id & 1023;
            $safeCount++;

            for ($d = 0; $d < 4; $d++) {
                $nr = $r + $dr[$d];
                $nc = $c + $dc[$d];

                if ($nr < 0 || $nr >= $H || $nc < 0 || $nc >= $W) {
                    continue;
