                if ($grid[$nr][$nc] === '.') {
                    $grid[$nr][$nc] = 'v';
                    $queue->enqueue(($nr << 10) | $nc);
                } elseif ($grid[$nr][$nc] === 'x') {
                    // Temporarily mark it so it is counted only once
                    // for this connected component.
                    $grid[$nr][$nc] = 'y';
                    $boundaryCells[] = ($nr << 10) | $nc;
                    $boundaryCount++;
                }
            }
        }

        $answer = max($answer, $safeCount + $boundaryCount);

        // Restore boundary cells for use by other components.
        foreach ($boundaryCells as $id) {
            $r = $id >> 10;
            $c = $id & 1023;
            $grid[$r][$c] = 'x';
        }
    }
}

