    $a[] = nextInt($data, $pos, $length);
}

unset($data);

$sorted = $a;
sort($sorted, SORT_REGULAR);

$countTree = array_fill(0, $n + 2, 0);
$sumTree = array_fill(0, $n + 2, 0);

