$input = file_get_contents('php://stdin');
$inputLength = strlen($input);
$position = 0;

function nextInt(): int
{
    global $input, $inputLength, $position;

    while ($position < $inputLength && ord($input[$position]) <= 32) {
        $position++;
    }

    $number = 0;
    while ($position < $inputLength) {
        $code = ord($input[$position]);
        if ($code < 48 || $code > 57) {
            break;
        }
        $number = $number * 10 + ($code - 48);
        $position++;
    }

    return $number;
}

$n = nextInt();

$next = array_fill(0, $n, 0);
$indegree = array_fill(0, $n, 0);

for ($i = 0; $i < $n; $i++) {
    $to = nextInt() - 1;
    $next[$i] = $to;
    $indegree[$to]++;
}

$queue = [];
for ($i = 0; $i < $n; $i++) {
    if ($indegree[$i] === 0) {
        $queue[] = $i;
    }
}

$head = 0;
while ($head < count($queue)) {
    $vertex = $queue[$head++];
    $to = $next[$vertex];

    $indegree[$to]--;
    if ($indegree[$to] === 0) {
        $queue[] = $to;
    }
}

$reachable = array_fill(0, $n, 0);

// Every vertex with positive remaining indegree lies on a cycle.
for ($i = 0; $i < $n; $i++) {
    if ($indegree[$i] > 0 && $reachable[$i] === 0) {
        $cycleLength = 1;
        $vertex = $next[$i];

        while ($vertex !== $i) {
            $cycleLength++;
            $vertex = $next[$vertex];
        }

        $vertex = $i;
        do {
            $reachable[$vertex] = $cycleLength;
            $vertex = $next[$vertex];
        } while ($vertex !== $i);
    }
}

// Process non-cycle vertices in reverse topological removal order.
for ($i = count($queue) - 1; $i >= 0; $i--) {
    $vertex = $queue[$i];
    $reachable[$vertex] = $reachable[$next[$vertex]] + 1;
}

$answer = 0;
for ($i = 0; $i < $n; $i++) {
    $answer += $reachable[$i];
}

echo $answer, PHP_EOL;
