const MOD = 998244353;

$input = trim(stream_get_contents(STDIN));
$tokens = preg_split('/\s+/', $input);

$N = (int)$tokens[0];
$K = (int)$tokens[1];
$S = $tokens[2];

$stateCount = 1 << ($K - 1);
$stateMask = $stateCount - 1;
$windowCount = 1 << $K;

$isPalindrome = array_fill(0, $windowCount, false);

for ($mask = 0; $mask < $windowCount; $mask++) {
    $palindrome = true;
    for ($left = 0, $right = $K - 1; $left < $right; $left++, $right--) {
        if ((($mask >> $left) & 1) !== (($mask >> $right) & 1)) {
            $palindrome = false;
            break;
        }
    }
    $isPalindrome[$mask] = $palindrome;
}

$dp = array_fill(0, $stateCount, 0);
$dp[0] = 1;

for ($i = 0; $i < $N; $i++) {
    $next = array_fill(0, $stateCount, 0);
    $char = $S[$i];

    $minBit = ($char === 'B') ? 1 : 0;
    $maxBit = ($char === 'A') ? 0 : 1;

    for ($mask = 0; $mask < $stateCount; $mask++) {
        $ways = $dp[$mask];
        if ($ways === 0) {
            continue;
        }

        for ($bit = $minBit; $bit <= $maxBit; $bit++) {
            $window = ($mask << 1) | $bit;

            if ($i + 1 >= $K && $isPalindrome[$window]) {
                continue;
            }

            $newMask = $window & $stateMask;
            $next[$newMask] += $ways;

            if ($next[$newMask] >= MOD) {
                $next[$newMask] -= MOD;
            }
        }
    }

    $dp = $next;
}

$answer = 0;
foreach ($dp as $ways) {
    $answer += $ways;
    if ($answer >= MOD) {
        $answer -= MOD;
    }
}

echo $answer . PHP_EOL;
