const MOD = 998244353;

function modPow(int $base, int $exp): int
{
    $result = 1;
    while ($exp > 0) {
        if ($exp & 1) {
            $result = ($result * $base) % MOD;
        }
        $base = ($base * $base) % MOD;
        $exp >>= 1;
    }
    return $result;
}

