<?php

$n = (int) trim(fgets(STDIN));

function powerAtMost(int $base, int $exponent, int $limit): bool
{
    $value = 1;

    for ($i = 0; $i < $exponent; $i++) {
        if ($value > intdiv($limit, $base)) {
            return false;
        }
        $value *= $base;
    }

    return true;
}

function integerRoot(int $n, int $exponent): int
{
    $low = 1;
    $high = 1000000001;

    while ($high - $low > 1) {
        $mid = $low + intdiv($high - $low, 2);

        if (powerAtMost($mid, $exponent, $n)) {
            $low = $mid;
        } else {
            $high = $mid;
        }
    }

    return $low;
}

function mobius(int $n): int
{
    $primeFactorCount = 0;

    for ($p = 2; $p * $p <= $n; $p++) {
        if ($n % $p !== 0) {
            continue;
        }

        $n = intdiv($n, $p);
        if ($n % $p === 0) {
            return 0;
        }

        while ($n % $p === 0) {
            $n = intdiv($n, $p);
        }

        $primeFactorCount++;
    }

    if ($n > 1) {
        $primeFactorCount++;
    }

    return ($primeFactorCount % 2 === 0) ? 1 : -1;
}

$answer = 1;

for ($exponent = 2; $exponent <= 60; $exponent++) {
    $mu = mobius($exponent);

    if ($mu === 0) {
        continue;
    }

    $root = integerRoot($n, $exponent);
    $answer -= $mu * ($root - 1);
}

echo $answer . PHP_EOL;
