<?php

final class FastScanner
{
    private string $data;
    private int $index = 0;
    private int $length;

    public function __construct()
    {
        $this->data = file_get_contents('php://stdin');
        $this->length = strlen($this->data);
    }

    public function nextInt(): int
    {
        while ($this->index < $this->length && ord($this->data[$this->index]) <= 32) {
            ++$this->index;
        }

        $number = 0;
        while ($this->index < $this->length) {
            $digit = ord($this->data[$this->index]) - 48;
            if ($digit < 0 || $digit > 9) {
                break;
            }
            $number = $number * 10 + $digit;
            ++$this->index;
        }

        return $number;
    }
}

$scanner = new FastScanner();

$n = $scanner->nextInt();
$m = $scanner->nextInt();

$vertexWeight = [0];
for ($i = 1; $i <= $n; ++$i) {
    $vertexWeight[] = $scanner->nextInt();
}

$head = array_fill(0, $n + 1, -1);
$to = [];
$edgeWeight = [];
$next = [];
$edgeIndex = 0;

for ($i = 0; $i < $m; ++$i) {
    $u = $scanner->nextInt();
    $v = $scanner->nextInt();
    $b = $scanner->nextInt();

    $to[] = $v;
    $edgeWeight[] = $b;
    $next[] = $head[$u];
    $head[$u] = $edgeIndex++;

    $to[] = $u;
    $edgeWeight[] = $b;
    $next[] = $head[$v];
    $head[$v] = $edgeIndex++;
}

$dist = array_fill(0, $n + 1, PHP_INT_MAX);
$dist[1] = $vertexWeight[1];

$queue = new SplPriorityQueue();
$queue->setExtractFlags(SplPriorityQueue::EXTR_BOTH);
$queue->insert(1, -$dist[1]);

while (!$queue->isEmpty()) {
    $item = $queue->extract();
    $u = $item['data'];
    $currentDistance = -$item['priority'];

    if ($currentDistance != $dist[$u]) {
        continue;
    }

    for ($e = $head[$u]; $e !== -1; $e = $next[$e]) {
        $v = $to[$e];
        $newDistance = $currentDistance + $edgeWeight[$e] + $vertexWeight[$v];

        if ($newDistance < $dist[$v]) {
            $dist[$v] = $newDistance;
            $queue->insert($v, -$newDistance);
        }
    }
}

$answer = [];
for ($i = 2; $i <= $n; ++$i) {
    $answer[] = (string)$dist[$i];
}

echo implode(' ', $answer), PHP_EOL;
