function countValidPermutations(int $depth): int
{
    global $N, $K, $counts, $typeCount, $buffer;

    if ($depth === $N) {
        return 1;
    }

    $result = 0;

    for ($char = 0; $char < $typeCount; $char++) {
        if ($counts[$char] === 0) {
            continue;
        }

        $counts[$char]--;
        $buffer[$depth] = $char;

        $valid = true;

        if ($depth + 1 >= $K) {
            $left = $depth - $K + 1;
            $right = $depth;

            while ($left < $right) {
                if ($buffer[$left] !== $buffer[$right]) {
                    break;
                }
                $left++;
                $right--;
            }

            if ($left >= $right) {
                $valid = false;
            }
        }

        if ($valid) {
            $result += countValidPermutations($depth + 1);
        }

        $counts[$char]++;
    }

    return $result;
}

