$input = file_get_contents("php://stdin");
$inputLength = strlen($input);
$inputIndex = 0;

function nextInt(): int
{
    global $input, $inputLength, $inputIndex;

    while ($inputIndex < $inputLength && ord($input[$inputIndex]) <= 32) {
        $inputIndex++;
    }

    $sign = 1;
    if ($input[$inputIndex] === '-') {
        $sign = -1;
        $inputIndex++;
    }

    $number = 0;
    while ($inputIndex < $inputLength) {
        $code = ord($input[$inputIndex]);
        if ($code < 48 || $code > 57) {
            break;
        }
        $number = $number * 10 + ($code - 48);
        $inputIndex++;
    }

    return $number * $sign;
}

$n = nextInt();
$q = nextInt();

$a = [];
for ($i = 0; $i < $n; $i++) {
    $a[] = nextInt();
}
sort($a, SORT_NUMERIC);

$output = '';

for ($query = 0; $query < $q; $query++) {
    $b = nextInt();
    $k = nextInt();

    // Find the first index whose coordinate is at least b.
    $low = 0;
    $high = $n;
    while ($low < $high) {
        $mid = intdiv($low + $high, 2);
        if ($a[$mid] < $b) {
            $low = $mid + 1;
        } else {
            $high = $mid;
        }
    }

    $position = $low;
    $leftCount = $position;
    $rightCount = $n - $position;

    // Merge conceptually:
    // left distances:  b-a[position-1], b-a[position-2], ...
    // right distances: a[position]-b, a[position+1]-b, ...
    $partitionLow = max(0, $k - $rightCount);
    $partitionHigh = min($k, $leftCount);
    $answer = 0;

    while ($partitionLow <= $partitionHigh) {
        $takeLeft = intdiv($partitionLow + $partitionHigh, 2);
        $takeRight = $k - $takeLeft;

        $leftPrevious = $takeLeft > 0
            ? $b - $a[$position - $takeLeft]
            : -1;

        $leftNext = $takeLeft < $leftCount
            ? $b - $a[$position - $takeLeft - 1]
            : PHP_INT_MAX;

        $rightPrevious = $takeRight > 0
            ? $a[$position + $takeRight - 1] - $b
            : -1;

        $rightNext = $takeRight < $rightCount
            ? $a[$position + $takeRight] - $b
            : PHP_INT_MAX;

        if ($leftPrevious > $rightNext) {
            $partitionHigh = $takeLeft - 1;
        } elseif ($rightPrevious > $leftNext) {
            $partitionLow = $takeLeft + 1;
        } else {
            $answer = max($leftPrevious, $rightPrevious);
            break;
        }
    }

    $output .= $answer . "\n";
}

echo $output;
