        $saltLimit = $Y - $b;
        $newMaxReach = $maxReach[$k + 1];

        $src =& $dp[$k];
        $dst =& $dp[$k + 1];

        for ($sweet = 0; $sweet <= $limit; ++$sweet) {
            $currentSalt = $src[$sweet];

            if ($currentSalt <= $saltLimit) {
                $nextSweet = $sweet + $a;
                $nextSalt = $currentSalt + $b;

                if ($nextSalt < $dst[$nextSweet]) {
                    $dst[$nextSweet] = $nextSalt;
                }

                if ($nextSweet > $newMaxReach) {
                    $newMaxReach = $nextSweet;
                }
