    $xBase = $x * $plane;

    // Build the two-dimensional prefix sum for the current x-plane.
    for ($y = 1; $y <= $n; ++$y) {
        $base = $xBase + $y * $side;
        $rowSum = 0;

        for ($z = 1; $z <= $n; ++$z) {
            $rowSum += nextInt();
            $index = $base + $z;
            $prefix[$index] = $rowSum + $prefix[$index - $side];
        }
    }

    // Accumulate the current plane along the x-axis.
    if ($x > 1) {
        $previousBase = $xBase - $plane;
        for ($y = 1; $y <= $n; ++$y) {
            $currentRow = $xBase + $y * $side;
            $previousRow = $previousBase + $y * $side;

            for ($z = 1; $z <= $n; ++$z) {
