        $value = $value * 10 + ($c - 48);
        $pos++;
    }

    return $value;
}

$N = nextInt();
$K = nextInt();

$counts = array_fill(0, 51 * 51, 0);

for ($i = 0; $i < $N; $i++) {
    $a = nextInt();
    $b = nextInt();
    $counts[$a * 51 + $b]++;
}

$types = [];

for ($a = 1; $a <= 50; $a++) {
    for ($b = 1; $b <= 50; $b++) {
        $count = $counts[$a * 51 + $b];
        if ($count > 0) {
            $types[] = [$a, $b, min($count, $K)];
        }
    }
}

// Optimal outer-to-inner order is descending by (A - 1) / B.
usort($types, static function (array $x, array $y): int {
    $left = ($x[0] - 1) * $y[1];
    $right = ($y[0] - 1) * $x[1];

    if ($left !== $right) {
        return $right <=> $left;
    }
    if ($x[0] !== $y[0]) {
        return $x[0] <=> $y[0];
    }
    return $x[1] <=> $y[1];
});

$dp = array_fill(0, $K + 1, PHP_INT_MIN);
$dp[0] = 1;
$available = 0;

// Process from inner to outer.
