    [$a, $b, $count] = $types[$i];

    for ($copy = 0; $copy < $count; $copy++) {
        $upper = min($K, $available + 1);

        for ($used = $upper; $used >= 1; $used--) {
            $candidate = $a * $dp[$used - 1] + $b;
            if ($candidate > $dp[$used]) {
                $dp[$used] = $candidate;
            }
        }

        $available = $upper;
    }
}

