<?php

const MOD = 998244353;

$input = file_get_contents("php://stdin");
$inputPos = 0;
$inputLen = strlen($input);

function nextInt(): int
{
    global $input, $inputPos, $inputLen;

    while ($inputPos < $inputLen && ord($input[$inputPos]) <= 32) {
        ++$inputPos;
    }

    $value = 0;
    while ($inputPos < $inputLen) {
        $c = ord($input[$inputPos]);
        if ($c <= 32) {
            break;
        }
        $value = $value * 10 + ($c - 48);
        ++$inputPos;
    }

    return $value;
}

function modPow(int $base, int $exp): int
{
    $result = 1;
    $base %= MOD;

    while ($exp > 0) {
        if ($exp & 1) {
            $result = (int)(($result * $base) % MOD);
        }
        $base = (int)(($base * $base) % MOD);
        $exp >>= 1;
    }

    return $result;
}

function cyclicMultiply(array $a, array $b, int $m): array
{
    $result = array_fill(0, $m, 0);

    for ($i = 0; $i < $m; ++$i) {
        $ai = $a[$i];
        if ($ai === 0) {
            continue;
        }

        for ($j = 0; $j < $m; ++$j) {
            $bj = $b[$j];
            if ($bj === 0) {
                continue;
            }

            $index = $i + $j;
            if ($index >= $m) {
                $index -= $m;
            }

            $value = $result[$index] + (int)(($ai * $bj) % MOD);
            if ($value >= MOD) {
                $value -= MOD;
            }
            $result[$index] = $value;
        }
    }

    return $result;
}

function cyclicPlusPower(int $m, int $exp): array
{
    $result = array_fill(0, $m, 0);
    $result[0] = 1;

    $base = array_fill(0, $m, 0);
    $base[0] = 1;
    $index = 1 % $m;
    ++$base[$index];
    if ($base[$index] >= MOD) {
        $base[$index] -= MOD;
    }

    while ($exp > 0) {
        if ($exp & 1) {
            $result = cyclicMultiply($result, $base, $m);
        }
        $exp >>= 1;
        if ($exp > 0) {
            $base = cyclicMultiply($base, $base, $m);
        }
    }

    return $result;
}

$N = nextInt();
$M = nextInt();
$K = nextInt();

if ($M > $N) {
    echo "0\n";
    exit;
}

$A = array_fill(0, $N, 0);
$maxA = 0;
$allXor = 0;

for ($i = 0; $i < $N; ++$i) {
    $value = nextInt();
    $A[$i] = $value;
    if ($value > $maxA) {
        $maxA = $value;
    }
    $allXor ^= $value;
}

unset($input);

if ($M === $N) {
    echo modPow($allXor, $K), "\n";
    exit;
}

if ($maxA === 0) {
    echo "0\n";
    exit;
}

/*
 * g[c] is the signed count
 *
 *   sum_{|S| divisible by M} (-1)^(number of selected elements
 *                                  among a fixed set of c elements).
 *
 * It equals the coefficient-sum in residue class 0 of
 * (1+z)^(N-c) (1-z)^c modulo z^M-1.
 */
$p = cyclicPlusPower($M, $N);
$g = array_fill(0, $N + 1, 0);
$g[0] = $p[0];

if ($M & 1) {
    $degree = $M;
    $initialLast = $M - 1;
    $inv2 = 499122177;

    for ($target = 1; $target <= $initialLast; ++$target) {
        $sum = $p[0] - $p[$M - 1];

        for ($r = 1; $r < $M; ++$r) {
            $d = $p[$r] - $p[$r - 1];
            if ($r & 1) {
                $sum += $d;
            } else {
                $sum -= $d;
            }
        }

        $sum %= MOD;
        if ($sum < 0) {
            $sum += MOD;
        }

        $q0 = (int)(($sum * $inv2) % MOD);

        $previousOld = $p[0];
        $previousNew = $q0;
        $p[0] = $q0;

        for ($r = 1; $r < $M; ++$r) {
            $currentOld = $p[$r];
            $value = $currentOld - $previousOld - $previousNew;
            if ($value < 0) {
                $value += MOD;
            }
            if ($value < 0) {
                $value += MOD;
            }

            $p[$r] = $value;
            $previousOld = $currentOld;
            $previousNew = $value;
        }

        $g[$target] = $q0;
    }
} else {
    $degree = $M - 1;
    $initialLast = $M - 2;
    $invM = modPow($M, MOD - 2);

    for ($target = 1; $target <= $initialLast; ++$target) {
        $weighted = 0;

        for ($r = 1; $r < $M; ++$r) {
            $d = $p[$r] - $p[$r - 1];
            $term = ($M - $r) * $d;
            if ($r & 1) {
                $weighted -= $term;
            } else {
                $weighted += $term;
            }
        }

        $weighted %= MOD;
        if ($weighted < 0) {
            $weighted += MOD;
        }

        $q0 = ($weighted === 0) ? 0 : MOD - $weighted;
        $q0 = (int)(($q0 * $invM) % MOD);

        $previousOld = $p[0];
        $previousNew = $q0;
        $p[0] = $q0;

        for ($r = 1; $r < $M; ++$r) {
            $currentOld = $p[$r];
            $value = $currentOld - $previousOld - $previousNew;
            if ($value < 0) {
                $value += MOD;
            }
            if ($value < 0) {
                $value += MOD;
            }

            $p[$r] = $value;
            $previousOld = $currentOld;
            $previousNew = $value;
        }

        $g[$target] = $q0;
    }
}

unset($p);

/*
 * The sequence g satisfies
 *   sum_{odd j} C(M,j) g[c+j] = 0.
 */
$binom = array_fill(0, $M + 1, 0);
$binom[0] = 1;

for ($i = 1; $i <= $M; ++$i) {
    for ($j = $i; $j >= 1; --$j) {
        $value = $binom[$j] + $binom[$j - 1];
        if ($value >= MOD) {
            $value -= MOD;
        }
        $binom[$j] = $value;
    }
}

$limit = ($M & 1) ? $N : $N - 1;
$leadingInverse = ($M & 1) ? 1 : modPow($M, MOD - 2);

for ($index = $degree; $index <= $limit; ++$index) {
    $baseIndex = $index - $degree;
    $sum = 0;

    for ($j = 1; $j < $degree; $j += 2) {
        $term = (int)(($binom[$j] * $g[$baseIndex + $j]) % MOD);
        $sum += $term;
        if ($sum >= MOD) {
            $sum -= MOD;
        }
    }

    $value = ($sum === 0) ? 0 : MOD - $sum;
    if ($leadingInverse !== 1) {
        $value = (int)(($value * $leadingInverse) % MOD);
    }
    $g[$index] = $value;
}

if (($M & 1) === 0) {
    $g[$N] = $g[0];
}

unset($binom);

/* Use only the necessary number of XOR bits. */
$size = 1;
while ($size <= $maxA) {
    $size <<= 1;
}

$frequency = array_fill(0, $size, 0);
for ($i = 0; $i < $N; ++$i) {
    ++$frequency[$A[$i]];
}
unset($A);

/* Build f[x] = x^K modulo MOD. */
$f = array_fill(0, $size, 0);

if ($K === 1) {
    for ($x = 1; $x < $size; ++$x) {
        $f[$x] = $x;
    }
} elseif ($K === 2) {
    for ($x = 1; $x < $size; ++$x) {
        $f[$x] = (int)(($x * $x) % MOD);
    }
} else {
    /*
     * First store smallest prime factors in f, then overwrite them
     * in increasing order with x^K.
     */
    for ($i = 2; $i * $i < $size; ++$i) {
        if ($f[$i] !== 0) {
            continue;
        }

        for ($j = $i * $i; $j < $size; $j += $i) {
            if ($f[$j] === 0) {
                $f[$j] = $i;
            }
        }
    }

    $f[1] = 1;

    for ($x = 2; $x < $size; ++$x) {
        $prime = $f[$x];

        if ($prime === 0) {
            $f[$x] = modPow($x, $K);
        } else {
            $f[$x] = (int)(($f[$prime] * $f[intdiv($x, $prime)]) % MOD);
        }
    }
}

/* Simultaneous ordinary and modular Walsh-Hadamard transforms. */
for ($half = 1; $half < $size; $half <<= 1) {
    $step = $half << 1;

    for ($base = 0; $base < $size; $base += $step) {
        $end = $base + $half;
        $other = $end;

        for ($left = $base; $left < $end; ++$left, ++$other) {
            $u = $frequency[$left];
            $v = $frequency[$other];
            $frequency[$left] = $u + $v;
            $frequency[$other] = $u - $v;

            $u = $f[$left];
            $v = $f[$other];

            $sum = $u + $v;
            if ($sum >= MOD) {
                $sum -= MOD;
            }

            $difference = $u - $v;
            if ($difference < 0) {
                $difference += MOD;
            }

            $f[$left] = $sum;
            $f[$other] = $difference;
        }
    }
}

$answer = 0;

for ($s = 0; $s < $size; ++$s) {
    $c = intdiv($N - $frequency[$s], 2);
    $term = (int)(($f[$s] * $g[$c]) % MOD);
    $answer += $term;
    if ($answer >= MOD) {
        $answer -= MOD;
    }
}

$inverseSize = modPow($size, MOD - 2);
$answer = (int)(($answer * $inverseSize) % MOD);

echo $answer, "\n";
