function findNext(&$parent, $position, $limit)
{
    $root = $position;

    while ($root < $limit && $parent[$root] !== $root) {
        $root = $parent[$root];
    }

    while ($position < $limit && $parent[$position] !== $position) {
        $next = $parent[$position];
        $parent[$position] = $root;
        $position = $next;
