<?php

$data = file_get_contents('php://stdin');
$dataPos = 0;
$dataLength = strlen($data);

function nextInt(): int
{
    global $data, $dataPos, $dataLength;

    while ($dataPos < $dataLength && ord($data[$dataPos]) <= 32) {
        $dataPos++;
    }

    $value = 0;
    while ($dataPos < $dataLength) {
        $c = ord($data[$dataPos]);
        if ($c < 48 || $c > 57) {
            break;
        }
        $value = $value * 10 + ($c - 48);
        $dataPos++;
    }

    return $value;
}

class SegmentTree
{
    private int $n;
    private array $sum;
    private array $mx;
    private array $lazy;

    public function __construct(array &$values, int $n)
    {
        $this->n = $n;
        $size = 4 * $n + 5;
        $this->sum = array_fill(0, $size, 0);
        $this->mx = array_fill(0, $size, 0);
        $this->lazy = array_fill(0, $size, null);
        $this->build(1, 1, $n, $values);
    }

    private function build(int $node, int $left, int $right, array &$values): void
    {
        if ($left === $right) {
            $this->sum[$node] = $values[$left];
            $this->mx[$node] = $values[$left];
            return;
        }

        $mid = intdiv($left + $right, 2);
        $lc = $node * 2;
        $rc = $lc + 1;

        $this->build($lc, $left, $mid, $values);
        $this->build($rc, $mid + 1, $right, $values);
        $this->pull($node);
    }

    private function pull(int $node): void
    {
        $lc = $node * 2;
        $rc = $lc + 1;
        $this->sum[$node] = $this->sum[$lc] + $this->sum[$rc];
        $this->mx[$node] = max($this->mx[$lc], $this->mx[$rc]);
    }

    private function apply(int $node, int $left, int $right, int $value): void
    {
        $this->sum[$node] = $value * ($right - $left + 1);
        $this->mx[$node] = $value;
        $this->lazy[$node] = $value;
    }

    private function push(int $node, int $left, int $right): void
    {
        if (!isset($this->lazy[$node]) || $left === $right) {
            return;
        }

        $mid = intdiv($left + $right, 2);
        $lc = $node * 2;
        $rc = $lc + 1;
        $value = $this->lazy[$node];

        $this->apply($lc, $left, $mid, $value);
        $this->apply($rc, $mid + 1, $right, $value);
        $this->lazy[$node] = null;
    }

    public function getPoint(int $index): int
    {
        return $this->getPointRec(1, 1, $this->n, $index);
    }

    private function getPointRec(int $node, int $left, int $right, int $index): int
    {
        if (isset($this->lazy[$node]) || $left === $right) {
            return $this->mx[$node];
        }

        $mid = intdiv($left + $right, 2);
        if ($index <= $mid) {
            return $this->getPointRec($node * 2, $left, $mid, $index);
        }

        return $this->getPointRec($node * 2 + 1, $mid + 1, $right, $index);
    }

    public function firstGreaterOrEqual(int $value): int
    {
        if ($this->mx[1] < $value) {
            return $this->n + 1;
        }
        return $this->firstIndexRec(1, 1, $this->n, $value, false);
    }

    public function firstGreater(int $value): int
    {
        if ($this->mx[1] <= $value) {
            return $this->n + 1;
        }
        return $this->firstIndexRec(1, 1, $this->n, $value, true);
    }

    private function firstIndexRec(
        int $node,
        int $left,
        int $right,
        int $value,
        bool $strict
    ): int {
        if ($left === $right || isset($this->lazy[$node])) {
            return $left;
        }

        $mid = intdiv($left + $right, 2);
        $lc = $node * 2;
        $leftMax = $this->mx[$lc];

        if (($strict && $leftMax > $value) || (!$strict && $leftMax >= $value)) {
            return $this->firstIndexRec($lc, $left, $mid, $value, $strict);
        }

        return $this->firstIndexRec($lc + 1, $mid + 1, $right, $value, $strict);
    }

    public function replaceAndGetOldSum(int $queryLeft, int $queryRight, int $value): int
    {
        return $this->replaceRec(
            1,
            1,
            $this->n,
            $queryLeft,
            $queryRight,
            $value
        );
    }

    private function replaceRec(
        int $node,
        int $left,
        int $right,
        int $queryLeft,
        int $queryRight,
        int $value
    ): int {
        if ($queryLeft <= $left && $right <= $queryRight) {
            $oldSum = $this->sum[$node];
            $this->apply($node, $left, $right, $value);
            return $oldSum;
        }

        $this->push($node, $left, $right);

        $mid = intdiv($left + $right, 2);
        $oldSum = 0;

        if ($queryLeft <= $mid) {
            $oldSum += $this->replaceRec(
                $node * 2,
                $left,
                $mid,
                $queryLeft,
                $queryRight,
                $value
            );
        }

        if ($queryRight > $mid) {
            $oldSum += $this->replaceRec(
                $node * 2 + 1,
                $mid + 1,
                $right,
                $queryLeft,
                $queryRight,
                $value
            );
        }

        $this->pull($node);
        return $oldSum;
    }
}

$n = nextInt();
$values = [0];

for ($i = 1; $i <= $n; $i++) {
    $values[$i] = nextInt() - $i;
}

$segmentTree = new SegmentTree($values, $n);
