    $person = nextInt();
    $goal = nextInt();
    $target = $goal - $person;

    $current = $segmentTree->getPoint($person);

    if ($current < $target) {
        $end = $segmentTree->firstGreaterOrEqual($target) - 1;
        $length = $end - $person + 1;
        $oldSum = $segmentTree->replaceAndGetOldSum($person, $end, $target);
        $answer += $target * $length - $oldSum;
    } elseif ($current > $target) {
        $start = $segmentTree->firstGreater($target);
        $length = $person - $start + 1;
        $oldSum = $segmentTree->replaceAndGetOldSum($start, $person, $target);
        $answer += $oldSum - $target * $length;
    }
}

echo $answer, PHP_EOL;
