function modInverse(int $a, int $mod): int
{
    $b = $mod;
    $u = 1;
    $v = 0;

    while ($b !== 0) {
        $q = intdiv($a, $b);

        $nextA = $a - $q * $b;
        $a = $b;
        $b = $nextA;

        $nextU = $u - $q * $v;
        $u = $v;
        $v = $nextU;
    }

    $u %= $mod;
    if ($u < 0) {
        $u += $mod;
    }
    return $u;
}

$N = nextInt();

$P = array_fill(0, $N + 1, 0);
$A = array_fill(0, $N + 1, 0);
$answer = array_fill(0, $N + 1, 0);

