/*
 * For each prime p:
 * $primeMod[p] is the largest constrained power of p.
 * $primeRem[p] is k modulo that power.
 */
$primeMod = [];
$primeRem = [];

for ($start = 1; $start <= $N; ++$start) {
    if ($P[$start] < 0) {
        continue;
    }

    $cycle = [];
    $current = $start;

    while ($P[$current] > 0) {
        $cycle[] = $current;
        $next = $P[$current];
        $P[$current] = -$P[$current];
        $current = $next;
    }

    $cycleLength = count($cycle);

    // Prime-power factorization of the cycle length.
    $factors = [];
    $remaining = $cycleLength;

    for ($p = 2; $p * $p <= $remaining; ++$p) {
        if ($remaining % $p !== 0) {
            continue;
        }

        $power = 1;
        while ($remaining % $p === 0) {
            $remaining = intdiv($remaining, $p);
            $power *= $p;
        }
        $factors[] = [$p, $power];
    }

    if ($remaining > 1) {
        $factors[] = [$remaining, $remaining];
    }

    /*
     * Existing constraints allow residues r modulo cycleLength satisfying
     * r ≡ base (mod divisor).
     */
    $base = 0;
    $divisor = 1;

    foreach ($factors as [$prime, $cyclePrimePower]) {
        if (!isset($primeMod[$prime])) {
            continue;
        }

        $commonPower = min($cyclePrimePower, $primeMod[$prime]);
        $required = $primeRem[$prime] % $commonPower;

        $delta = ($required - ($base % $commonPower)) % $commonPower;
        if ($delta < 0) {
            $delta += $commonPower;
        }

        $inverse = modInverse($divisor % $commonPower, $commonPower);
        $multiplier = ($delta * $inverse) % $commonPower;

        $base += $divisor * $multiplier;
        $divisor *= $commonPower;
        $base %= $divisor;
    }

    // Choose the feasible shift minimizing the value at this cycle's first index.
    $bestShift = $base;
    $bestValue = $A[$cycle[$base]];

    for ($shift = $base + $divisor; $shift < $cycleLength; $shift += $divisor) {
        $value = $A[$cycle[$shift]];
        if ($value < $bestValue) {
            $bestValue = $value;
            $bestShift = $shift;
        }
    }

    // This choice imposes k ≡ bestShift (mod cycleLength).
    foreach ($factors as [$prime, $cyclePrimePower]) {
        if (!isset($primeMod[$prime]) || $cyclePrimePower > $primeMod[$prime]) {
            $primeMod[$prime] = $cyclePrimePower;
            $primeRem[$prime] = $bestShift % $cyclePrimePower;
        }
    }

    for ($i = 0; $i < $cycleLength; ++$i) {
        $answer[$cycle[$i]] = $A[$cycle[($i + $bestShift) % $cycleLength]];
    }
}

$output = '';
for ($i = 1; $i <= $N; ++$i) {
    if ($i > 1) {
        $output .= ' ';
    }
    $output .= (string)$answer[$i];
}
$output .= "\n";

echo $output;
