function compareLines(array $p, array $q): int
{
    // Sort by A/B ascending, i.e. slopes -A/B descending.
    $left = $p[0] * $q[1];
    $right = $q[0] * $p[1];

    if ($left !== $right) {
        return $left <=> $right;
    }

    // For equal slopes, put the smaller intercept D/B first.
    $left = $p[2] * $q[1];
    $right = $q[2] * $p[1];

    return $left <=> $right;
}

function ceilDiv(int $numerator, int $denominator): int
{
    if ($numerator >= 0) {
        return intdiv($numerator + $denominator - 1, $denominator);
    }

    return -intdiv(-$numerator, $denominator);
}

/**
 * Returns sum_{i=0}^{n-1} floor((a*i+b)/m).
 * All arguments are nonnegative and m is positive.
 */
function floorSum(int $n, int $m, int $a, int $b): int
{
    $answer = 0;

    while (true) {
        if ($a >= $m) {
            $answer += intdiv($n * ($n - 1), 2) * intdiv($a, $m);
            $a %= $m;
        }

        if ($b >= $m) {
            $answer += $n * intdiv($b, $m);
            $b %= $m;
        }

        $yMax = $a * $n + $b;
        if ($yMax < $m) {
            break;
        }

        $n = intdiv($yMax, $m);
        $b = $yMax % $m;

        $tmp = $m;
        $m = $a;
        $a = $tmp;
    }

    return $answer;
}

$testCases = nextInt();
