        $b = nextInt();
        $c = nextInt();

        if (!$possible) {
            continue;
        }

        $d = $c - 1;
        $xNumerator = $d - $b;

        // Even (x, y) = (1, 1) does not satisfy this constraint.
        if ($xNumerator < $a) {
            $possible = false;
            $lines = [];
            continue;
        }

        $lineMaxX = intdiv($xNumerator, $a);
        if ($lineMaxX < $maxX) {
            $maxX = $lineMaxX;
        }

        // y <= floor((D - A*x) / B)
        $lines[] = [$a, $b, $d];
    }

    if (!$possible) {
        $output[] = '0';
        continue;
    }

    if (count($lines) > 1) {
        usort($lines, 'compareLines');
    }

    // Lower envelope, with integer starting positions.
    $hA = [];
    $hB = [];
    $hD = [];
    $hStart = [];
