            // (D_old - A_old*x)/B_old
            // (D_new - A_new*x)/B_new
            $denominator = $a * $hB[$last] - $hA[$last] * $b;
            $numerator = $d * $hB[$last] - $hD[$last] * $b;
            $start = ceilDiv($numerator, $denominator);

