        }

        $length = $right - $left + 1;

        // Reverse x = right - t:
        // floor((D - A*x)/B)
        // = floor((A*t + D - A*right)/B).
        $base = $hD[$i] - $hA[$i] * $right;
        $answer += floorSum(
            $length,
            $hB[$i],
            $hA[$i],
            $base
        );
    }

    $output[] = (string)$answer;
}

echo implode("\n", $output);
