<?php

$data = file_get_contents('php://stdin');
$pos = 0;
$dataLength = strlen($data);

function nextInt(): int
{
    global $data, $pos, $dataLength;

    while ($pos < $dataLength && ord($data[$pos]) <= 32) {
        ++$pos;
    }

    $value = 0;
    while ($pos < $dataLength) {
        $c = ord($data[$pos]);
        if ($c < 48 || $c > 57) {
            break;
        }
        $value = $value * 10 + ($c - 48);
        ++$pos;
    }

    return $value;
}

$N = nextInt();
$M = nextInt();
$K = nextInt();

$votes = [];
$sumVotes = 0;

for ($i = 0; $i < $N; ++$i) {
    $votes[$i] = nextInt();
    $sumVotes += $votes[$i];
}

$remaining = $K - $sumVotes;
unset($data);

if ($M === $N) {
    echo implode(' ', array_fill(0, $N, 0)), PHP_EOL;
    exit;
}

$ids = range(0, $N - 1);
array_multisort(
    $votes, SORT_ASC, SORT_NUMERIC,
    $ids, SORT_ASC, SORT_NUMERIC
);

$prefix = array_fill(0, $N + 1, 0);
for ($i = 0; $i < $N; ++$i) {
    $prefix[$i + 1] = $prefix[$i] + $votes[$i];
}

/* For each sorted position, store the first position with a greater value. */
$upperEqual = array_fill(0, $N, 0);
$i = 0;
while ($i < $N) {
    $j = $i + 1;
    while ($j < $N && $votes[$j] === $votes[$i]) {
        ++$j;
    }
    for ($t = $i; $t < $j; ++$t) {
        $upperEqual[$t] = $j;
    }
    $i = $j;
}

$answers = array_fill(0, $N, 0);
$topStart = $N - $M;

for ($p = 0; $p < $N; ++$p) {
    $a = $votes[$p];
    $isHigh = ($p >= $topStart);

    if ($isHigh) {
        // Top M+1 candidates, excluding the candidate themself.
        $start = $topStart - 1;
    } else {
        // The candidate is outside the top M.
        $start = $topStart;
    }

    // Number and sum of selected competitors whose votes are <= a.
    $u = $upperEqual[$p];

    if ($u <= $start) {
        $q0 = 0;
        $sum0 = 0;
    } else {
        $q0 = $u - $start;
        $sum0 = $prefix[$u] - $prefix[$start];

        if ($isHigh) {
            --$q0;
            $sum0 -= $a;
        }
    }

    // Votes needed at X=0 to make M competitors strictly exceed this candidate.
    $initialCost = $q0 * ($a + 1) - $sum0;

    if ($initialCost > $remaining) {
        $answers[$ids[$p]] = 0;
        continue;
    }

    /*
     * Search for the first competitor value c > a whose activation point
     * X = c-a is already guaranteed (i.e. the adversary cannot defeat
     * the candidate there).
     */
    $lo = $q0;
    $hi = $M;

    while ($lo < $hi) {
        $mid = ($lo + $hi) >> 1;

        $globalIndex = $start + $mid;
        if ($isHigh && $globalIndex >= $p) {
            ++$globalIndex;
        }

        $c = $votes[$globalIndex];
        $groupEnd = $upperEqual[$globalIndex];

        $q = $groupEnd - $start;
        $selectedSum = $prefix[$groupEnd] - $prefix[$start];

        if ($isHigh && $p < $groupEnd) {
            --$q;
            $selectedSum -= $a;
        }

        $x = $c - $a;
        $failureBudget = $x + $q * ($c + 1) - $selectedSum;

        if ($failureBudget <= $remaining) {
            $lo = $mid + 1;
        } else {
            $hi = $mid;
        }
    }

    $activeCount = $lo;

    // Sum of the first activeCount values in the selected competitor list.
    $rawEnd = $start + $activeCount;

    if (!$isHigh || $rawEnd <= $p) {
        $activeSum = $prefix[$rawEnd] - $prefix[$start];
    } else {
        $actualEnd = $rawEnd + 1;
        $activeSum = $prefix[$actualEnd] - $prefix[$start] - $a;
    }

    $numerator = $remaining
        - $activeCount * ($a + 1)
        + $activeSum;

    $maxFailingX = intdiv($numerator, $activeCount + 1);

    // If an infeasible activation point exists, stay below that point.
    if ($lo < $M) {
        $globalIndex = $start + $lo;
        if ($isHigh && $globalIndex >= $p) {
            ++$globalIndex;
        }

        $activationCap = $votes[$globalIndex] - $a - 1;
        if ($maxFailingX > $activationCap) {
            $maxFailingX = $activationCap;
        }
    }

    if ($maxFailingX >= $remaining) {
        $answers[$ids[$p]] = -1;
    } else {
        $answers[$ids[$p]] = $maxFailingX + 1;
    }
}

echo implode(' ', $answers), PHP_EOL;
