$tokens = preg_split('/\s+/', trim(file_get_contents('php://stdin')));
$index = 0;

$N = (int)$tokens[$index++];
$W = (int)$tokens[$index++];

$dp = array_fill(0, $W + 1, 0);

for ($item = 0; $item < $N; ++$item) {
    $weight = (int)$tokens[$index++];
    $value = (int)$tokens[$index++];

    $nextDp = array_fill(0, $W + 1, 0);
    $maxRemainder = min($weight - 1, $W);

    for ($r = 0; $r <= $maxRemainder; ++$r) {
        $maxX = intdiv($W - $r, $weight);

        $lineT = [];
        $lineB = [];
        $head = 0;
        $tail = 0;

        for ($x = 0, $position = $r; $x <= $maxX; ++$x, $position += $weight) {
            $newT = $x;
            $newB = $dp[$position] - $x * $value - $x * $x;

            while ($tail - $head >= 2) {
                $t1 = $lineT[$tail - 2];
                $t2 = $lineT[$tail - 1];
                $b1 = $lineB[$tail - 2];
                $b2 = $lineB[$tail - 1];

                if (($b1 - $b2) * ($newT - $t2) >=
                    ($b2 - $newB) * ($t2 - $t1)) {
                    --$tail;
                } else {
                    break;
                }
            }

            $lineT[$tail] = $newT;
            $lineB[$tail] = $newB;
            ++$tail;

            while ($tail - $head >= 2) {
                $currentValue = $lineB[$head] + 2 * $lineT[$head] * $x;
                $nextValue = $lineB[$head + 1] + 2 * $lineT[$head + 1] * $x;

                if ($currentValue <= $nextValue) {
                    ++$head;
                } else {
                    break;
                }
            }

            $bestLineValue = $lineB[$head] + 2 * $lineT[$head] * $x;
            $nextDp[$position] = -$x * $x + $x * $value + $bestLineValue;
        }
    }

    $dp = $nextDp;
}

echo $dp[$W], PHP_EOL;
