    $startY[$i][0] = $ay;
    $endX[$i][0] = $cx;
    $endY[$i][0] = $cy;

    // Direction 1: (C, D) -> (A, B)
    $startX[$i][1] = $cx;
    $startY[$i][1] = $cy;
    $endX[$i][1] = $ax;
    $endY[$i][1] = $ay;

    $dx = $ax - $cx;
    $dy = $ay - $cy;
    $totalDrawingLength += sqrt($dx * $dx + $dy * $dy);
}

