$stateCount = 2 * $n;
$inf = INF;

$dp = [];
for ($mask = 0; $mask < $maskCount; $mask++) {
    $dp[$mask] = array_fill(0, $stateCount, $inf);
}

// Choose the first segment and its drawing direction.
for ($i = 0; $i < $n; $i++) {
    for ($direction = 0; $direction < 2; $direction++) {
        $x = $startX[$i][$direction];
        $y = $startY[$i][$direction];
        $dp[1 << $i][$i * 2 + $direction] = sqrt($x * $x + $y * $y);
    }
