    for ($last = 0; $last < $n; $last++) {
        if (($mask & (1 << $last)) === 0) {
            continue;
        }

        for ($lastDirection = 0; $lastDirection < 2; $lastDirection++) {
            $state = $last * 2 + $lastDirection;
            $currentCost = $dp[$mask][$state];

            if (is_infinite($currentCost)) {
                continue;
            }

            $currentX = $endX[$last][$lastDirection];
            $currentY = $endY[$last][$lastDirection];

            for ($next = 0; $next < $n; $next++) {
                if (($mask & (1 << $next)) !== 0) {
