                for ($nextDirection = 0; $nextDirection < 2; $nextDirection++) {
                    $dx = $currentX - $startX[$next][$nextDirection];
                    $dy = $currentY - $startY[$next][$nextDirection];
                    $newCost = $currentCost + sqrt($dx * $dx + $dy * $dy);
                    $nextState = $next * 2 + $nextDirection;

                    if ($newCost < $dp[$nextMask][$nextState]) {
                        $dp[$nextMask][$nextState] = $newCost;
                    }
                }
            }
        }
    }
}

$fullMask = $maskCount - 1;
$minimumNonPrintingDistance = min($dp[$fullMask]);

