<?php

$tokens = preg_split('/\s+/', trim(stream_get_contents(STDIN)));
$index = 0;

$n = (int)$tokens[$index++];
$budget = (int)$tokens[$index++];

$machines = [];
for ($i = 0; $i < $n; $i++) {
    $machines[] = [
        (int)$tokens[$index++], // A
        (int)$tokens[$index++], // P
        (int)$tokens[$index++], // B
        (int)$tokens[$index++], // Q
    ];
}

function isFeasible(array $machines, int $target, int $budget): bool
{
    $totalCost = 0;

    foreach ($machines as [$a, $p, $b, $q]) {
        $minimumCost = PHP_INT_MAX;

        // There is an optimal solution with either fewer than B units of S
        // or fewer than A units of T.
        for ($s = 0; $s <= $b; $s++) {
            $remaining = $target - $s * $a;
            $t = $remaining > 0 ? intdiv($remaining + $b - 1, $b) : 0;
            $cost = $s * $p + $t * $q;
            if ($cost < $minimumCost) {
                $minimumCost = $cost;
            }
        }

        for ($t = 0; $t <= $a; $t++) {
            $remaining = $target - $t * $b;
            $s = $remaining > 0 ? intdiv($remaining + $a - 1, $a) : 0;
            $cost = $s * $p + $t * $q;
            if ($cost < $minimumCost) {
                $minimumCost = $cost;
            }
        }

        $totalCost += $minimumCost;
        if ($totalCost > $budget) {
            return false;
        }
    }

    return true;
}

$low = 0;
$high = 1_000_000_001;

while ($high - $low > 1) {
    $mid = intdiv($low + $high, 2);

    if (isFeasible($machines, $mid, $budget)) {
        $low = $mid;
    } else {
        $high = $mid;
    }
}

echo $low, PHP_EOL;
