$K = (int)$tokens[$pos++];
$X = (int)$tokens[$pos++];

$T = array_fill(0, $N + 1, 0);
$prefix = array_fill(0, $N + 1, 0);

for ($i = 1; $i <= $N; $i++) {
    $T[$i] = (int)$tokens[$pos++];
    $prefix[$i] = $prefix[$i - 1] + $T[$i];
}

// $dp[$i][$day] = minimum dissatisfaction after shipping the first i orders,
// with the latest shipment made on $day.
$dp = array_fill(0, $N + 1, null);

// Initialize the first shipment.
for ($size = 1; $size <= min($K, $N); $size++) {
    $day = $T[$size];
    $cost = $size * $day - $prefix[$size];
    $dp[$size] = [$day => $cost];
}

for ($i = 1; $i < $N; $i++) {
    if ($dp[$i] === null) {
        continue;
    }

    $maxBatch = min($K, $N - $i);

    foreach ($dp[$i] as $lastDay => $currentCost) {
        $lastDay = (int)$lastDay;

        for ($size = 1; $size <= $maxBatch; $size++) {
            $j = $i + $size;
            $shipDay = max($T[$j], $lastDay + $X);

            $batchArrivalSum = $prefix[$j] - $prefix[$i];
            $newCost = $currentCost + $size * $shipDay - $batchArrivalSum;

            if ($dp[$j] === null) {
                $dp[$j] = [];
            }

            if (!isset($dp[$j][$shipDay]) || $newCost < $dp[$j][$shipDay]) {
                $dp[$j][$shipDay] = $newCost;
            }
        }
    }
}

