<?php

$tokens = preg_split('/\s+/', trim(stream_get_contents(STDIN)));
$index = 0;
$n = (int)$tokens[$index++];

$vertexCount = 26;
$edges = [];
$reach = array_fill(0, $vertexCount, null);

for ($i = 0; $i < $vertexCount; $i++) {
    $reach[$i] = array_fill(0, $vertexCount, false);
    $reach[$i][$i] = true;
}

for ($i = 0; $i < $n; $i++) {
    $s = $tokens[$index++];
    $from = ord($s[0]) - ord('A');
    $to = ord($s[1]) - ord('A');
    $edges[] = [$from, $to];
    $reach[$from][$to] = true;
}

// Transitive closure.
for ($k = 0; $k < $vertexCount; $k++) {
    for ($i = 0; $i < $vertexCount; $i++) {
        if (!$reach[$i][$k]) {
            continue;
        }
        for ($j = 0; $j < $vertexCount; $j++) {
            if ($reach[$k][$j]) {
                $reach[$i][$j] = true;
            }
        }
    }
}

// Build strongly connected components.
$component = array_fill(0, $vertexCount, -1);
$representatives = [];
$componentCount = 0;

for ($i = 0; $i < $vertexCount; $i++) {
    if ($component[$i] !== -1) {
        continue;
    }

    $representatives[$componentCount] = $i;
    for ($j = 0; $j < $vertexCount; $j++) {
        if (
            $component[$j] === -1 &&
            $reach[$i][$j] &&
            $reach[$j][$i]
        ) {
            $component[$j] = $componentCount;
        }
    }
    $componentCount++;
}

// Reachability between SCCs, including reachability to itself.
$componentReach = array_fill(0, $componentCount, null);
for ($i = 0; $i < $componentCount; $i++) {
    $componentReach[$i] = array_fill(0, $componentCount, false);
    for ($j = 0; $j < $componentCount; $j++) {
        $componentReach[$i][$j] =
            $reach[$representatives[$i]][$representatives[$j]];
    }
}

/*
 * Each inter-SCC edge is an item.
 * All edges lying inside one SCC can be covered in one visit, so they form
 * one additional item for that SCC.
 */
$hasInternalEdge = array_fill(0, $componentCount, false);
$itemStart = [];
$itemEnd = [];

foreach ($edges as [$from, $to]) {
    $fromComponent = $component[$from];
    $toComponent = $component[$to];

    if ($fromComponent === $toComponent) {
        $hasInternalEdge[$fromComponent] = true;
    } else {
        $itemStart[] = $fromComponent;
        $itemEnd[] = $toComponent;
    }
}

for ($c = 0; $c < $componentCount; $c++) {
    if ($hasInternalEdge[$c]) {
        $itemStart[] = $c;
        $itemEnd[] = $c;
    }
}

$itemCount = count($itemStart);

/*
 * Item u can precede item v in one string exactly when the ending SCC of u
 * can reach the starting SCC of v. The answer is the minimum chain cover of
 * this partial order, equal to itemCount - maximum matching.
 */
$pairLeft = array_fill(0, $itemCount, -1);
$pairRight = array_fill(0, $itemCount, -1);
$distance = array_fill(0, $itemCount, 0);
$infinity = PHP_INT_MAX;
$matching = 0;

while (true) {
    $queue = [];
    $head = 0;
    $distanceToFree = $infinity;

    for ($u = 0; $u < $itemCount; $u++) {
        if ($pairLeft[$u] === -1) {
            $distance[$u] = 0;
            $queue[] = $u;
        } else {
            $distance[$u] = $infinity;
        }
    }

    while ($head < count($queue)) {
        $u = $queue[$head++];

        if ($distance[$u] >= $distanceToFree) {
            continue;
        }

        $endComponent = $itemEnd[$u];

        for ($v = 0; $v < $itemCount; $v++) {
            if (
                $u === $v ||
                !$componentReach[$endComponent][$itemStart[$v]]
            ) {
                continue;
            }

            $matchedLeft = $pairRight[$v];

            if ($matchedLeft === -1) {
                $distanceToFree = $distance[$u] + 1;
            } elseif ($distance[$matchedLeft] === $infinity) {
                $distance[$matchedLeft] = $distance[$u] + 1;
                $queue[] = $matchedLeft;
            }
        }
    }

    if ($distanceToFree === $infinity) {
        break;
    }

    $dfs = function (int $u) use (
        &$dfs,
        &$pairLeft,
        &$pairRight,
        &$distance,
        &$itemStart,
        &$itemEnd,
        &$componentReach,
        $itemCount,
        $distanceToFree,
        $infinity
    ): bool {
        $endComponent = $itemEnd[$u];

        for ($v = 0; $v < $itemCount; $v++) {
            if (
                $u === $v ||
                !$componentReach[$endComponent][$itemStart[$v]]
            ) {
                continue;
            }

            $matchedLeft = $pairRight[$v];

            if ($matchedLeft === -1) {
                if ($distance[$u] + 1 !== $distanceToFree) {
                    continue;
                }
            } elseif (
                $distance[$matchedLeft] !== $distance[$u] + 1 ||
                !$dfs($matchedLeft)
            ) {
                continue;
            }

            $pairLeft[$u] = $v;
            $pairRight[$v] = $u;
            return true;
        }

        $distance[$u] = $infinity;
        return false;
    };

    for ($u = 0; $u < $itemCount; $u++) {
        if ($pairLeft[$u] === -1 && $dfs($u)) {
            $matching++;
        }
    }
}

echo ($itemCount - $matching) . PHP_EOL;
