        $value = $value * 10 + ($c - 48);
        $pos++;
    }

    return $value;
}

function dijkstra(
    int $n,
    int $source,
    array &$head,
    array &$to,
    array &$weight,
    array &$next
): array {
    $inf = PHP_INT_MAX;
    $dist = array_fill(0, $n + 1, $inf);
    $dist[$source] = 0;

    $queue = new SplPriorityQueue();
    $queue->setExtractFlags(SplPriorityQueue::EXTR_BOTH);
    $queue->insert($source, 0);

    while (!$queue->isEmpty()) {
        $item = $queue->extract();
        $v = $item['data'];
        $currentDistance = -$item['priority'];

        if ($currentDistance != $dist[$v]) {
            continue;
        }

        for ($e = $head[$v]; $e !== -1; $e = $next[$e]) {
            $u = $to[$e];
            $newDistance = $currentDistance + $weight[$e];

            if ($newDistance < $dist[$u]) {
                $dist[$u] = $newDistance;
                $queue->insert($u, -$newDistance);
            }
        }
    }

    return $dist;
}

