function minimumMoves(int $n, int $start, int $target, int $blocked): int
{
    if ($start === $target) {
        return 0;
    }

    $queue = new SplQueue();
    $queue->enqueue([$start, 0]);
    $visited = array_fill(0, $n + 1, false);
    $visited[$start] = true;

    while (!$queue->isEmpty()) {
        [$position, $distance] = $queue->dequeue();

        $neighbors = [
            $position === 1 ? $n : $position - 1,
            $position === $n ? 1 : $position + 1
        ];

        foreach ($neighbors as $next) {
            if ($next === $blocked || $visited[$next]) {
                continue;
            }

            if ($next === $target) {
                return $distance + 1;
            }

            $visited[$next] = true;
            $queue->enqueue([$next, $distance + 1]);
        }
    }

    return 0;
}

for ($i = 0; $i < $q; $i++) {
    $hand = $tokens[$index++];
    $target = (int)$tokens[$index++];

    if ($hand === 'L') {
        $total += minimumMoves($n, $left, $target, $right);
        $left = $target;
    } else {
        $total += minimumMoves($n, $right, $target, $left);
        $right = $target;
    }
}

echo $total . PHP_EOL;
