    $nextDp = array_fill(0, $n, $inf);

    $clockwiseNeighbor = $target + 1;
    if ($clockwiseNeighbor === $n) {
        $clockwiseNeighbor = 0;
    }

    $counterclockwiseNeighbor = $target - 1;
    if ($counterclockwiseNeighbor < 0) {
        $counterclockwiseNeighbor = $n - 1;
    }

    for ($otherPosition = 0; $otherPosition < $n; ++$otherPosition) {
        $baseCost = $dp[$otherPosition];
        if ($baseCost === $inf) {
            continue;
        }

        if ($sameHand) {
            $movingPosition = $previousTarget;
            $blockingPosition = $otherPosition;
        } else {
            $movingPosition = $otherPosition;
            $blockingPosition = $previousTarget;
        }

        // Move the instructed hand clockwise.
        $distance = $target - $movingPosition;
        if ($distance < 0) {
