const MOD = 998244353;

$input = file_get_contents("php://stdin");
$inputPos = 0;
$inputLength = strlen($input);

function nextIntFast(): int
{
    global $input, $inputPos, $inputLength;

    while ($inputPos < $inputLength && ord($input[$inputPos]) <= 32) {
        ++$inputPos;
    }

    $value = 0;
    while ($inputPos < $inputLength) {
        $c = ord($input[$inputPos]);
        if ($c < 48 || $c > 57) {
            break;
        }
        $value = $value * 10 + ($c - 48);
        ++$inputPos;
    }

    return $value;
}

function findSet(array &$dsu, int $x): int
{
    $root = $x;
    while ($dsu[$root] !== $root) {
        $root = $dsu[$root];
    }

    while ($dsu[$x] !== $x) {
        $next = $dsu[$x];
        $dsu[$x] = $root;
        $x = $next;
    }

    return $root;
}

function modPow(int $base, int $exponent): int
{
    $result = 1;
    $base %= MOD;

    while ($exponent > 0) {
        if (($exponent & 1) === 1) {
            $result = ($result * $base) % MOD;
        }
        $base = ($base * $base) % MOD;
        $exponent >>= 1;
    }

    return $result;
}

$testCases = nextIntFast();
$output = '';

for ($case = 0; $case < $testCases; ++$case) {
    $n = nextIntFast();

    $parent = array_fill(0, $n + 1, 0);
    for ($i = 1; $i <= $n; ++$i) {
        $parent[$i] = nextIntFast();
    }

    $dsu = range(0, $n);
    $componentWeight = array_fill(0, $n + 1, 0);
    $componentLength = array_fill(0, $n + 1, 1);
    $componentLength[0] = 0;

    $heap = array_fill(0, $n + 1, 0);
    $heapPosition = array_fill(0, $n + 1, 0);

    $totalWeight = 0;

    for ($i = 1; $i <= $n; ++$i) {
        $weight = nextIntFast();
        $componentWeight[$i] = $weight;
        $totalWeight += $weight;
        $heap[$i] = $i;
        $heapPosition[$i] = $i;
    }

    $heapSize = $n;

    // Build a max-heap ordered by componentWeight / componentLength.
    for ($start = $heapSize >> 1; $start >= 1; --$start) {
        $item = $heap[$start];
        $position = $start;
        $half = $heapSize >> 1;

        while ($position <= $half) {
            $left = $position << 1;
            $right = $left + 1;
            $best = $left;
            $bestNode = $heap[$left];

            if ($right <= $heapSize) {
                $rightNode = $heap[$right];
                if (
                    $componentWeight[$rightNode] * $componentLength[$bestNode]
                    > $componentWeight[$bestNode] * $componentLength[$rightNode]
                ) {
                    $best = $right;
                    $bestNode = $rightNode;
                }
            }

            if (
                $componentWeight[$bestNode] * $componentLength[$item]
                <= $componentWeight[$item] * $componentLength[$bestNode]
            ) {
                break;
            }

            $heap[$position] = $bestNode;
            $heapPosition[$bestNode] = $position;
            $position = $best;
        }

        $heap[$position] = $item;
        $heapPosition[$item] = $position;
    }

    // Every singleton contributes its own weight at local position 1.
    $weightedCompletionSum = $totalWeight;

    while ($heapSize > 0) {
        // Extract the component of maximum density.
        $x = $heap[1];
        $lastNode = $heap[$heapSize];
        --$heapSize;
        $heapPosition[$x] = 0;

        if ($heapSize > 0) {
            $position = 1;
            $half = $heapSize >> 1;

            while ($position <= $half) {
                $left = $position << 1;
                $right = $left + 1;
                $best = $left;
                $bestNode = $heap[$left];

                if ($right <= $heapSize) {
                    $rightNode = $heap[$right];
                    if (
                        $componentWeight[$rightNode] * $componentLength[$bestNode]
                        > $componentWeight[$bestNode] * $componentLength[$rightNode]
                    ) {
                        $best = $right;
                        $bestNode = $rightNode;
                    }
                }

                if (
                    $componentWeight[$bestNode] * $componentLength[$lastNode]
                    <= $componentWeight[$lastNode] * $componentLength[$bestNode]
                ) {
                    break;
                }

                $heap[$position] = $bestNode;
                $heapPosition[$bestNode] = $position;
                $position = $best;
            }

            $heap[$position] = $lastNode;
            $heapPosition[$lastNode] = $position;
        }

        $y = findSet($dsu, $parent[$x]);

        // Append component x after component y.
        $weightedCompletionSum += $componentLength[$y] * $componentWeight[$x];

        $componentWeight[$y] += $componentWeight[$x];
        $componentLength[$y] += $componentLength[$x];
        $dsu[$x] = $y;

        // The density of y only increases, so restore the heap by moving it up.
        if ($y !== 0) {
            $position = $heapPosition[$y];

            while ($position > 1) {
                $up = $position >> 1;
                $upNode = $heap[$up];

                if (
                    $componentWeight[$y] * $componentLength[$upNode]
                    <= $componentWeight[$upNode] * $componentLength[$y]
                ) {
                    break;
                }

                $heap[$position] = $upNode;
                $heapPosition[$upNode] = $position;
                $position = $up;
            }

            $heap[$position] = $y;
            $heapPosition[$y] = $position;
        }
    }

    $numerator = $weightedCompletionSum % MOD;
    $inverse = modPow($totalWeight, MOD - 2);
