const MOD = 998244353;

function getAllowedAnchors(string $row, int $width, int $stateCount): array
{
    $allowed = array_fill(0, $stateCount, 0);

    for ($mask = 0; $mask < $stateCount; $mask++) {
        $candidates = 7; // Bits 0, 1, 2 represent the possible first-cell colors.
        $offset = 0;

        for ($j = 0; $j < $width; $j++) {
            $ch = $row[$j];

            if ($ch !== '?') {
                $digit = ord($ch) - ord('1');
                $required = $digit - $offset;
                if ($required < 0) {
                    $required += 3;
                }
                $candidates &= 1 << $required;

                if ($candidates === 0) {
                    break;
                }
            }

            if ($j + 1 < $width) {
                if ((($mask >> $j) & 1) === 1) {
                    $offset++;
                    if ($offset === 3) {
                        $offset = 0;
                    }
                } else {
                    $offset--;
                    if ($offset < 0) {
                        $offset = 2;
                    }
                }
            }
        }

        $allowed[$mask] = $candidates;
    }

    return $allowed;
}

