            $half = 1 << $bit;
            $block = $half << 1;

            for ($base = 0; $base < $stateCount; $base += $block) {
                $end = $base + $half;
                for ($mask0 = $base; $mask0 < $end; $mask0++) {
                    $mask1 = $mask0 + $half;

                    $sum = $plus[$mask1] + $minus[$mask0];
                    if ($sum >= MOD) {
                        $sum -= MOD;
