        }

        $out = array_fill(0, $stateCount, 0);
        $colorBit = 1 << $targetColor;

        for ($mask = 0; $mask < $stateCount; $mask++) {
            if (($allowed[$mask] & $colorBit) !== 0) {
                $sum = $plus[$mask] + $minus[$mask];
                if ($sum >= MOD) {
                    $sum -= MOD;
                }
                $out[$mask] = $sum;
            }
        }

        $newDp[$targetColor] = $out;
        unset($plus, $minus, $out);
    }

    $dp = $newDp;
}

$answer = 0;
for ($color = 0; $color < 3; $color++) {
    for ($mask = 0; $mask < $stateCount; $mask++) {
        $answer += $dp[$color][$mask];
        if ($answer >= MOD) {
            $answer -= MOD;
        }
    }
