function findRoot(array &$parent, int $x): int
{
    $root = $x;
    while ($parent[$root] !== $root) {
        $root = $parent[$root];
    }

    while ($parent[$x] !== $x) {
        $next = $parent[$x];
        $parent[$x] = $root;
        $x = $next;
    }

    return $root;
}

