$p = 0;

$N = (int)$tokens[$p++];
$M = (int)$tokens[$p++];
$L = (int)$tokens[$p++];

$values = [];
for ($i = 0; $i < $N + $M + $L; $i++) {
    $values[] = (int)$tokens[$p++];
}

$K = $N + $M + $L;

$pow3 = array_fill(0, $K + 1, 1);
for ($i = 1; $i <= $K; $i++) {
    $pow3[$i] = $pow3[$i - 1] * 3;
}

$bits = [];
for ($i = 0; $i < $K; $i++) {
    $bits[$i] = 1 << $i;
}

$lessMask = array_fill(0, $K, 0);
for ($i = 0; $i < $K; $i++) {
    for ($j = 0; $j < $K; $j++) {
        if ($values[$j] < $values[$i]) {
            $lessMask[$i] |= $bits[$j];
        }
    }
}

// Ownership digit in ternary:
// 0 = table, 1 = Takahashi, 2 = Aoki.
$initialState = 0;
for ($i = 0; $i < $N; $i++) {
    $initialState += $pow3[$i];
}
for ($i = $N; $i < $N + $M; $i++) {
    $initialState += 2 * $pow3[$i];
}

$totalStates = $pow3[$K];
$memo = str_repeat(chr(0), $totalStates * 2);
$loseChar = chr(1);
$winChar = chr(2);

$dfs = function (int $state, int $turn) use (
    &$dfs,
    &$memo,
    $K,
    $pow3,
    $bits,
    $lessMask,
    $loseChar,
    $winChar
): bool {
    $memoIndex = $state * 2 + $turn;
    $cached = ord($memo[$memoIndex]);

    if ($cached !== 0) {
        return $cached === 2;
    }

    $owner = ($turn === 0) ? 1 : 2;
    $handMask = 0;
    $tableMask = 0;
    $tmp = $state;

    for ($i = 0; $i < $K; $i++) {
        $digit = $tmp % 3;
        $tmp = intdiv($tmp, 3);

        if ($digit === 0) {
            $tableMask |= $bits[$i];
        } elseif ($digit === $owner) {
            $handMask |= $bits[$i];
        }
    }

    if ($handMask === 0) {
        $memo[$memoIndex] = $loseChar;
        return false;
    }

    $nextTurn = 1 - $turn;

    for ($x = 0; $x < $K; $x++) {
        if (($handMask & $bits[$x]) === 0) {
            continue;
        }

        // Play card x without taking a card from the table.
        $baseState = $state - $owner * $pow3[$x];
        if (!$dfs($baseState, $nextTurn)) {
            $memo[$memoIndex] = $winChar;
            return true;
        }

        // Play card x and take a smaller card y from the table.
        $candidates = $tableMask & $lessMask[$x];
        for ($y = 0; $y < $K; $y++) {
            if (($candidates & $bits[$y]) === 0) {
                continue;
            }

            $nextState = $baseState + $owner * $pow3[$y];
            if (!$dfs($nextState, $nextTurn)) {
                $memo[$memoIndex] = $winChar;
                return true;
            }
        }
    }

    $memo[$memoIndex] = $loseChar;
    return false;
};

echo $dfs($initialState, 0) ? "Takahashi\n" : "Aoki\n";
