<?php

const MOD = 998244353;
const INV4 = 748683265;

function nextInt(string $data, int &$index, int $length): int
{
    while ($index < $length && ord($data[$index]) <= 32) {
        ++$index;
    }

    $value = 0;
    while ($index < $length) {
        $c = ord($data[$index]);
        if ($c < 48 || $c > 57) {
            break;
        }
        $value = $value * 10 + ($c - 48);
        ++$index;
    }

    return $value;
}

function bitAdd(array &$bit, int $n, int $index, int $delta): void
{
    while ($index <= $n) {
        $bit[$index] += $delta;
        $index += $index & (-$index);
    }
}

function bitSum(array &$bit, int $index): int
{
    $sum = 0;
    while ($index > 0) {
        $sum += $bit[$index];
        $index -= $index & (-$index);
    }
    return $sum;
}

function modPow(int $base, int $exponent): int
{
    $result = 1;
    while ($exponent > 0) {
        if (($exponent & 1) === 1) {
            $result = ($result * $base) % MOD;
        }
        $base = ($base * $base) % MOD;
        $exponent >>= 1;
    }
    return $result;
}

$data = file_get_contents('php://stdin');
$index = 0;
$length = strlen($data);

$n = nextInt($data, $index, $length);
$k = nextInt($data, $index, $length);

$p = [];
for ($i = 0; $i < $n; ++$i) {
    $p[$i] = nextInt($data, $index, $length);
}

/* Inversion count of the entire permutation. */
$bit = array_fill(0, $n + 1, 0);
$totalInversions = 0;

for ($i = 0; $i < $n; ++$i) {
    $value = $p[$i];
    $lessOrEqual = bitSum($bit, $value);
    $totalInversions += $i - $lessOrEqual;
    bitAdd($bit, $n, $value, 1);
}

/* Sum of inversion counts over all length-K subarrays. */
$bit = array_fill(0, $n + 1, 0);
$windowInversions = 0;

for ($i = 0; $i < $k; ++$i) {
    $value = $p[$i];
    $lessOrEqual = bitSum($bit, $value);
    $windowInversions += $i - $lessOrEqual;
    bitAdd($bit, $n, $value, 1);
}

$sumWindowInversions = $windowInversions;
$windowCount = $n - $k + 1;

for ($left = 0; $left + $k < $n; ++$left) {
    $removed = $p[$left];

    $windowInversions -= bitSum($bit, $removed - 1);
    bitAdd($bit, $n, $removed, -1);

    $added = $p[$left + $k];
    $lessOrEqual = bitSum($bit, $added);
    $windowInversions += ($k - 1) - $lessOrEqual;
    bitAdd($bit, $n, $added, 1);

    $sumWindowInversions += $windowInversions;
}

$inverseWindowCount = modPow($windowCount, MOD - 2);
$averageRemoved = (($sumWindowInversions % MOD) * $inverseWindowCount) % MOD;

$expectedInternal = (($k * ($k - 1)) % MOD) * INV4 % MOD;

$answer = (($totalInversions % MOD) - $averageRemoved + $expectedInternal) % MOD;
if ($answer < 0) {
    $answer += MOD;
}

echo $answer, PHP_EOL;
