            $lazyAssign[$node] = 0;
        }
    }

    // Range minimum query.
    $minimum = PHP_INT_MAX;
    $ql = $l;
    $qr = $r;

    while ($ql < $qr) {
        if (($ql & 1) !== 0) {
            if ($segmentTree[$ql] < $minimum) {
                $minimum = $segmentTree[$ql];
            }
            ++$ql;
        }

        if (($qr & 1) !== 0) {
            --$qr;
            if ($segmentTree[$qr] < $minimum) {
                $minimum = $segmentTree[$qr];
            }
        }

        $ql >>= 1;
        $qr >>= 1;
    }

    $newRow = $minimum - 1;

    // Every value in the interval is greater than newRow, so assign newRow.
    $ul = $l;
    $ur = $r;

    while ($ul < $ur) {
        if (($ul & 1) !== 0) {
            $segmentTree[$ul] = $newRow;
            if ($ul < $segmentBase) {
                $lazyAssign[$ul] = $newRow;
            }
            ++$ul;
        }

        if (($ur & 1) !== 0) {
            --$ur;
            $segmentTree[$ur] = $newRow;
            if ($ur < $segmentBase) {
                $lazyAssign[$ur] = $newRow;
            }
        }

        $ul >>= 1;
        $ur >>= 1;
    }

    // Rebuild the two boundary paths.
    for ($k = 1; $k <= $segmentHeight; ++$k) {
        $node = $leftLeaf >> $k;
        if ($lazyAssign[$node] === 0) {
            $child = $node << 1;
            $a = $segmentTree[$child];
            $b = $segmentTree[$child + 1];
            $segmentTree[$node] = ($a < $b) ? $a : $b;
        }
    }

    for ($k = 1; $k <= $segmentHeight; ++$k) {
        $node = $rightLeaf >> $k;
        if ($lazyAssign[$node] === 0) {
            $child = $node << 1;
            $a = $segmentTree[$child];
            $b = $segmentTree[$child + 1];
            $segmentTree[$node] = ($a < $b) ? $a : $b;
        }
    }

    return $newRow;
}

$answer = array_fill(0, $N, 0);

for ($row = $H; $row >= 1; --$row) {
    for ($id = $head[$row]; $id !== -1; $id = $next[$id]) {
        $answer[$id] = settleRange($left[$id], $right[$id]);
    }
}

$output = '';
for ($i = 0; $i < $N; ++$i) {
    $output .= $answer[$i] . "\n";

    if (($i & 8191) === 8191) {
        echo $output;
        $output = '';
    }
}
