// Sieve of Eratosthenes up to floor(sqrt(N)).
$isPrime = str_repeat("\1", $limit + 1);
$isPrime[0] = "\0";
if ($limit >= 1) {
    $isPrime[1] = "\0";
}

for ($i = 2; $i <= intdiv($limit, $i); ++$i) {
    if ($isPrime[$i] !== "\1") {
        continue;
    }

    for ($j = $i * $i; $j <= $limit; $j += $i) {
        $isPrime[$j] = "\0";
    }
}

$primes = [];
for ($i = 2; $i <= $limit; ++$i) {
    if ($isPrime[$i] === "\1") {
        $primes[] = $i;
    }
}

$answer = 0;
$primeCount = count($primes);

// Numbers of the form p^2 * q^2, where p and q are distinct primes.
$right = $primeCount - 1;
for ($left = 0; $left < $right; ++$left) {
    while (
        $right > $left &&
        $primes[$left] > intdiv($limit, $primes[$right])
    ) {
        --$right;
    }

    if ($right <= $left) {
        break;
    }

    $answer += $right - $left;
}

// Numbers of the form p^8.
