function findRoot(array &$parent, int $vertex): int
{
    $root = $vertex;
    while ($parent[$root] >= 0) {
        $root = $parent[$root];
    }

    while ($vertex !== $root) {
        $next = $parent[$vertex];
        $parent[$vertex] = $root;
        $vertex = $next;
    }

    return $root;
}

