    $u = intdiv($code, $base);
    $v = $code % $base;

    $rootU = findRoot($parent, $u);
    $rootV = findRoot($parent, $v);

    if ($rootU === $rootV) {
        continue;
    }

    $balanceU = $balance[$rootU];
    $balanceV = $balance[$rootV];

    if ($balanceU > 0 && $balanceV < 0) {
        $answer += min($balanceU, -$balanceV) * $weights[$i];
    } elseif ($balanceU < 0 && $balanceV > 0) {
        $answer += min(-$balanceU, $balanceV) * $weights[$i];
    }

    $mergedBalance = $balanceU + $balanceV;

    if ($parent[$rootU] > $parent[$rootV]) {
        $temp = $rootU;
        $rootU = $rootV;
        $rootV = $temp;
    }

    $parent[$rootU] += $parent[$rootV];
    $parent[$rootV] = $rootU;
    $balance[$rootU] = $mergedBalance;

    ++$unions;
}

