        $i = $this->index;

        while ($i < $n && ord($this->data[$i]) <= 32) {
            ++$i;
        }

        $value = 0;
        while ($i < $n) {
            $c = ord($this->data[$i]);
            if ($c < 48 || $c > 57) {
                break;
            }
            $value = $value * 10 + ($c - 48);
            ++$i;
        }

        $this->index = $i;
        return $value;
    }
