function distanceToPrefix(
    int $a,
    int $threshold,
    int $y,
    int $valueCount,
    int $levelCount,
    array &$onePrefixLevels,
    array &$zeroSumLevels,
    array &$zeroCounts,
    array &$prefixB
): int {
    $totalSum = $prefixB[$y];

    if ($threshold <= 0) {
        return $totalSum - $a * $y;
    }
    if ($threshold >= $valueCount) {
        return $a * $y - $totalSum;
    }

    $left = 0;
    $right = $y;
    $lowerCount = 0;
    $lowerSum = 0;

    for ($level = 0; $level < $levelCount; ++$level) {
        $ones = $onePrefixLevels[$level];
        $zeroSums = $zeroSumLevels[$level];

        $onesLeft = $ones[$left];
        $onesRight = $ones[$right];
        $bit = ($threshold >> ($levelCount - 1 - $level)) & 1;

        if ($bit === 1) {
            $zerosInRange = ($right - $left) - ($onesRight - $onesLeft);
            $lowerCount += $zerosInRange;
            $lowerSum += $zeroSums[$right] - $zeroSums[$left];

            $left = $zeroCounts[$level] + $onesLeft;
            $right = $zeroCounts[$level] + $onesRight;
        } else {
            $left -= $onesLeft;
            $right -= $onesRight;
        }
    }

    return $a * (2 * $lowerCount - $y) + $totalSum - 2 * $lowerSum;
}

