        $x = $queryX[$queryIndex];
        $y = $queryY[$queryIndex];
        $boundary = $boundaries[$queryIndex];

        if ($x > $boundary) {
            for ($i = $boundary; $i < $x; ++$i) {
                $answers[$queryIndex] += distanceToPrefix(
                    $a[$i],
                    $aThreshold[$i],
                    $y,
                    $valueCount,
                    $levelCount,
                    $onePrefixLevels,
                    $zeroSumLevels,
                    $zeroCounts,
                    $prefixB
