            }
        } elseif ($x < $boundary) {
            for ($i = $x; $i < $boundary; ++$i) {
                $answers[$queryIndex] -= distanceToPrefix(
                    $a[$i],
                    $aThreshold[$i],
                    $y,
                    $valueCount,
                    $levelCount,
                    $onePrefixLevels,
                    $zeroSumLevels,
                    $zeroCounts,
                    $prefixB
                );
            }
        }
    }
}

