<?php

class FastScanner
{
    private string $data;
    private int $index = 0;
    private int $length;

    public function __construct()
    {
        $this->data = file_get_contents("php://stdin");
        $this->length = strlen($this->data);
    }

    public function nextInt(): int
    {
        while ($this->index < $this->length && ord($this->data[$this->index]) <= 32) {
            $this->index++;
        }

        $sign = 1;
        if ($this->data[$this->index] === '-') {
            $sign = -1;
            $this->index++;
        }

        $number = 0;
        while ($this->index < $this->length) {
            $c = ord($this->data[$this->index]);
            if ($c < 48 || $c > 57) {
                break;
            }
            $number = $number * 10 + ($c - 48);
            $this->index++;
        }

        return $number * $sign;
    }

    public function next(): string
    {
        while ($this->index < $this->length && ord($this->data[$this->index]) <= 32) {
            $this->index++;
        }

        $start = $this->index;
        while ($this->index < $this->length && ord($this->data[$this->index]) > 32) {
            $this->index++;
        }

        return substr($this->data, $start, $this->index - $start);
    }
}

$scanner = new FastScanner();

$n = $scanner->nextInt();
$m = $scanner->nextInt();
$currentX = $scanner->nextInt();
$currentY = $scanner->nextInt();

$houseX = [];
$houseY = [];
$housesByY = [];

for ($i = 0; $i < $n; $i++) {
    $x = $scanner->nextInt();
    $y = $scanner->nextInt();

    $houseX[$i] = $x;
    $houseY[$i] = $y;
    $housesByY[$y][$i] = $x;
}

$horizontalSegments = [];
$verticalSegments = [];

for ($i = 0; $i < $m; $i++) {
    $direction = $scanner->next();
    $distance = $scanner->nextInt();

    if ($direction === 'L') {
        $nextX = $currentX - $distance;
        $left = $nextX;
        $right = $currentX;

        if (!isset($horizontalSegments[$currentY])) {
            $horizontalSegments[$currentY] = [[], []];
        }
        $horizontalSegments[$currentY][0][] = $left;
        $horizontalSegments[$currentY][1][] = $right;

        $currentX = $nextX;
    } elseif ($direction === 'R') {
        $nextX = $currentX + $distance;
        $left = $currentX;
        $right = $nextX;

        if (!isset($horizontalSegments[$currentY])) {
            $horizontalSegments[$currentY] = [[], []];
        }
        $horizontalSegments[$currentY][0][] = $left;
        $horizontalSegments[$currentY][1][] = $right;

        $currentX = $nextX;
    } elseif ($direction === 'D') {
        $nextY = $currentY - $distance;
        $bottom = $nextY;
        $top = $currentY;

        if (!isset($verticalSegments[$currentX])) {
            $verticalSegments[$currentX] = [[], []];
        }
        $verticalSegments[$currentX][0][] = $bottom;
        $verticalSegments[$currentX][1][] = $top;

        $currentY = $nextY;
    } else { // U
        $nextY = $currentY + $distance;
        $bottom = $currentY;
        $top = $nextY;

        if (!isset($verticalSegments[$currentX])) {
            $verticalSegments[$currentX] = [[], []];
        }
        $verticalSegments[$currentX][0][] = $bottom;
        $verticalSegments[$currentX][1][] = $top;

        $currentY = $nextY;
    }
}

$visited = array_fill(0, $n, false);
$count = 0;
$negativeInfinity = -PHP_INT_MAX - 1;

/* Process horizontal movement segments. */
foreach ($horizontalSegments as $fixedY => &$segments) {
    if (!isset($housesByY[$fixedY])) {
        continue;
    }

    $lefts =& $segments[0];
    $rights =& $segments[1];

    array_multisort(
        $lefts, SORT_ASC, SORT_NUMERIC,
        $rights, SORT_DESC, SORT_NUMERIC
    );

    $points =& $housesByY[$fixedY];
    asort($points, SORT_NUMERIC);

    $segmentCount = count($lefts);
    $segmentIndex = 0;
    $maximumRight = $negativeInfinity;

    foreach ($points as $houseIndex => $x) {
        while ($segmentIndex < $segmentCount && $lefts[$segmentIndex] <= $x) {
            if ($rights[$segmentIndex] > $maximumRight) {
                $maximumRight = $rights[$segmentIndex];
            }
            $segmentIndex++;
        }

        if ($maximumRight >= $x) {
            $visited[$houseIndex] = true;
            $count++;
        }
    }

    unset($lefts, $rights, $points);
}
unset($segments, $horizontalSegments, $housesByY);

/* Only unvisited houses need to be checked against vertical segments. */
$housesByX = [];

for ($i = 0; $i < $n; $i++) {
    if (!$visited[$i]) {
        $housesByX[$houseX[$i]][$i] = $houseY[$i];
    }
}

/* Process vertical movement segments. */
foreach ($verticalSegments as $fixedX => &$segments) {
    if (!isset($housesByX[$fixedX])) {
        continue;
    }

    $bottoms =& $segments[0];
    $tops =& $segments[1];

    array_multisort(
        $bottoms, SORT_ASC, SORT_NUMERIC,
        $tops, SORT_DESC, SORT_NUMERIC
    );

    $points =& $housesByX[$fixedX];
    asort($points, SORT_NUMERIC);

    $segmentCount = count($bottoms);
    $segmentIndex = 0;
    $maximumTop = $negativeInfinity;

    foreach ($points as $houseIndex => $y) {
        while ($segmentIndex < $segmentCount && $bottoms[$segmentIndex] <= $y) {
            if ($tops[$segmentIndex] > $maximumTop) {
                $maximumTop = $tops[$segmentIndex];
            }
            $segmentIndex++;
        }

        if ($maximumTop >= $y) {
            $visited[$houseIndex] = true;
            $count++;
        }
    }

    unset($bottoms, $tops, $points);
}
unset($segments);

echo $currentX . ' ' . $currentY . ' ' . $count . PHP_EOL;
