$K = (int) trim(fgets(STDIN));
$S = rtrim(fgets(STDIN), "\r\n");
$T = rtrim(fgets(STDIN), "\r\n");

$n = strlen($S);
$m = strlen($T);

if (abs($n - $m) > $K) {
    echo "No\n";
    exit;
}

$offset = $K + 1;
$size = 2 * $K + 3;
$prev = array_fill(0, $size, -1);

// Match the common prefix with zero operations.
$x = 0;
while ($x < $n && $x < $m && $S[$x] === $T[$x]) {
    ++$x;
}

if ($x === $n && $x === $m) {
    echo "Yes\n";
    exit;
}

// prev[d + offset] is the furthest position in S reachable on
// diagonal d = position_in_S - position_in_T.
$prev[$offset] = $x;

for ($operations = 1; $operations <= $K; ++$operations) {
    $curr = array_fill(0, $size, -1);

    for ($d = -$operations; $d <= $operations; ++$d) {
        $index = $d + $offset;
        $best = -1;

        // Delete one character from S.
        $sourceX = $prev[$index - 1];
        if ($sourceX >= 0 && $sourceX < $n) {
            $candidate = $sourceX + 1;
            if ($candidate > $best) {
                $best = $candidate;
            }
        }

        // Replace one character in S.
        $sourceX = $prev[$index];
        if ($sourceX >= 0) {
            $sourceY = $sourceX - $d;
            if ($sourceX < $n && $sourceY < $m) {
                $candidate = $sourceX + 1;
                if ($candidate > $best) {
                    $best = $candidate;
                }
            }
        }

        // Insert one character into S.
        $sourceX = $prev[$index + 1];
        if ($sourceX >= 0) {
            $sourceY = $sourceX - ($d + 1);
            if ($sourceY < $m && $sourceX > $best) {
                $best = $sourceX;
            }
        }

        if ($best < 0) {
            continue;
        }

        $y = $best - $d;

        // Matching characters require no operations.
        while ($best < $n && $y < $m && $S[$best] === $T[$y]) {
            ++$best;
            ++$y;
        }

        if ($best === $n && $y === $m) {
            echo "Yes\n";
            exit;
        }

        $curr[$index] = $best;
    }

    $prev = $curr;
}

echo "No\n";
