function primitiveRootLength(string $s): int
{
    $n = strlen($s);
    $pi = array_fill(0, $n, 0);

    for ($i = 1; $i < $n; ++$i) {
        $j = $pi[$i - 1];

        while ($j > 0 && $s[$i] !== $s[$j]) {
            $j = $pi[$j - 1];
        }

        if ($s[$i] === $s[$j]) {
            ++$j;
        }

        $pi[$i] = $j;
    }

    $period = $n - $pi[$n - 1];
    return ($n % $period === 0) ? $period : $n;
}

$t = (int) trim(fgets(STDIN));
$output = '';

for ($case = 0; $case < $t; ++$case) {
    $s = rtrim(fgets(STDIN));
    $x = rtrim(fgets(STDIN));
    $y = rtrim(fgets(STDIN));

    $sLength = strlen($s);

    $xZeros = substr_count($x, '0');
    $yZeros = substr_count($y, '0');
    $xOnes = strlen($x) - $xZeros;
    $yOnes = strlen($y) - $yZeros;

    $zeroDiff = $xZeros - $yZeros;
    $oneDiff = $xOnes - $yOnes;

    if ($oneDiff === 0) {
        $output .= ($zeroDiff === 0) ? "Yes\n" : "No\n";
        continue;
    }

    $numerator = -$zeroDiff * $sLength;

    if ($numerator % $oneDiff !== 0) {
        $output .= "No\n";
        continue;
    }

    $tLength = intdiv($numerator, $oneDiff);

    if ($tLength < 0) {
        $output .= "No\n";
        continue;
    }

    if ($tLength === 0) {
        $output .= "Yes\n";
        continue;
    }

    $rootLength = primitiveRootLength($s);
    $output .= ($tLength % $rootLength === 0) ? "Yes\n" : "No\n";
