        ++$inputIndex;
    }

    $value = 0;
    while ($inputIndex < $inputLength) {
        $c = ord($input[$inputIndex]);
        if ($c < 48 || $c > 57) {
            break;
        }
        $value = $value * 10 + ($c - 48);
        ++$inputIndex;
    }

    return $value;
}

function gcdInt(int $a, int $b): int
{
    while ($b !== 0) {
        $t = $a % $b;
        $a = $b;
        $b = $t;
    }
    return $a;
}

/**
 * Returns sum_{i=0}^{n-1} floor((a*i+b)/m).
 */
function floorSum(int $n, int $m, int $a, int $b): int
{
    $answer = 0;

    while (true) {
        if ($a >= $m) {
            $quotient = intdiv($a, $m);
            if (($n & 1) === 0) {
                $triangle = intdiv($n, 2) * ($n - 1);
            } else {
                $triangle = $n * intdiv($n - 1, 2);
            }
            $answer += $triangle * $quotient;
            $a %= $m;
        }

        if ($b >= $m) {
            $answer += $n * intdiv($b, $m);
            $b %= $m;
        }

        $yMax = $a * $n + $b;
        if ($yMax < $m) {
            break;
        }

        $n = intdiv($yMax, $m);
        $b = $yMax % $m;

        $tmp = $m;
        $m = $a;
        $a = $tmp;
    }

    return $answer;
}

function bigFromInt(int $value): array
{
    if ($value === 0) {
        return [0];
    }

    $result = [];
    while ($value > 0) {
        $result[] = $value % BIG_BASE;
        $value = intdiv($value, BIG_BASE);
    }
    return $result;
}

function bigMultiplySmall(array $value, int $multiplier): array
{
    if ($multiplier === 0) {
        return [0];
    }

    $result = [];
    $carry = 0;
    $length = count($value);

    for ($i = 0; $i < $length; ++$i) {
        $current = $value[$i] * $multiplier + $carry;
        $result[] = $current % BIG_BASE;
        $carry = intdiv($current, BIG_BASE);
    }

    while ($carry > 0) {
        $result[] = $carry % BIG_BASE;
        $carry = intdiv($carry, BIG_BASE);
    }

    return $result;
}

function bigSubtract(array $a, array $b): array
{
    $result = [];
    $borrow = 0;
    $length = count($a);

    for ($i = 0; $i < $length; ++$i) {
        $current = $a[$i] - ($b[$i] ?? 0) - $borrow;
        if ($current < 0) {
            $current += BIG_BASE;
            $borrow = 1;
        } else {
            $borrow = 0;
        }
        $result[] = $current;
    }

    while (count($result) > 1 && $result[count($result) - 1] === 0) {
        array_pop($result);
    }

    return $result;
}

function bigToInt(array $value): int
{
    $result = 0;
    for ($i = count($value) - 1; $i >= 0; --$i) {
        $result = $result * BIG_BASE + $value[$i];
    }
    return $result;
}

/**
 * Returns sum_{i=0}^{n-1} (a*i mod m).
 */
function modularPrefixSum(int $n, int $m, int $a, int $floorValue): int
{
    if (($n & 1) === 0) {
        $triangle = intdiv($n, 2) * ($n - 1);
    } else {
        $triangle = $n * intdiv($n - 1, 2);
    }

    $raw = bigMultiplySmall(bigFromInt($triangle), $a);
    $removed = bigMultiplySmall(bigFromInt($floorValue), $m);
    return bigToInt(bigSubtract($raw, $removed));
}

$N = nextInt();
$M = nextInt();
$C = nextInt();
$K = nextInt();

$points = [];
for ($i = 0; $i < $N; ++$i) {
    $a = nextInt();
    $points[] = ($a === 0) ? 0 : ($M - $a);
}

sort($points, SORT_NUMERIC);

$uniquePoints = [];
$previous = -1;
foreach ($points as $point) {
    if ($point !== $previous) {
        $uniquePoints[] = $point;
        $previous = $point;
    }
}
$points = $uniquePoints;
$pointCount = count($points);

$g = gcdInt($C, $M);
$reducedMod = intdiv($M, $g);
$reducedStep = intdiv($C, $g);

$cycles = intdiv($K, $reducedMod);
$remainder = $K % $reducedMod;

$floorPrefix = floorSum($remainder, $reducedMod, $reducedStep, 0);
$prefixResidueSum = modularPrefixSum(
    $remainder,
    $reducedMod,
    $reducedStep,
    $floorPrefix
);

$cycleResidueSum = intdiv($reducedMod * ($reducedMod - 1), 2);
$sumX = $cycles * ($cycleResidueSum * $g) + $prefixResidueSum * $g;

$lastPoint = $points[$pointCount - 1];
$initialValue = ($points[0] === 0) ? 0 : ($M - $lastPoint);

$jumpSum = 0;

for ($i = 0; $i < $pointCount; ++$i) {
    $point = $points[$i];
    if ($point === 0) {
        continue;
    }

    if ($i === 0) {
        $gap = $point + $M - $lastPoint;
    } else {
        $gap = $point - $points[$i - 1];
    }

    $threshold = intdiv($point + $g - 1, $g);

    $fullCycleCount = $reducedMod - $threshold;
    $prefixCount = floorSum(
        $remainder,
        $reducedMod,
        $reducedStep,
        $reducedMod - $threshold
    ) - $floorPrefix;

    $countAtOrAbove = $cycles * $fullCycleCount + $prefixCount;
    $jumpSum += $gap * $countAtOrAbove;
}

$answer = $sumX + $K * $initialValue - $jumpSum;
echo $answer, PHP_EOL;
