function rectangleIsGood(int $left, int $right, array &$y, array &$prefixMin): bool
{
    $upper = $y[$left];
    $lower = $y[$right];
    $minimum = PHP_INT_MAX;

    for ($i = $left + 1; $i < $right; ++$i) {
        $value = $y[$i];
        if ($lower < $value && $value < $upper) {
            $prefixMin[$i] = $minimum;
            if ($value < $minimum) {
                $minimum = $value;
            }
        }
    }

    $maximum = 0;
    for ($i = $right - 1; $i > $left; --$i) {
        $value = $y[$i];
        if ($lower < $value && $value < $upper) {
            if ($prefixMin[$i] > $value && $maximum < $value) {
                return false;
            }
            if ($value > $maximum) {
                $maximum = $value;
            }
        }
    }

    return true;
}

