function lowerBound(array &$values, int $size, int $target): int
{
    $left = 0;
    $right = $size;

    while ($left < $right) {
        $mid = ($left + $right) >> 1;
        if ($values[$mid] < $target) {
            $left = $mid + 1;
        } else {
            $right = $mid;
        }
    }

    return $left;
}

function fenwickAdd(
    array &$countTree,
    array &$sumTree,
    int $size,
    int $index,
    int $value
): void {
    for ($i = $index; $i <= $size; $i += $i & (-$i)) {
        $countTree[$i]++;
        $sumTree[$i] += $value;
    }
}

function sumOfSmallest(
    array &$countTree,
    array &$sumTree,
    array &$coordinates,
    int $size,
    int $highestBit,
    int $k
): int {
    if ($k <= 0) {
        return 0;
    }

    $index = 0;
    $count = 0;
    $sum = 0;

    for ($step = $highestBit; $step > 0; $step >>= 1) {
        $next = $index + $step;
