            $maximumCurrent = min($blockerCount, $groupSize);

            $currentPenalty = 0;
            $minimumPenalty = PHP_INT_MAX;

            for ($q = 1; $q <= $maximumCurrent; $q++) {
                $cost = $costs[$start + $q - 1];
                $currentPenalty += max($cost, $reward);

                if ($q >= $minimumCurrent) {
                    $neededHigher = $blockerCount - $q;
                    $higherPenalty = sumOfSmallest(
                        $countTree,
                        $sumTree,
                        $coordinates,
                        $treeSize,
                        $highestBit,
                        $neededHigher
                    );

                    $penalty = $currentPenalty + $higherPenalty;
                    if ($penalty < $minimumPenalty) {
                        $minimumPenalty = $penalty;
                    }
                }
            }

            $candidate = $baseValue - $minimumPenalty;
            if ($candidate > $best) {
                $best = $candidate;
            }
