            $coordinateIndex = lowerBound($coordinates, $treeSize, $cost) + 1;
            fenwickAdd($countTree, $sumTree, $treeSize, $coordinateIndex, $cost);

            $net = $rewards[$i] - $cost;
            if ($net > 0) {
                $processedPositive += $net;
            }
        }

        $higherCount += $groupSize;
        $start = $end;
    }

    $output .= $best . "\n";

    unset(
        $rewards,
        $costs,
        $coordinates,
        $countTree,
        $sumTree
    );
}

