// Modular inverses of 1..M.
$inverse = array_fill(0, $M + 1, 0);
$inverse[1] = 1;
for ($x = 2; $x <= $M; ++$x) {
    $inverse[$x] = MOD - (
        (intdiv(MOD, $x) * $inverse[MOD % $x]) % MOD
    );
