    $value = $B[$k - 1];

    if ($value === -1) {
        --$rightUnknowns;

        for ($x = 0; $x <= $M; ++$x) {
            $leftPower[$x] = ($leftPower[$x] * $x) % MOD;
        }

        for ($x = 1; $x <= $M; ++$x) {
            $rightPower[$x] = ($rightPower[$x] * $inverse[$x]) % MOD;
        }
        $rightPower[0] = ($rightUnknowns === 0) ? 1 : 0;
    } elseif ($value < $prefixFixedMin) {
        $prefixFixedMin = $value;
    }

    $suffixFixedMax = $suffixMax[$k];
    $start = max(1, $suffixFixedMax);
    $end = min($M, $prefixFixedMin - 1);

    $cutWays = 0;

    for ($x = $start; $x <= $end; ++$x) {
        if ($suffixFixedMax > 0 && $x === $suffixFixedMax) {
            $rightWays = $rightPower[$x];
