$rankOfGroup = array_fill(0, $n + 1, 0);
$color = array_fill(0, $n + 1, 0);
$invalid = false;

for ($i = 0; $i < $n; $i++) {
    $rank = $A[$i];
    $group = intdiv($rank + 1, 2);

    $sourceOfIndex[$i] = $group;

    if ($rankOfGroup[$group] !== 0) {
        $invalid = true;
    } else {
        $rankOfGroup[$group] = $rank;
        $color[$group] = $rank & 1;
    }
}

$to = array_fill(0, $n + 1, 0);
$indegree = array_fill(0, $n + 1, 0);

for ($i = 0; $i < $n; $i++) {
    if ($B[$i] === -1) {
        continue;
    }

    $source = $sourceOfIndex[$i];
    $target = intdiv($B[$i] + 1, 2);
    $aRank = $rankOfGroup[$target];

    if ($aRank === 0) {
        $invalid = true;
    } else {
        $complement = (($aRank & 1) === 1) ? $aRank + 1 : $aRank - 1;
        if ($B[$i] !== $complement) {
            $invalid = true;
        }
    }

    if ($to[$source] !== 0 || $indegree[$target] !== 0) {
        $invalid = true;
    } else {
        $to[$source] = $target;
        $indegree[$target] = 1;
    }
}

if ($invalid) {
    echo "0\n";
    exit;
}

$visited = array_fill(0, $n + 1, false);
$oddComponents = 0;
$evenComponents = 0;
$mixedComponents = 0;

/* Open path components. */
for ($start = 1; $start <= $n; $start++) {
    if ($indegree[$start] !== 0) {
        continue;
    }

    $hasOdd = false;
    $hasEven = false;
    $cur = $start;

    while ($cur !== 0 && !$visited[$cur]) {
        $visited[$cur] = true;

        if ($color[$cur] === 1) {
            $hasOdd = true;
        } else {
            $hasEven = true;
        }

        $cur = $to[$cur];
    }

    if ($hasOdd && $hasEven) {
        $mixedComponents++;
    } elseif ($hasOdd) {
        $oddComponents++;
    } else {
        $evenComponents++;
    }
