 * Build a maximum Cartesian tree.
 * Equal values are not popped, so equal-valued connected nodes can later
 * be contracted into one component.
 */
$parent = array_fill(0, $n, -1);
$stack = [];
$top = -1;

for ($i = 0; $i < $n; ++$i) {
    $last = -1;

    while ($top >= 0 && $a[$stack[$top]] < $a[$i]) {
        $last = $stack[$top];
        --$top;
    }

    if ($top >= 0) {
        $parent[$i] = $stack[$top];
    }

    if ($last !== -1) {
        $parent[$last] = $i;
    }

    $stack[++$top] = $i;
}
unset($stack);

/*
 * Contract Cartesian-tree edges whose endpoints have equal values.
 * uf[i] points toward the representative of i's contracted component.
 */
$uf = array_fill(0, $n, 0);
for ($i = 0; $i < $n; ++$i) {
    $p = $parent[$i];
    if ($p >= 0 && $a[$p] === $a[$i]) {
        $uf[$i] = $p;
    } else {
        $uf[$i] = $i;
    }
}

/* Path compression. */
for ($i = 0; $i < $n; ++$i) {
    $x = $i;
    while ($uf[$x] !== $x) {
        $x = $uf[$x];
    }
    $root = $x;

    $x = $i;
    while ($uf[$x] !== $x) {
        $next = $uf[$x];
        $uf[$x] = $root;
        $x = $next;
    }
}

/*
 * Build the contracted component tree.
 * total[v] initially stores the sum of vertices belonging directly to v.
 */
$total = array_fill(0, $n, 0);
for ($i = 0; $i < $n; ++$i) {
    $total[$uf[$i]] += $a[$i];
}

$childCount = array_fill(0, $n, 0);

for ($i = 0; $i < $n; ++$i) {
    if ($uf[$i] !== $i) {
        continue;
    }

    $p = $parent[$i];
    if ($p >= 0) {
        $parent[$i] = $uf[$p];
        ++$childCount[$parent[$i]];
    } else {
        $parent[$i] = -1;
    }
}

/*
 * Accumulate subtree sums from leaves toward the root.
 * The queue also gives a child-before-parent topological order.
 */
$queue = [];
$qt = 0;

for ($i = 0; $i < $n; ++$i) {
    if ($uf[$i] === $i && $childCount[$i] === 0) {
        $queue[$qt++] = $i;
    }
}

$qh = 0;
while ($qh < $qt) {
    $v = $queue[$qh++];
    $p = $parent[$v];

    if ($p >= 0) {
        $total[$p] += $total[$v];
        --$childCount[$p];

        if ($childCount[$p] === 0) {
            $queue[$qt++] = $p;
        }
    }
}

/*
 * Reuse childCount as the final reachable component.
 * Process parents before children by reversing the previous order.
 */
for ($i = $qt - 1; $i >= 0; --$i) {
    $v = $queue[$i];
    $p = $parent[$v];

    if ($p >= 0 && $a[$p] < $total[$v]) {
        $childCount[$v] = $childCount[$p];
    } else {
        $childCount[$v] = $v;
    }
}

$out = '';

for ($i = 0; $i < $n; ++$i) {
    $canStart =
        ($i > 0 && $a[$i - 1] < $a[$i]) ||
        ($i + 1 < $n && $a[$i + 1] < $a[$i]);

    if ($canStart) {
        $component = $uf[$i];
        $answer = $total[$childCount[$component]];
    } else {
        $answer = $a[$i];
    }

    if ($i > 0) {
        $out .= ' ';
    }
    $out .= (string)$answer;
}

echo $out, PHP_EOL;
?>
